_TERMINAL_ENTRY_NO_FILL_COMMAND_STATES = frozenset({
    CommandState.CANCELLED.value,
    CommandState.EXPIRED.value,
    CommandState.SUBMIT_REJECTED.value,
    CommandState.REJECTED.value,
})
_TERMINAL_ENTRY_NO_FILL_EVENT_TYPES = frozenset({
    "CANCEL_ACKED",
    "EXPIRED",
    "REVIEW_CLEARED_NO_VENUE_EXPOSURE",
    CommandEventType.REVIEW_CLEARED_NO_VENUE_SIDE_EFFECT.value,
    "SUBMIT_REJECTED",
})
_SETTLEMENT_ABSORBED_ENTRY_COMMAND_STATES = frozenset({
    CommandState.FILLED.value,
    CommandState.CANCELLED.value,
    CommandState.EXPIRED.value,
})


def _order_fact_proof_rank_sql(alias: str) -> str:
    return f"""
        CASE
            WHEN UPPER(COALESCE({alias}.state, '')) IN ('PARTIALLY_MATCHED', 'PARTIAL')
                 AND CAST(COALESCE({alias}.matched_size, '0') AS REAL) > 0
                 AND CAST(COALESCE({alias}.remaining_size, '0') AS REAL) = 0
                 AND json_valid({alias}.raw_payload_json)
                 AND json_extract({alias}.raw_payload_json, '$.proof_class')
                     = 'terminal_partial_order_fact'
            THEN 650
            WHEN UPPER(COALESCE({alias}.state, '')) IN ('MATCHED', 'FILLED')
                 AND CAST(COALESCE({alias}.matched_size, '0') AS REAL) > 0
                 AND CAST(COALESCE({alias}.remaining_size, '0') AS REAL) = 0
            THEN 600
            WHEN UPPER(COALESCE({alias}.state, '')) IN ('CANCEL_CONFIRMED', 'EXPIRED', 'VENUE_WIPED')
                 AND CAST(COALESCE({alias}.matched_size, '0') AS REAL) > 0
            THEN 550
            WHEN UPPER(COALESCE({alias}.state, '')) IN ('PARTIALLY_MATCHED', 'PARTIAL')
                 AND CAST(COALESCE({alias}.matched_size, '0') AS REAL) > 0
            THEN 400
            WHEN UPPER(COALESCE({alias}.state, '')) IN ('CANCEL_CONFIRMED', 'EXPIRED', 'VENUE_WIPED')
                 AND CAST(COALESCE({alias}.matched_size, '0') AS REAL) = 0
            THEN 300
            WHEN UPPER(COALESCE({alias}.state, '')) IN ('LIVE', 'OPEN', 'RESTING')
            THEN 200
            ELSE 100
        END
    """


def _canonical_order_truth_cte(
    *,
    cte_name: str = "canonical_order_truth",
    partition_by_venue_order: bool = False,
    command_scope_cte: str | None = None,
) -> str:
    """SQL CTE that prevents weaker later order facts from demoting truth.

    Recovery used to treat ``MAX(local_sequence)`` as authority. That is unsafe
    when a later RESTING/PARTIAL observation arrives after an earlier terminal
    fill/no-fill proof. The reducer ranks proof strength first, recency second.
    """

    partition = "command_id, venue_order_id" if partition_by_venue_order else "command_id"
    command_scope_join = (
        f"JOIN {command_scope_cte} scope ON scope.command_id = fact.command_id"
        if command_scope_cte
        else ""
    )
    proof_rank = _order_fact_proof_rank_sql("fact")
    return f"""
        {cte_name} AS (
            SELECT ranked.*
              FROM (
                    SELECT scored.*,
                           ROW_NUMBER() OVER (
                               PARTITION BY {partition}
                               ORDER BY proof_rank DESC, local_sequence DESC
                           ) AS canonical_rank
                      FROM (
                            SELECT fact.*,
                                   {proof_rank} AS proof_rank
                              FROM venue_order_facts fact
                              {command_scope_join}
                           ) scored
                   ) ranked
             WHERE ranked.canonical_rank = 1
        )
    """


def _canonical_trade_fact_cte(
    cte_name: str = "canonical_trade_fact",
    *,
    source_clause_sql: str = "",
) -> str:
    """SQL CTE that prevents weaker later trade facts from hiding fills."""

    return f"""
        {cte_name} AS (
            SELECT ranked.*
              FROM (
                    SELECT scored.*,
                           ROW_NUMBER() OVER (
                               PARTITION BY command_id, trade_id
                               ORDER BY proof_rank DESC, local_sequence DESC
                           ) AS canonical_rank
                      FROM (
                            SELECT fact.*,
                                   CASE
                                       WHEN UPPER(COALESCE(fact.state, '')) = 'CONFIRMED'
                                            AND CAST(COALESCE(fact.filled_size, '0') AS REAL) > 0
                                       THEN 500
                                       WHEN UPPER(COALESCE(fact.state, '')) = 'MINED'
                                            AND CAST(COALESCE(fact.filled_size, '0') AS REAL) > 0
                                       THEN 450
                                       WHEN UPPER(COALESCE(fact.state, '')) = 'MATCHED'
                                            AND CAST(COALESCE(fact.filled_size, '0') AS REAL) > 0
                                       THEN 400
                                       WHEN CAST(COALESCE(fact.filled_size, '0') AS REAL) > 0
                                       THEN 300
                                       ELSE 100
                                   END AS proof_rank
                              FROM venue_trade_facts fact
                              {source_clause_sql}
                           ) scored
                   ) ranked
             WHERE ranked.canonical_rank = 1
        )
    """


def _economic_trade_fact_cte(
    *,
    canonical_cte_name: str = "canonical_trade_fact",
    cte_name: str = "economic_trade_fact",
) -> str:
    """Return one row per economic fill, excluding derived aliases."""

    return f"""
        {cte_name} AS (
            SELECT fact.*
              FROM {canonical_cte_name} fact
             WHERE NOT (
                    TRIM(COALESCE(fact.tx_hash, '')) != ''
                AND LOWER(TRIM(COALESCE(fact.trade_id, '')))
                    = LOWER(TRIM(fact.tx_hash))
                AND EXISTS (
                        SELECT 1
                          FROM {canonical_cte_name} exact
                         WHERE exact.command_id = fact.command_id
                           AND LOWER(TRIM(COALESCE(exact.tx_hash, '')))
                               = LOWER(TRIM(fact.tx_hash))
                           AND LOWER(TRIM(COALESCE(exact.trade_id, '')))
                               != LOWER(TRIM(COALESCE(fact.trade_id, '')))
                           AND UPPER(COALESCE(exact.state, ''))
                               IN ('MATCHED', 'MINED', 'CONFIRMED')
                           AND CAST(COALESCE(exact.filled_size, '0') AS REAL) > 0
                    )
                )
               AND NOT EXISTS (
                       SELECT 1
                         FROM venue_trade_facts source_fact
                        WHERE source_fact.trade_fact_id = CASE
                                  WHEN json_valid(fact.raw_payload_json)
                                  THEN CAST(json_extract(
                                      fact.raw_payload_json,
                                      '$.raw_fill_payload.source_trade_fact_id'
                                  ) AS INTEGER)
                              END
                          AND source_fact.command_id = fact.command_id
                          AND source_fact.venue_order_id = fact.venue_order_id
                          AND UPPER(COALESCE(source_fact.state, ''))
                              IN ('MATCHED', 'MINED', 'CONFIRMED')
                          AND CAST(COALESCE(source_fact.filled_size, '0') AS REAL) > 0
                    )
        )
    """


class MissingPositionCurrentForTerminalOrder(ValueError):
    """Raised when terminal order facts arrive before the entry projection."""


def _now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _parse_ts(value: str) -> Optional[datetime]:
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed


def _age_seconds(cmd: VenueCommand, *, now: datetime) -> float | None:
    started_at = _parse_ts(cmd.updated_at) or _parse_ts(cmd.created_at)
    if started_at is None:
        return None
    return (now - started_at).total_seconds()


def _venue_order_payload(value: object | None) -> dict | None:
    """Normalize live adapter order objects to a JSON-safe venue payload."""

    if value is None:
        return None
    if isinstance(value, Mapping):
        payload = dict(value)
    else:
        raw = getattr(value, "raw", None)
        if isinstance(raw, Mapping):
            payload = dict(raw)
        else:
            payload = dict(getattr(value, "__dict__", {}) or {})
    status = getattr(value, "status", None)
    if status not in (None, "") and not (payload.get("status") or payload.get("state")):
        payload["status"] = str(status)
    order_id = getattr(value, "order_id", None)
    if order_id not in (None, "") and not _extract_order_id(payload):
        payload["orderID"] = str(order_id)
    if not (_extract_order_id(payload) or payload.get("status") or payload.get("state")):
        return None
    return payload


def _extract_order_id(venue_resp: dict | None, fallback: str | None = None) -> str | None:
    if not isinstance(venue_resp, dict):
        return fallback
    return (
        venue_resp.get("orderID")
        or venue_resp.get("orderId")
        or venue_resp.get("order_id")
        or venue_resp.get("id")
        or fallback
    )


def _order_status(raw: dict) -> str:
    status = str(
        raw.get("_venue_order_status")
        or raw.get("status")
        or raw.get("state")
        or ""
    ).strip().upper()
    if status.startswith("ORDER_STATUS_"):
        status = status.removeprefix("ORDER_STATUS_")
    return {
        "CANCELED_MARKET_RESOLVED": "CANCELED",
        "INVALID": "REJECTED",
    }.get(status, status)


def _order_matched_size(raw: dict) -> str:
    if (
        raw.get("_venue_response_contract")
        == "POLYMARKET_CLOB_V2_FIXED_6_POINT_ORDER"
    ):
        return str(raw.get("_v2_matched_size") or "0")
    value = (
        raw.get("matched_size")
        or raw.get("size_matched")
        or raw.get("matched")
        or raw.get("matched_amount")
        or raw.get("filled_size")
        or "0"
    )
    return str(value)


def _order_original_size(raw: dict) -> object:
    if (
        raw.get("_venue_response_contract")
        == "POLYMARKET_CLOB_V2_FIXED_6_POINT_ORDER"
    ):
        return raw.get("_v2_original_size")
    return raw.get("size") or raw.get("original_size") or raw.get("matched_amount")


def _explicit_point_order_matched_size(point_order: dict | None) -> str | None:
    """Matched/filled size only when the venue point-order payload says it explicitly.

    Do not infer from making/taking amounts here: for canceled/expired orders those
    fields can describe original order amounts, not executed exposure. Terminal
    no-fill release needs a positive zero-fill proof, not a default.
    """

    if (
        _first_present(point_order, "_venue_response_contract")
        == "POLYMARKET_CLOB_V2_FIXED_6_POINT_ORDER"
    ):
        value = _first_present(point_order, "_v2_matched_size")
        return str(value) if value not in (None, "") else None
    value = _first_present(
        point_order,
        "matched_size",
        "matchedSize",
        "size_matched",
        "sizeMatched",
        "matched",
        "matched_amount",
        "matchedAmount",
        "filled_size",
        "filledSize",
    )
    if value in (None, ""):
        return None
    return str(value)


def _canonical_positive_order_fact_exists(
    conn: sqlite3.Connection,
    *,
    command_id: str,
    venue_order_id: str,
) -> bool:
    """Return whether canonical order truth already proves a positive fill."""

    if not command_id or not venue_order_id:
        return False
    rows = conn.execute(
        """
        SELECT matched_size
          FROM venue_order_facts
         WHERE command_id = ?
           AND venue_order_id = ?
        """,
        (command_id, venue_order_id),
    ).fetchall()
    return any(_is_positive_decimal(row[0]) for row in rows)


def _terminal_point_order_zero_fill_proven(
    conn: sqlite3.Connection,
    *,
    command_id: str,
    point_order: dict | None,
) -> tuple[bool, str]:
    """Return whether a terminal venue point-order proves zero fill.

    A terminal venue status alone is not enough: CLOB orders can be canceled or
    expire after partial matching. We release duplicate locks only when the point
    order explicitly reports matched/filled size == 0 and both local trade facts
    and point-order trade ids are absent.
    """

    matched_size = _explicit_point_order_matched_size(point_order)
    if matched_size is None:
        return False, "terminal_matched_size_missing"
    if not _decimal_is_zero(matched_size):
        return False, "terminal_matched_size_positive_or_invalid"
    venue_order_id = _extract_order_id(point_order or {})
    if _canonical_positive_order_fact_exists(
        conn,
        command_id=command_id,
        venue_order_id=venue_order_id,
    ):
        return False, "terminal_positive_order_fact_exists"
    if _fill_trade_fact_count(conn, command_id) > 0:
        return False, "terminal_positive_trade_fact_exists"
    if _point_order_trade_ids(point_order):
        return False, "terminal_point_order_trade_ids_present"
    return True, "terminal_zero_fill_proven"


def _is_positive_decimal(value: object) -> bool:
    try:
        parsed = Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError):
        return False
    return parsed.is_finite() and parsed > 0


def _lookup_unknown_side_effect_order(
    conn: sqlite3.Connection,
    cmd: VenueCommand,
    client,
) -> tuple[str, dict | None, dict | None, str]:
    """Return (status, venue_response, proof, lookup_method).

    status is one of ``found`` or ``unavailable``.  A ``found`` status with a
    ``None`` response means the complete authenticated orders+trades read found
    no matching exposure, allowing the age-gated safe-replay path below to
    terminalize the command. An idempotency-key miss alone is only corroboration
    and never supplies that absence proof.
    """

    point_read = None
    point_error_type = None
    if cmd.venue_order_id:
        try:
            point_read = _client_point_order_read(client, cmd.venue_order_id)
        except Exception as exc:  # noqa: BLE001
            point_error_type = exc.__class__.__name__
            logger.warning(
                "recovery: command %s authenticated point-order read failed (%s); "
                "falling back to complete authenticated venue reads",
                cmd.command_id,
                point_error_type,
            )
        else:
            if point_read.point_order is not None:
                return "found", point_read.point_order, None, "venue_order_id"
    finder = getattr(client, "find_order_by_idempotency_key", None)
    if not cmd.venue_order_id and callable(finder):
        try:
            found = finder(cmd.idempotency_key.value)
        except Exception as exc:  # noqa: BLE001
            if exc.__class__.__name__ != "SnapshotMissError":
                raise
        else:
            if found is not None:
                payload = _venue_order_payload(found)
                if payload is not None:
                    return "found", payload, None, "idempotency_key"
                logger.warning(
                    "recovery: command %s idempotency-key lookup returned non-order %s; "
                    "treating lookup as unavailable",
                    cmd.command_id,
                    type(found).__name__,
                )
                return "unavailable", None, None, "idempotency_key"
            logger.info(
                "recovery: command %s idempotency-key lookup found no order; "
                "corroborating with complete authenticated venue reads",
                cmd.command_id,
            )
    venue_status, venue_resp, proof = _lookup_unknown_side_effect_by_venue_reads(
        cmd, client
    )
    if proof is not None and cmd.venue_order_id:
        proof = {
            **proof,
            "point_order_checked": True,
            "point_order_query_complete": bool(
                point_read is not None and point_read.query_complete
            ),
            "point_order_absent": bool(point_read is not None and point_read.absent),
            "point_order_source": (
                point_read.source if point_read is not None else None
            ),
            "point_order_absence_reason": (
                point_read.absence_reason if point_read is not None else None
            ),
            "point_order_error_type": point_error_type,
            "venue_order_id": cmd.venue_order_id,
        }
    if (
        venue_status == "unavailable"
        and proof is not None
        and point_read is not None
        and point_read.query_complete
        and point_read.absent
        and proof.get("open_orders_query_complete") is True
        and proof.get("trades_query_complete") is True
        and int(proof.get("matching_trade_count") or 0) == 0
    ):
        detached = _detached_terminal_ghost_open_orders(
            conn,
            current_command=cmd,
            matching_open_orders=proof.get("matching_open_orders") or (),
        )
        if detached is not None:
            proof = {
                **proof,
                "current_submit_exact_order_absent": True,
                "matching_open_orders_detached_from_current_submit": detached,
                "effective_current_submit_matching_open_order_count": 0,
            }
            return "found", None, proof, "authenticated_exact_absence_detached_ghost"
    return venue_status, venue_resp, proof, "authenticated_venue_absence"


def _client_read_items(client, method_name: str) -> SimpleNamespace:
    adapter_factory = getattr(client, "_ensure_v2_adapter", None)
    if callable(adapter_factory):
        adapter = adapter_factory()
        adapter_reader = getattr(adapter, method_name, None)
        if callable(adapter_reader):
            return SimpleNamespace(
                items=list(adapter_reader() or []),
                query_complete=True,
                pagination_scope=f"{adapter.__class__.__name__}.{method_name}:all_pages",
            )
    reader = getattr(client, method_name, None)
    if callable(reader):
        query_complete = bool(
            getattr(client, "venue_reads_are_complete", False)
            or getattr(reader, "venue_reads_are_complete", False)
        )
        return SimpleNamespace(
            items=list(reader() or []),
            query_complete=query_complete,
            pagination_scope=(
                f"{client.__class__.__name__}.{method_name}:declared_complete"
                if query_complete
                else f"{client.__class__.__name__}.{method_name}:single_call_unverified"
            ),
        )
    raise AttributeError(f"client does not expose {method_name}")


def _client_point_order_read(client, order_id: str) -> SimpleNamespace:
    """Return one authenticated point-order result or an incomplete proof.

    ``None`` is never absence authority.  The live V2 adapter reports an exact
    authenticated HTTP 404 as ``VenueOrderNotFound``; test/fake clients must
    explicitly declare the same complete point-read contract.
    """

    declared_complete = False
    adapter_factory = getattr(client, "_ensure_v2_adapter", None)
    if callable(adapter_factory):
        source = adapter_factory()
        reader = getattr(source, "get_order", None)
        authenticated = bool(
            callable(reader)
            and getattr(source, "authenticated_point_reads_are_complete", False)
        )
    else:
        source = client
        reader = getattr(client, "get_order", None)
        declared_complete = bool(
            getattr(client, "authenticated_point_reads_are_complete", False)
            or getattr(reader, "authenticated_point_reads_are_complete", False)
        )
        authenticated = declared_complete
    source_name = f"{source.__class__.__name__}.get_order"
    if not callable(reader) or not authenticated:
        return SimpleNamespace(
            point_order=None,
            absent=False,
            query_complete=False,
            source=f"{source_name}:unverified",
            order_id=str(order_id),
            absence_reason=None,
        )
    try:
        value = reader(str(order_id))
    except VenueOrderNotFound:
        return SimpleNamespace(
            point_order=None,
            absent=True,
            query_complete=True,
            source=f"{source_name}:authenticated_http_404",
            order_id=str(order_id),
            absence_reason="authenticated_order_404",
        )
    if value is None and declared_complete:
        return SimpleNamespace(
            point_order=None,
            absent=True,
            query_complete=True,
            source=f"{source_name}:declared_authenticated_absence",
            order_id=str(order_id),
            absence_reason="declared_authenticated_order_absence",
        )
    payload = _venue_order_payload(value)
    if payload is None or str(_extract_order_id(payload) or "") != str(order_id):
        return SimpleNamespace(
            point_order=None,
            absent=False,
            query_complete=False,
            source=f"{source_name}:malformed_or_identity_mismatch",
            order_id=str(order_id),
            absence_reason=None,
        )
    return SimpleNamespace(
        point_order=payload,
        absent=False,
        query_complete=True,
        source=f"{source_name}:authenticated_point_order",
        order_id=str(order_id),
        absence_reason=None,
    )


def _command_mapping(cmd: VenueCommand) -> dict:
    return {
        "command_id": cmd.command_id,
        "decision_id": cmd.decision_id,
        "market_id": cmd.market_id,
        "token_id": cmd.token_id,
        "side": cmd.side,
        "price": cmd.price,
        "size": cmd.size,
        "created_at": cmd.created_at,
    }


def _raw_matches_command_order_identity(raw: dict, command: dict) -> bool:
    token_id = str(command.get("token_id") or "")
    if not token_id or not _raw_mentions_token(raw, token_id):
        return False
    raw_side = str(raw.get("side") or "").upper()
    side = str(command.get("side") or "").upper()
    if raw_side and side and raw_side != side:
        return False
    if not _decimal_matches(raw.get("price"), command.get("price")):
        return False
    raw_size = _order_original_size(raw)
    return _decimal_matches(raw_size, command.get("size"))


def _lookup_unknown_side_effect_by_venue_reads(
    cmd: VenueCommand,
    client,
) -> tuple[str, dict | None, dict | None]:
    try:
        open_read = _client_read_items(client, "get_open_orders")
        trade_read = _client_read_items(client, "get_trades")
    except Exception as exc:
        logger.warning(
            "recovery: command %s authenticated venue absence read unavailable: %s",
            cmd.command_id, exc,
        )
        return "unavailable", None, None
    open_orders = open_read.items
    trades = trade_read.items

    command = _command_mapping(cmd)
    created_epoch = _epoch_seconds(cmd.created_at) or 0.0
    matching_open = []
    exact_open = []
    for item in open_orders:
        raw = _raw_payload(item)
        if not _raw_matches_command_exposure(raw, command):
            continue
        matching_open.append(raw)
        if _raw_matches_command_order_identity(raw, command):
            exact_open.append(raw)

    matching_trades = []
    for item in trades:
        raw = _raw_payload(item)
        if not _raw_matches_command_exposure(raw, command):
            continue
        trade_epoch = _epoch_seconds(raw.get("match_time") or raw.get("last_update"))
        if trade_epoch is not None and trade_epoch < created_epoch:
            continue
        matching_trades.append(raw)

    proof = {
        "schema_version": 1,
        "source": "authenticated_clob_user_read",
        "owner_scope": "authenticated_funder",
        "observed_at": _now_iso(),
        "command_id": cmd.command_id,
        "decision_id": cmd.decision_id,
        "market_id": cmd.market_id,
        "token_id": cmd.token_id,
        "side": cmd.side,
        "price": str(Decimal(str(cmd.price))),
        "size": str(Decimal(str(cmd.size))),
        "open_orders_checked": True,
        "trades_checked": True,
        "open_orders_query_complete": bool(open_read.query_complete),
        "trades_query_complete": bool(trade_read.query_complete),
        "pagination_scope": {
            "open_orders": open_read.pagination_scope,
            "trades": trade_read.pagination_scope,
        },
        "time_window_start": cmd.created_at,
        "time_window_end": _now_iso(),
        "open_order_count": len(open_orders),
        "trade_count": len(trades),
        "matching_open_order_count": len(matching_open),
        "matching_trade_count": len(matching_trades),
        "matching_open_orders": [_summarize_venue_match(raw) for raw in matching_open[:10]],
        "matching_trades": [_summarize_venue_match(raw) for raw in matching_trades[:10]],
    }

    if len(exact_open) == 1:
        payload = dict(exact_open[0])
        payload.setdefault("status", payload.get("state") or "LIVE")
        return "found", payload, proof
    if matching_open or matching_trades:
        return "unavailable", None, proof
    if not (open_read.query_complete and trade_read.query_complete):
        return "unavailable", None, proof
    return "found", None, proof


_PRE_SDK_COLLATERAL_REASON_MARKERS = (
    "pusd_allowance_insufficient",
    "pusd_insufficient",
    "collateral_snapshot_degraded",
    "collateral_snapshot_stale",
    "collateral_snapshot_future",
    "collateral_ledger_unconfigured",
    "ctf_allowance_insufficient",
    "ctf_tokens_insufficient",
)

_PRE_SDK_REVIEW_REQUIRED_REASONS = frozenset({
    "pre_submit_collateral_reservation_failed",
    # Legacy live rows before the 2026-05-15 fix could be left SUBMITTING
    # after pre-SDK collateral failure, then moved here by recovery.
    "recovery_no_venue_order_id",
})

_GEOBLOCK_403_MARKERS = (
    "status_code=403",
    "Trading restricted in your region",
    "geoblock",
)
def _dict_row(row) -> dict:
    if row is None:
        return {}
    try:
        return dict(row)
    except Exception:
        return {}


def _table_exists(conn: sqlite3.Connection, table: str) -> bool:
    row = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?",
        (table,),
    ).fetchone()
    return row is not None


def _attached_table_exists(conn: sqlite3.Connection, schema: str, table: str) -> bool:
    row = conn.execute(
        f"SELECT 1 FROM {schema}.sqlite_master WHERE type = 'table' AND name = ?",
        (table,),
    ).fetchone()
    return row is not None


def _table_has_columns(conn: sqlite3.Connection, table_ref: str, required: set[str]) -> bool:
    return required.issubset(_table_columns(conn, table_ref))


def _maybe_attach_world_for_recovery(conn: sqlite3.Connection) -> None:
    attached = {str(row[1]) for row in conn.execute("PRAGMA database_list").fetchall()}
    if "world" in attached:
        return
    main_path = ""
    for row in conn.execute("PRAGMA database_list").fetchall():
        if str(row[1]) == "main":
            main_path = str(row[2] or "")
            break
    if not main_path or Path(main_path).name != "zeus_trades.db":
        return
    try:
        from src.state.db import ZEUS_WORLD_DB_PATH

        if ZEUS_WORLD_DB_PATH.exists():
            conn.execute("ATTACH DATABASE ? AS world", (str(ZEUS_WORLD_DB_PATH),))
    except sqlite3.OperationalError:
        logger.debug("command recovery could not attach world DB", exc_info=True)


def _maybe_attach_forecasts_for_recovery(conn: sqlite3.Connection) -> None:
    attached = {str(row[1]) for row in conn.execute("PRAGMA database_list").fetchall()}
    if "forecasts" in attached:
        return
    main_path = ""
    for row in conn.execute("PRAGMA database_list").fetchall():
        if str(row[1]) == "main":
            main_path = str(row[2] or "")
            break
    if not main_path or Path(main_path).name != "zeus_trades.db":
        return
    try:
        from src.state.db import ZEUS_FORECASTS_DB_PATH

        if ZEUS_FORECASTS_DB_PATH.exists():
            conn.execute("ATTACH DATABASE ? AS forecasts", (str(ZEUS_FORECASTS_DB_PATH),))
    except sqlite3.OperationalError:
        logger.debug("command recovery could not attach forecasts DB", exc_info=True)


