# =============================================================================
# Abandoned never-submitted EDLI ghost reconcile (live_order_pathology 2026-06-22)
# =============================================================================
# A live decision can build an EDLI order aggregate all the way to
# ``ExecutionCommandCreated`` (the executor accepted the command INTERNALLY) and
# then be interrupted — daemon restart / SQLite lock — BEFORE the venue submit.
# The aggregate then stalls with NO subsequent event: no VenueSubmitAttempted, no
# SubmitRejected, no SubmitUnknown, no ack, no user event, no Reconciled. Its
# ``edli_live_order_projection.venue_order_id`` is NULL and there is ZERO
# ``venue_commands`` row for its execution_command_id — i.e. the order NEVER
# reached the venue and has $0 capital at risk.
#
# Such a ghost is NON-TERMINAL per ``event_reactor_adapter._TERMINAL_EVENT_SQL``,
# so ``_locked_live_opportunity_active_order_reason`` treats it as an ACTIVE order
# and permanently SUPPRESSES every new submit on the same weather family (the
# duplicate-suppression lock has no direction filter — a stuck buy_YES ghost
# blocks a live buy_NO on the same family forever). No other reconcile path
# terminalizes it: the SUBMIT_UNKNOWN reconcile (_reconcile_edli_pending_no_order_if_proven)
# requires ``pending_reconcile=1`` (a SubmitUnknown the ghost never reached), and
# ``append_reconciled`` requires venue-reconcile truth a never-submitted order
# has none of.
#
# The LEGAL terminalization (confirmed in live_order_aggregate._validate_event_append
# for event_type=="SubmitRejected") is a PRE-SUBMIT SubmitRejected appended directly
# after ExecutionCommandCreated WITHOUT a VenueSubmitAttempted: it is accepted iff
# ``_is_pre_submit_rejection_payload(payload)`` is True (pre_submit_rejection=True,
# submit_status="PRE_SUBMIT_ERROR", venue_call_started=False), the command-binding
# fields match the ExecutionCommandCreated event, and a non-empty reason_code is set.
# A SubmitRejected event makes the aggregate TERMINAL per _TERMINAL_EVENT_SQL, so the
# family duplicate lock RELEASES and the family re-enters the normal decision pipeline
# (still fully re-certified downstream — no gate bypassed).
#
# VENUE-TRUTH GUARD (money-path, fail-closed): a ghost is terminalized ONLY when
# the CURRENT command has NO venue presence whatsoever — venue_order_id IS NULL
# in the projection, NO venue_commands row for its execution_command_id, and
# NONE of {VenueSubmitAttempted, VenueSubmitAcknowledged, SubmitUnknown,
# UserOrderObserved, UserTradeObserved, SubmitRejected, Reconciled,
# CapTransitioned} events exist AFTER the current ExecutionCommandCreated. Older
# rejected attempts on the same aggregate do not prove venue presence for the
# current command. A real resting / filled / in-flight order is NEVER
# terminalized.

# The same safe-replay grace the SUBMIT_UNKNOWN path uses: an aggregate is only a
# terminalizable ghost once it has sat at ExecutionCommandCreated for longer than
# this window (a crash mid-cycle is normal; we never race a still-completing submit).
_ABANDONED_GHOST_GRACE_SECONDS = _SAFE_REPLAY_MIN_AGE_SECONDS

# Events that prove the aggregate progressed past the never-submitted boundary (any
# venue contact, any user-channel fact, or any later terminal/cap event). If ANY of
# these exist on the aggregate it is NOT a never-submitted ghost — fail closed.
_GHOST_DISQUALIFYING_EVENT_TYPES = (
    "VenueSubmitAttempted",
    "VenueSubmitAcknowledged",
    "SubmitUnknown",
    "UserOrderObserved",
    "UserTradeObserved",
    "SubmitRejected",
    "Reconciled",
    "CapTransitioned",
)


def _abandoned_unsubmitted_ghost_candidates(
    conn: sqlite3.Connection,
    *,
    events_ref: str,
    projection_ref: str,
    cutoff_iso: str,
) -> list[dict]:
    """Aggregates stalled at ExecutionCommandCreated that never reached the venue.

    Returns one row per ghost with its aggregate_id + execution_command_id (read
    from the latest ExecutionCommandCreated event payload). Strictly read-only.

    Predicates (ALL must hold):
      * projection current_state = EXECUTION_COMMAND_CREATED and last_event_type =
        ExecutionCommandCreated, with the joined command row matching
        projection.last_sequence (the aggregate's CURRENT event is the command);
      * projection.venue_order_id IS NULL;
      * the ExecutionCommandCreated event occurred before ``cutoff_iso`` (grace);
      * no disqualifying (venue / user / later-terminal / cap) event exists after
        the current command row — defense-in-depth even though current_state
        already implies it;
      * no venue_commands row links to the execution_command_id (decision_id key).
    """
    if not _table_exists(conn, "venue_commands"):
        logger.warning(
            "recovery: abandoned-unsubmitted-ghost pass skipped because "
            "venue_commands is not visible on this connection"
        )
        return []
    disqualifier_placeholders = ",".join("?" for _ in _GHOST_DISQUALIFYING_EVENT_TYPES)
    rows = conn.execute(
        f"""
        SELECT proj.aggregate_id AS aggregate_id,
               json_extract(cmd_ev.payload_json, '$.execution_command_id') AS execution_command_id,
               cmd_ev.occurred_at AS command_occurred_at
        FROM {projection_ref} proj
        JOIN {events_ref} cmd_ev
          ON cmd_ev.aggregate_id = proj.aggregate_id
         AND cmd_ev.event_type = 'ExecutionCommandCreated'
         AND cmd_ev.event_sequence = proj.last_sequence
        WHERE proj.current_state = 'EXECUTION_COMMAND_CREATED'
          AND proj.last_event_type = 'ExecutionCommandCreated'
          AND COALESCE(proj.venue_order_id, '') = ''
          AND cmd_ev.occurred_at < ?
          AND NOT EXISTS (
              SELECT 1 FROM {events_ref} later
              WHERE later.aggregate_id = proj.aggregate_id
                AND later.event_type IN ({disqualifier_placeholders})
                AND later.event_sequence > cmd_ev.event_sequence
          )
        ORDER BY cmd_ev.occurred_at, proj.aggregate_id
        """,
        (cutoff_iso, *_GHOST_DISQUALIFYING_EVENT_TYPES),
    ).fetchall()
    candidates: list[dict] = []
    for row in rows:
        record = _dict_row(row)
        execution_command_id = str(record.get("execution_command_id") or "").strip()
        if not execution_command_id:
            # An ExecutionCommandCreated with no execution_command_id cannot be
            # safely cap-released or command-bound; skip (fail closed).
            continue
        # VENUE-TRUTH GUARD: any venue_commands row for this execution_command_id
        # means the order reached the command bus — never terminalize.
        venue_cmd = conn.execute(
            "SELECT 1 FROM venue_commands WHERE decision_id = ? LIMIT 1",
            (execution_command_id,),
        ).fetchone()
        if venue_cmd is not None:
            continue
        record["execution_command_id"] = execution_command_id
        candidates.append(record)
    return candidates


def _terminalize_abandoned_unsubmitted_ghost(
    conn: sqlite3.Connection,
    *,
    events_ref: str,
    projection_ref: str,
    cap_usage_ref: str,
    day_slots_ref: str | None,
    rate_window_ref: str | None,
    aggregate_id: str,
    execution_command_id: str,
    occurred_at: str,
) -> dict | None:
    """Append a PRE-SUBMIT SubmitRejected terminal + release the cap reservation.

    Returns a redecision-continuation identity when the ghost was terminalized,
    or None when a final guard (re-read venue truth) refuses. Caller wraps this
    in a SAVEPOINT.
    """
    # Re-read the ExecutionCommandCreated event for the exact command-binding
    # fields (event_id / final_intent_id / execution_command_id) the
    # _require_command_binding check enforces. Fail closed if absent.
    command_event = _latest_edli_event(conn, events_ref, aggregate_id, "ExecutionCommandCreated")
    command_payload = _edli_payload(command_event)
    plan_payload = _edli_payload(_latest_edli_event(conn, events_ref, aggregate_id, "SubmitPlanBuilt"))
    event_id = str(command_payload.get("event_id") or "").strip()
    final_intent_id = str(command_payload.get("final_intent_id") or "").strip()
    bound_command_id = str(command_payload.get("execution_command_id") or "").strip()
    if not event_id or not final_intent_id or bound_command_id != execution_command_id:
        return None

    # FINAL venue-truth guard (re-read the projection under the write lock): the
    # latest event must still be ExecutionCommandCreated and venue_order_id NULL.
    projection = conn.execute(
        f"""
        SELECT current_state, last_event_type, venue_order_id
        FROM {projection_ref}
        WHERE aggregate_id = ?
        """,
        (aggregate_id,),
    ).fetchone()
    if projection is None:
        return None
    if str(projection["current_state"]) != "EXECUTION_COMMAND_CREATED":
        return None
    if str(projection["last_event_type"] or "") != "ExecutionCommandCreated":
        return None
    if str(projection["venue_order_id"] or "").strip():
        return None

    # The PRE-SUBMIT SubmitRejected payload the immutable ledger accepts directly
    # after ExecutionCommandCreated (no VenueSubmitAttempted required), per
    # live_order_aggregate._validate_event_append + _is_pre_submit_rejection_payload
    # + _require_command_binding. reason_code is mandatory.
    submit_rejected_payload = {
        "schema_version": 1,
        "event_id": event_id,
        "final_intent_id": final_intent_id,
        "execution_command_id": execution_command_id,
        "execution_receipt_hash": str(command_payload.get("execution_receipt_hash") or ""),
        "reason_code": "ABANDONED_UNSUBMITTED_GHOST_RECONCILE",
        "submit_status": "PRE_SUBMIT_ERROR",
        "venue_call_started": False,
        "venue_ack_received": False,
        "pre_submit_rejection": True,
        "proof_class": "command_created_never_submitted_no_venue_presence",
        "required_predicates": {
            "current_event_is_execution_command_created": True,
            "no_venue_submit_attempt": True,
            "no_venue_order_id": True,
            "no_venue_commands_row": True,
            "aged_past_grace_seconds": _ABANDONED_GHOST_GRACE_SECONDS,
        },
        "reviewed_by": "command_recovery",
        "cleared_at": occurred_at,
    }
    _append_edli_event_qualified(
        conn,
        events_ref=events_ref,
        aggregate_id=aggregate_id,
        event_type="SubmitRejected",
        payload=submit_rejected_payload,
        occurred_at=occurred_at,
        source_authority="existing_executor",
    )

    # Release the still-RESERVED cap reservation keyed by execution_command_id.
    cap = conn.execute(
        f"""
        SELECT usage_id, reservation_status
        FROM {cap_usage_ref}
        WHERE execution_command_id = ?
        ORDER BY created_at DESC
        LIMIT 1
        """,
        (execution_command_id,),
    ).fetchone()
    if cap is not None and str(cap["reservation_status"]) == "RESERVED":
        usage_id = str(cap["usage_id"])
        conn.execute(
            f"UPDATE {cap_usage_ref} SET reservation_status = 'RELEASED' WHERE usage_id = ?",
            (usage_id,),
        )
        if day_slots_ref:
            conn.execute(f"DELETE FROM {day_slots_ref} WHERE usage_id = ?", (usage_id,))
        if rate_window_ref:
            conn.execute(f"DELETE FROM {rate_window_ref} WHERE usage_id = ?", (usage_id,))

    _rebuild_edli_projection_qualified(
        conn,
        events_ref=events_ref,
        projection_ref=projection_ref,
        aggregate_id=aggregate_id,
    )
    return {
        "reason": "abandoned_unsubmitted_ghost",
        "aggregate_id": aggregate_id,
        "execution_command_id": execution_command_id,
        "event_id": event_id,
        "final_intent_id": final_intent_id,
        "family_id": str(plan_payload.get("family_id") or ""),
        "city": str(plan_payload.get("city") or ""),
        "target_date": str(plan_payload.get("target_date") or ""),
        "metric": _canonical_temperature_metric_text(
            plan_payload.get("metric") or plan_payload.get("temperature_metric") or ""
        ),
        "condition_id": str(plan_payload.get("condition_id") or ""),
        "token_id": str(plan_payload.get("token_id") or ""),
        "direction": str(plan_payload.get("direction") or ""),
    }


def reconcile_abandoned_unsubmitted_ghosts(
    conn: sqlite3.Connection,
    *,
    updated_before: str | None = None,
) -> dict[str, object]:
    """Terminalize EDLI order aggregates abandoned at ExecutionCommandCreated.

    THE GHOST CLASS THIS KILLS (live_order_pathology 2026-06-22): an aggregate
    that reached ExecutionCommandCreated and was then interrupted before the venue
    submit. It is non-terminal, so the duplicate-suppression family lock
    (event_reactor_adapter._locked_live_opportunity_active_order_reason) suppresses
    every new submit on the same weather family forever — even an opposite-direction
    trade — while $0 sits at the venue.

    For each such ghost (after a grace window, with NO venue presence) this appends
    a PRE-SUBMIT SubmitRejected — the legal terminal directly after
    ExecutionCommandCreated, accepted by the immutable ledger's _validate_event_append
    — and releases its still-RESERVED cap reservation. That makes the aggregate
    TERMINAL per _TERMINAL_EVENT_SQL, releasing the family lock so the next decision
    cycle re-enters the family through the full (un-bypassed) certification pipeline.

    Wired into both recovery lanes (boot / periodic) so a daemon restart self-heals
    any ghost it created on its way down. DB-only pass; never calls the venue.
    Returns {"scanned", "advanced", "stayed", "errors", "continuations"}.
    """
    summary: dict[str, object] = {
        "scanned": 0,
        "advanced": 0,
        "stayed": 0,
        "errors": 0,
        "continuations": [],
    }
    events_ref = _edli_live_order_events_ref(conn)
    projection_ref = _edli_live_order_projection_ref(conn)
    cap_usage_ref = _edli_live_cap_ref(conn, "edli_live_cap_usage")
    if not events_ref or not projection_ref or not cap_usage_ref:
        return summary
    day_slots_ref = _edli_live_cap_ref(conn, "edli_live_cap_day_slots")
    rate_window_ref = _edli_live_cap_ref(conn, "edli_live_cap_rate_window")

    now = datetime.now(timezone.utc)
    explicit_cutoff = _parse_ts(updated_before) if updated_before else None
    grace_cutoff = now - timedelta(seconds=_ABANDONED_GHOST_GRACE_SECONDS)
    # Honor an explicit caller cutoff only when it is at least as strict (no later
    # than) the grace cutoff — we never terminalize a ghost younger than the grace.
    cutoff = min(explicit_cutoff, grace_cutoff) if explicit_cutoff is not None else grace_cutoff
    cutoff_iso = cutoff.astimezone(timezone.utc).isoformat()

    candidates = _abandoned_unsubmitted_ghost_candidates(
        conn,
        events_ref=events_ref,
        projection_ref=projection_ref,
        cutoff_iso=cutoff_iso,
    )
    occurred_at = _now_iso()
    for candidate in candidates:
        summary["scanned"] = int(summary["scanned"]) + 1
        aggregate_id = str(candidate.get("aggregate_id") or "")
        execution_command_id = str(candidate.get("execution_command_id") or "")
        conn.execute("SAVEPOINT abandoned_unsubmitted_ghost_reconcile")
        try:
            continuation = _terminalize_abandoned_unsubmitted_ghost(
                conn,
                events_ref=events_ref,
                projection_ref=projection_ref,
                cap_usage_ref=cap_usage_ref,
                day_slots_ref=day_slots_ref,
                rate_window_ref=rate_window_ref,
                aggregate_id=aggregate_id,
                execution_command_id=execution_command_id,
                occurred_at=occurred_at,
            )
            conn.execute("RELEASE SAVEPOINT abandoned_unsubmitted_ghost_reconcile")
            if continuation:
                summary["advanced"] = int(summary["advanced"]) + 1
                continuations = summary.get("continuations")
                if isinstance(continuations, list):
                    continuations.append(continuation)
            else:
                summary["stayed"] = int(summary["stayed"]) + 1
        except Exception as exc:
            conn.execute("ROLLBACK TO SAVEPOINT abandoned_unsubmitted_ghost_reconcile")
            conn.execute("RELEASE SAVEPOINT abandoned_unsubmitted_ghost_reconcile")
            logger.error(
                "recovery: abandoned-unsubmitted-ghost reconcile failed for %s (cmd=%s): %s",
                aggregate_id,
                execution_command_id,
                exc,
            )
            summary["errors"] = int(summary["errors"]) + 1
    return summary


def reconcile_stale_intent_created_no_submit(
    conn: sqlite3.Connection,
    *,
    updated_before: str | None = None,
) -> dict[str, int]:
    """Terminalize pre-submit command shells that never crossed the venue boundary.

    A crash/SQLite lock can occur after ``insert_command`` appends INTENT_CREATED
    but before SUBMIT_REQUESTED is appended or any venue call is made.  Such a
    row is not an unresolved venue side effect, but leaving it active misleads
    operators and downstream projections.  The predicates here are intentionally
    local and strict: no submit event, no venue order id, no order/trade facts,
    and no position event caused by this command.  ``position_current`` itself
    is not a command-scoped predicate: a Kelly increment correctly points at an
    already-active position, so requiring position absence strands precisely
    the safe pre-venue shell this recovery owns.
    """

    summary = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
    cutoff = str(updated_before or _now_iso())
    rows = conn.execute(
        """
        SELECT cmd.*
          FROM venue_commands cmd
         WHERE cmd.state = 'INTENT_CREATED'
           AND COALESCE(cmd.venue_order_id, '') = ''
           AND cmd.updated_at < ?
           AND NOT EXISTS (
                SELECT 1
                  FROM venue_command_events ev
                 WHERE ev.command_id = cmd.command_id
                   AND ev.event_type != 'INTENT_CREATED'
           )
           AND NOT EXISTS (
                SELECT 1 FROM venue_order_facts fact
                 WHERE fact.command_id = cmd.command_id
           )
           AND NOT EXISTS (
                SELECT 1 FROM venue_trade_facts fact
                 WHERE fact.command_id = cmd.command_id
           )
           AND NOT EXISTS (
                SELECT 1 FROM position_events pe
                 WHERE pe.command_id = cmd.command_id
           )
         ORDER BY cmd.updated_at, cmd.command_id
        """,
        (cutoff,),
    ).fetchall()
    summary["scanned"] = len(rows)
    for row in rows:
        command = _dict_row(row)
        command_id = str(command.get("command_id") or "")
        try:
            payload = {
                "schema_version": 1,
                "reason": "pre_venue_intent_abandoned_before_submit",
                "command_id": command_id,
                "decision_id": str(command.get("decision_id") or ""),
                "proof_class": "local_command_journal_no_submit_boundary",
                "side_effect_boundary_crossed": False,
                "venue_order_created": False,
                "safe_replay_permitted": True,
                "required_predicates": {
                    "state_is_intent_created": True,
                    "no_submit_requested_event": True,
                    "no_venue_order_id": True,
                    "no_order_facts": True,
                    "no_trade_facts": True,
                    "no_command_position_events": True,
                    "updated_before_recovery_started_at": cutoff,
                },
                "reviewed_by": "command_recovery",
                "cleared_at": cutoff,
            }
            append_event(
                conn,
                command_id=command_id,
                event_type=CommandEventType.SUBMIT_REJECTED.value,
                occurred_at=cutoff,
                payload=payload,
            )
            summary["advanced"] += 1
        except Exception:
            summary["errors"] += 1
            logger.exception(
                "recovery: stale INTENT_CREATED terminalization failed for command %s",
                command_id,
            )
    return summary


def _latest_edli_event(conn: sqlite3.Connection, events_ref: str, aggregate_id: str, event_type: str | None = None) -> dict:
    if event_type is None:
        row = conn.execute(
            f"""
            SELECT *
            FROM {events_ref}
            WHERE aggregate_id = ?
            ORDER BY event_sequence DESC
            LIMIT 1
            """,
            (aggregate_id,),
        ).fetchone()
    else:
        row = conn.execute(
            f"""
            SELECT *
            FROM {events_ref}
            WHERE aggregate_id = ? AND event_type = ?
            ORDER BY event_sequence DESC
            LIMIT 1
            """,
            (aggregate_id, event_type),
        ).fetchone()
    return _dict_row(row)


def _edli_payload(row: Mapping[str, object] | None) -> dict:
    if not row:
        return {}
    return _json_dict(_dict_row(row).get("payload_json"))


def _append_edli_event_qualified(
    conn: sqlite3.Connection,
    *,
    events_ref: str,
    aggregate_id: str,
    event_type: str,
    payload: dict,
    occurred_at: str,
    source_authority: str,
) -> dict:
    latest = _latest_edli_event(conn, events_ref, aggregate_id)
    if not latest:
        raise ValueError("EDLI recovery requires existing aggregate event")
    parent_hash = str(latest.get("event_hash") or "")
    next_sequence = int(latest.get("event_sequence") or 0) + 1
    payload_json = canonical_json(payload)
    payload_hash = stable_hash(payload)
    event_hash = stable_hash(
        {
            "aggregate_id": aggregate_id,
            "event_sequence": next_sequence,
            "event_type": event_type,
            "parent_event_hash": parent_hash,
            "payload_hash": payload_hash,
            "source_authority": source_authority,
            "occurred_at": occurred_at,
        }
    )
    aggregate_event_id = "edli_live_order_event:" + event_hash[:32]
    conn.execute(
        f"""
        INSERT INTO {events_ref} (
            aggregate_event_id, aggregate_id, event_sequence, event_type,
            parent_event_hash, event_hash, payload_json, payload_hash,
            source_authority, occurred_at, created_at, schema_version
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
        """,
        (
            aggregate_event_id,
            aggregate_id,
            next_sequence,
            event_type,
            parent_hash,
            event_hash,
            payload_json,
            payload_hash,
            source_authority,
            occurred_at,
            _now_iso(),
        ),
    )
    return {
        "aggregate_event_id": aggregate_event_id,
        "event_hash": event_hash,
        "event_sequence": next_sequence,
    }


def _rebuild_edli_projection_qualified(
    conn: sqlite3.Connection,
    *,
    events_ref: str,
    projection_ref: str,
    aggregate_id: str,
) -> None:
    rows = conn.execute(
        f"""
        SELECT *
        FROM {events_ref}
        WHERE aggregate_id = ?
        ORDER BY event_sequence ASC
        """,
        (aggregate_id,),
    ).fetchall()
    if not rows:
        raise ValueError("cannot rebuild EDLI projection for empty aggregate")
    event_id = str(_edli_payload(rows[0]).get("event_id") or "")
    final_intent_id = None
    venue_order_id = None
    pending_reconcile = False
    current_state = "UNKNOWN"
    state_by_type = {
        "DecisionProofAccepted": "DECISION_PROOF_ACCEPTED",
        "SubmitPlanBuilt": "SUBMIT_PLAN_BUILT",
        "PreSubmitRevalidated": "PRE_SUBMIT_REVALIDATED",
        "LiveCapReserved": "LIVE_CAP_RESERVED",
        "ExecutionCommandCreated": "EXECUTION_COMMAND_CREATED",
        "VenueSubmitAttempted": "VENUE_SUBMIT_ATTEMPTED",
        "VenueSubmitAcknowledged": "VENUE_SUBMIT_ACKED",
        "SubmitRejected": "SUBMIT_REJECTED",
        "SubmitUnknown": "PENDING_RECONCILE",
        "UserOrderObserved": "USER_ORDER_OBSERVED",
        "UserTradeObserved": "USER_TRADE_OBSERVED",
        "Reconciled": "RECONCILED",
        "CapTransitioned": "CAP_TRANSITIONED",
        "OrderLifecycleProjected": "ORDER_LIFECYCLE_PROJECTED",
    }
    for row in rows:
        payload = _edli_payload(row)
        if payload.get("final_intent_id") is not None:
            final_intent_id = str(payload["final_intent_id"])
        if payload.get("venue_order_id") is not None:
            venue_order_id = str(payload["venue_order_id"])
        current_event_type = str(row["event_type"])
        if current_event_type == "SubmitUnknown":
            current_state = "PENDING_RECONCILE"
            pending_reconcile = True
        elif current_event_type == "CapTransitioned":
            to_status = str(payload.get("to_status") or "")
            if to_status == "PENDING_RECONCILE":
                current_state = "PENDING_RECONCILE"
                pending_reconcile = True
            elif to_status == "CONSUMED":
                # CONSUMED belongs to the live-cap ledger. It must not hide
                # the active venue order lifecycle in the projection.
                if current_state == "UNKNOWN":
                    current_state = "VENUE_SUBMIT_ACKED"
            else:
                current_state = state_by_type.get(current_event_type, current_event_type)
        elif current_event_type == "Reconciled":
            current_state = "RECONCILED"
            pending_reconcile = bool(payload.get("pending_reconcile", False))
        elif current_event_type == "OrderLifecycleProjected":
            current_state = str(payload.get("order_lifecycle_state") or state_by_type.get(current_event_type, current_event_type))
            pending_reconcile = bool(payload.get("pending_reconcile", False))
        else:
            current_state = state_by_type.get(current_event_type, current_event_type)
    last = rows[-1]
    conn.execute(
        f"""
        INSERT INTO {projection_ref} (
            aggregate_id, event_id, final_intent_id, current_state,
            last_sequence, last_event_type, last_event_hash,
            pending_reconcile, venue_order_id, updated_at, schema_version
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
        ON CONFLICT(aggregate_id) DO UPDATE SET
            event_id = excluded.event_id,
            final_intent_id = excluded.final_intent_id,
            current_state = excluded.current_state,
            last_sequence = excluded.last_sequence,
            last_event_type = excluded.last_event_type,
            last_event_hash = excluded.last_event_hash,
            pending_reconcile = excluded.pending_reconcile,
            venue_order_id = excluded.venue_order_id,
            updated_at = excluded.updated_at,
            schema_version = excluded.schema_version
        """,
        (
            aggregate_id,
            event_id,
            final_intent_id,
            current_state,
            int(last["event_sequence"]),
            str(last["event_type"]),
            str(last["event_hash"]),
            1 if pending_reconcile else 0,
            venue_order_id,
            _now_iso(),
        ),
    )


def _reconcile_edli_pending_no_order_if_proven(
    conn: sqlite3.Connection,
    *,
    execution_command_id: str,
    occurred_at: str,
    reason: str,
    proof_class: str,
    command_id: str | None = None,
    required_predicates: Mapping[str, object] | None = None,
) -> bool:
    if not execution_command_id:
        return False
    events_ref = _edli_live_order_events_ref(conn)
    projection_ref = _edli_live_order_projection_ref(conn)
    cap_usage_ref = _edli_live_cap_ref(conn, "edli_live_cap_usage")
    day_slots_ref = _edli_live_cap_ref(conn, "edli_live_cap_day_slots")
    rate_window_ref = _edli_live_cap_ref(conn, "edli_live_cap_rate_window")
    if not events_ref or not projection_ref or not cap_usage_ref:
        return False
    row = conn.execute(
        f"""
        SELECT aggregate_id, payload_json
        FROM {events_ref}
        WHERE event_type = 'SubmitUnknown'
          AND json_extract(payload_json, '$.execution_command_id') = ?
        ORDER BY event_sequence DESC
        LIMIT 1
        """,
        (execution_command_id,),
    ).fetchone()
    if row is None:
        return False
    aggregate_id = str(row["aggregate_id"])
    submit_unknown_payload = _json_dict(row["payload_json"])
    if submit_unknown_payload.get("side_effect_known") is True:
        return False
    unsafe_count = conn.execute(
        f"""
        SELECT COUNT(*)
        FROM {events_ref}
        WHERE aggregate_id = ?
          AND event_type IN ('VenueSubmitAcknowledged', 'UserOrderObserved', 'UserTradeObserved')
        """,
        (aggregate_id,),
    ).fetchone()[0]
    if int(unsafe_count) != 0:
        return False
    projection = conn.execute(
        f"""
        SELECT pending_reconcile, venue_order_id
        FROM {projection_ref}
        WHERE aggregate_id = ?
        """,
        (aggregate_id,),
    ).fetchone()
    if projection is None or not bool(projection["pending_reconcile"]):
        return False
    if str(projection["venue_order_id"] or "").strip():
        return False
    cap = conn.execute(
        f"""
        SELECT usage_id, event_id, final_intent_id, reservation_status
        FROM {cap_usage_ref}
        WHERE execution_command_id = ?
        ORDER BY created_at DESC
        LIMIT 1
        """,
        (execution_command_id,),
    ).fetchone()
    if cap is None or str(cap["reservation_status"]) != "RESERVED":
        return False
    usage_id = str(cap["usage_id"])
    event_id = str(cap["event_id"])
    final_intent_id = str(cap["final_intent_id"] or submit_unknown_payload.get("final_intent_id") or "")
    reconcile_payload = {
        "schema_version": 1,
        "event_id": event_id,
        "final_intent_id": final_intent_id,
        "source_authority": "venue_reconcile",
        "pending_reconcile": False,
        "venue_order_exists": False,
        "cap_transition_recommendation": "RELEASED",
        "reason": reason,
        "proof_class": proof_class,
        "execution_command_id": execution_command_id,
        "command_id": command_id,
        "required_predicates": dict(required_predicates or {}),
    }
    reconciled = _append_edli_event_qualified(
        conn,
        events_ref=events_ref,
        aggregate_id=aggregate_id,
        event_type="Reconciled",
        payload=reconcile_payload,
        occurred_at=occurred_at,
        source_authority="explicit_reconcile",
    )
    conn.execute(
        f"UPDATE {cap_usage_ref} SET reservation_status = 'RELEASED' WHERE usage_id = ?",
        (usage_id,),
    )
    if day_slots_ref:
        conn.execute(f"DELETE FROM {day_slots_ref} WHERE usage_id = ?", (usage_id,))
    if rate_window_ref:
        conn.execute(f"DELETE FROM {rate_window_ref} WHERE usage_id = ?", (usage_id,))
    _append_edli_event_qualified(
        conn,
        events_ref=events_ref,
        aggregate_id=aggregate_id,
        event_type="CapTransitioned",
        payload={
            "schema_version": 1,
            "event_id": event_id,
            "final_intent_id": final_intent_id,
            "execution_command_id": execution_command_id,
            "execution_receipt_hash": str(submit_unknown_payload.get("execution_receipt_hash") or reconciled["event_hash"]),
            "to_status": "RELEASED",
            "projection_status": "RELEASED",
            "transition_reason": reason,
            "reconciled_event_hash": reconciled["event_hash"],
        },
        occurred_at=occurred_at,
        source_authority="live_cap_ledger",
    )
    _rebuild_edli_projection_qualified(
        conn,
        events_ref=events_ref,
        projection_ref=projection_ref,
        aggregate_id=aggregate_id,
    )
    return True


def _project_edli_terminal_no_fill_order_lifecycle(
    conn: sqlite3.Connection,
    *,
    command: Mapping[str, object],
    order_fact: Mapping[str, object],
    occurred_at: str,
) -> bool:
    """Mirror a proven zero-fill venue terminal fact into the EDLI order aggregate."""

    events_ref = _edli_live_order_events_ref(conn)
    projection_ref = _edli_live_order_projection_ref(conn)
    if not events_ref or not projection_ref:
        return False

    command_id = str(command.get("command_id") or "").strip()
    decision_id = str(command.get("decision_id") or "").strip()
    venue_order_id = str(
        order_fact.get("order_fact_venue_order_id")
        or order_fact.get("venue_order_id")
        or command.get("venue_order_id")
        or ""
    ).strip()
    if not venue_order_id or not command_id:
        return False

    execution_ids = tuple(
        value
        for value in dict.fromkeys((decision_id, command_id))
        if value
    )
    predicates = [
        "json_extract(payload_json, '$.command_id') = ?",
        "json_extract(payload_json, '$.venue_order_id') = ?",
    ]
    params: list[str] = [command_id, venue_order_id]
    if execution_ids:
        predicates.append(
            "json_extract(payload_json, '$.execution_command_id') IN ("
            + ",".join("?" for _ in execution_ids)
            + ")"
        )
        params.extend(execution_ids)

    rows = conn.execute(
        f"""
        WITH matched AS (
            SELECT aggregate_id, MAX(event_sequence) AS matched_sequence
              FROM {events_ref}
             WHERE {' OR '.join(predicates)}
             GROUP BY aggregate_id
        )
        SELECT proj.aggregate_id,
               proj.event_id,
               proj.final_intent_id,
               proj.current_state,
               proj.venue_order_id,
               matched.matched_sequence
          FROM matched
          JOIN {projection_ref} proj
            ON proj.aggregate_id = matched.aggregate_id
         ORDER BY matched.matched_sequence DESC, proj.updated_at DESC
         LIMIT 8
        """,
        tuple(params),
    ).fetchall()
    if not rows:
        return False

    for candidate_row in rows:
        candidate = _dict_row(candidate_row)
        aggregate_id = str(candidate.get("aggregate_id") or "")
        if not aggregate_id:
            continue
        terminal = conn.execute(
            f"""
            SELECT 1
              FROM {events_ref}
             WHERE aggregate_id = ?
               AND event_type IN ('UserTradeObserved', 'OrderLifecycleProjected')
               AND (
                    event_type = 'UserTradeObserved'
                    OR json_extract(payload_json, '$.order_lifecycle_state') = 'TERMINAL_NO_FILL'
               )
             LIMIT 1
            """,
            (aggregate_id,),
        ).fetchone()
        if terminal is not None:
            continue
        command_event = conn.execute(
            f"""
            SELECT payload_json
              FROM {events_ref}
             WHERE aggregate_id = ?
               AND event_type = 'ExecutionCommandCreated'
             ORDER BY event_sequence DESC
             LIMIT 1
            """,
            (aggregate_id,),
        ).fetchone()
        if command_event is None:
            continue
        command_payload = _json_dict(command_event["payload_json"])
        event_id = str(candidate.get("event_id") or command_payload.get("event_id") or "")
        final_intent_id = str(
            candidate.get("final_intent_id")
            or command_payload.get("final_intent_id")
            or ""
        )
        execution_command_id = str(
            command_payload.get("execution_command_id")
            or decision_id
            or command_id
        )
        if not event_id:
            continue
        _append_edli_event_qualified(
            conn,
            events_ref=events_ref,
            aggregate_id=aggregate_id,
            event_type="OrderLifecycleProjected",
            payload={
                "schema_version": 1,
                "event_id": event_id,
                "final_intent_id": final_intent_id,
                "execution_command_id": execution_command_id,
                "command_id": command_id,
                "venue_order_id": venue_order_id,
                "order_lifecycle_state": "TERMINAL_NO_FILL",
                "pending_reconcile": False,
                "exposure_created": False,
                "reason": "venue_terminal_no_fill",
                "proof_class": "terminal_order_fact_zero_matched",
                "venue_order_fact_id": order_fact.get("order_fact_id"),
                "venue_order_fact_state": order_fact.get("order_fact_state"),
                "matched_size": order_fact.get("order_fact_matched_size"),
                "remaining_size": order_fact.get("order_fact_remaining_size"),
                "source": order_fact.get("order_fact_source"),
                "source_authority": "venue_reconcile",
            },
            occurred_at=occurred_at,
            source_authority="explicit_reconcile",
        )
        _rebuild_edli_projection_qualified(
            conn,
            events_ref=events_ref,
            projection_ref=projection_ref,
            aggregate_id=aggregate_id,
        )
        return True
    return False


# Terminal CommandEventType used to discharge an unresolved venue_commands row
# once the event-sourced EDLI ledger has AUTHENTICATED-ABSENCE-PROVEN that the
# venue holds no open order and no trade for the command's token. The submit
# side-effect boundary WAS crossed (that is why the row is
# SUBMIT_UNKNOWN_SIDE_EFFECT / UNKNOWN), so the REVIEW_CLEARED_NO_VENUE_EXPOSURE
# path — whose no_submit_side_effect_events predicate forbids a prior
# SUBMIT_TIMEOUT_UNKNOWN / CLOSED_MARKET_UNKNOWN event — is BY DESIGN not legal
# here. The grammar's direct SUBMIT_UNKNOWN_SIDE_EFFECT -> SUBMIT_REJECTED edge
# (venue_command_repo._TRANSITIONS) is the canonical terminalization for
# "post-submit unknown, venue authenticated-confirmed no order and no trade",
# mirroring the live-venue safe_replay_permitted_no_order_found path in
# _reconcile_row. SUBMIT_REJECTED sits OUTSIDE _UNRESOLVED_SIDE_EFFECT_STATES so
# the governor's count_unknown_side_effects drops and the kill switch clears.
_EDLI_ABSENCE_SYNC_SOURCE_FUNCTION = "command_recovery._reconcile_venue_command_absence_sync"


def _edli_reconciled_absence_for_decision(
    conn: sqlite3.Connection,
    *,
    events_ref: str,
    decision_id: str,
) -> tuple[str, dict | None]:
    """Resolve the unique EDLI authenticated-absence proof for a command.

    The canonical EDLI <-> venue_commands link is
    ``Reconciled.payload.execution_command_id == venue_commands.decision_id``
    (the same join key used by _reconcile_edli_pre_venue_unknown_thresholds).

    Returns ``(status, reconcile_payload)`` where status is one of:
      * ``"absent"``  — exactly one Reconciled event whose authenticated absence
                         proof proves venue_order_exists=false AND
                         venue_trade_exists=false AND no matching open
                         order/trade for the token. ``reconcile_payload`` is set.
      * ``"exposure"``— a matching Reconciled event reports (or its proof shows)
                         venue exposure; FAIL-CLOSED, never terminalize.
      * ``"absent_none"`` — no Reconciled event links to this decision_id.
      * ``"ambiguous"``  — more than one distinct EDLI aggregate links to this
                         decision_id; FAIL-CLOSED, cannot pick one.

    Reads only; never re-queries the venue and never writes the world ledger.
    """

    if not decision_id:
        return "absent_none", None
    rows = conn.execute(
        f"""
        SELECT aggregate_id, payload_json
        FROM {events_ref}
        WHERE event_type = 'Reconciled'
          AND json_extract(payload_json, '$.execution_command_id') = ?
        ORDER BY event_sequence DESC
        """,
        (decision_id,),
    ).fetchall()
    if not rows:
        return "absent_none", None
    distinct_aggregates = {str(_dict_row(row).get("aggregate_id") or "") for row in rows}
    if len(distinct_aggregates) != 1:
        return "ambiguous", None
    payload = _json_dict(_dict_row(rows[0]).get("payload_json"))
    proof = payload.get("authenticated_absence_proof")
    proof = proof if isinstance(proof, dict) else {}
    # Authenticated absence requires BOTH the reconcile verdict and the proof's
    # own matching-exposure counts to be zero. Any positive value, a missing
    # proof, or a non-absence verdict fails closed.
    venue_order_exists = payload.get("venue_order_exists")
    venue_trade_exists = payload.get("venue_trade_exists")
    if venue_order_exists is True or venue_trade_exists is True:
        return "exposure", None
    if not proof:
        return "absent_none", None
    if str(payload.get("reconcile_reason") or "") != "AUTHENTICATED_CLOB_ABSENCE_NO_OPEN_ORDER_OR_TRADE":
        return "absent_none", None
    try:
        matching_open = int(proof.get("matching_open_order_count", -1))
        matching_trade = int(proof.get("matching_trade_count", -1))
    except (TypeError, ValueError):
        return "absent_none", None
    if matching_open != 0 or matching_trade != 0:
        return "exposure", None
    if venue_order_exists is not False or venue_trade_exists is not False:
        return "absent_none", None
    return "absent", payload


def _reconcile_venue_command_absence_sync(conn: sqlite3.Connection) -> dict:
    """Keep post-submit unknown venue commands fail-closed.

    An EDLI ``Reconciled`` absence event may come from an account snapshot taken
    after the request returned unknown. That snapshot cannot prove that the
    original submit will not appear later, so it cannot authorize replay or
    release the command-side governor. Only a causal order/trade/submit fact may
    terminalize these rows.
    """

    summary = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
    states = tuple(
        state
        for state in sorted(UNRESOLVED_SIDE_EFFECT_STATES)
        if state in (
            CommandState.SUBMIT_UNKNOWN_SIDE_EFFECT.value,
            CommandState.UNKNOWN.value,
        )
    )
    if not states:
        return summary
    placeholders = ",".join("?" for _ in states)
    rows = conn.execute(
        f"""
        SELECT command_id, decision_id, market_id, token_id, side, price, size,
               created_at, venue_order_id, state
        FROM venue_commands
        WHERE state IN ({placeholders})
          AND COALESCE(venue_order_id, '') = ''
        ORDER BY created_at, command_id
        """,
        states,
    ).fetchall()
    summary["scanned"] = len(rows)
    summary["stayed"] = len(rows)
    if rows:
        logger.warning(
            "recovery: keeping %d post-submit unknown venue commands fail-closed; "
            "EDLI account-snapshot absence is not causal side-effect proof",
            len(rows),
        )
    return summary


def reconcile_edli_acknowledged_venue_command_sync(conn: sqlite3.Connection) -> dict:
    """Mirror ACKED venue_commands back into the EDLI live-order ledger.

    A submit can succeed in the trade-side command journal while the world-side
    EDLI aggregate only records ``VenueSubmitAttempted``. The order is real, so
    releasing the cap would be wrong; recovery appends the missing
    ``VenueSubmitAcknowledged`` and ``CapTransitioned(CONSUMED)`` events and
    marks the existing cap reservation CONSUMED.
    """

    summary = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
    events_ref = _edli_live_order_events_ref(conn)
    projection_ref = _edli_live_order_projection_ref(conn)
    cap_usage_ref = _edli_live_cap_ref(conn, "edli_live_cap_usage")
    if not events_ref or not projection_ref or not cap_usage_ref or not _table_exists(conn, "venue_commands"):
        return summary
    rows = conn.execute(
        f"""
        SELECT proj.aggregate_id,
               proj.event_id,
               proj.final_intent_id,
               plan.payload_json AS plan_payload_json,
               attempted.payload_json AS attempted_payload_json,
               usage.usage_id,
               usage.execution_command_id,
               cmd.command_id,
               cmd.decision_id,
               cmd.token_id,
               cmd.state,
               cmd.venue_order_id,
               cmd.updated_at AS command_updated_at
        FROM {projection_ref} proj
        JOIN {events_ref} plan
          ON plan.aggregate_id = proj.aggregate_id
         AND plan.event_type = 'SubmitPlanBuilt'
        JOIN {events_ref} attempted
          ON attempted.aggregate_id = proj.aggregate_id
         AND attempted.event_type = 'VenueSubmitAttempted'
        JOIN {cap_usage_ref} usage
          ON usage.event_id = proj.event_id
         AND usage.final_intent_id = proj.final_intent_id
         AND usage.reservation_status = 'RESERVED'
        JOIN venue_commands cmd
          ON cmd.decision_id = usage.execution_command_id
        WHERE proj.current_state = 'VENUE_SUBMIT_ATTEMPTED'
          AND proj.last_event_type = 'VenueSubmitAttempted'
          AND COALESCE(proj.venue_order_id, '') = ''
          AND cmd.intent_kind = 'ENTRY'
          AND cmd.state IN ('ACKED', 'POST_ACKED')
          AND COALESCE(cmd.venue_order_id, '') != ''
          AND NOT EXISTS (
              SELECT 1 FROM {events_ref} ack
              WHERE ack.aggregate_id = proj.aggregate_id
                AND ack.event_type = 'VenueSubmitAcknowledged'
          )
          AND NOT EXISTS (
              SELECT 1 FROM {events_ref} cap
              WHERE cap.aggregate_id = proj.aggregate_id
                AND cap.event_type = 'CapTransitioned'
          )
        ORDER BY attempted.occurred_at, proj.aggregate_id
        """
    ).fetchall()
    summary["scanned"] = len(rows)
    occurred_at = _now_iso()
    for row in rows:
        record = _dict_row(row)
        aggregate_id = str(record.get("aggregate_id") or "")
        command_id = str(record.get("command_id") or "")
        venue_order_id = str(record.get("venue_order_id") or "").strip()
        safe_command_id = "".join(ch if ch.isalnum() else "_" for ch in command_id) or "unknown"
        sp_name = f"sp_edli_ack_sync_{safe_command_id}"
        conn.execute(f"SAVEPOINT {sp_name}")
        try:
            plan_payload = _json_dict(record.get("plan_payload_json"))
            attempted_payload = _json_dict(record.get("attempted_payload_json"))
            event_id = str(record.get("event_id") or plan_payload.get("event_id") or "")
            final_intent_id = str(record.get("final_intent_id") or plan_payload.get("final_intent_id") or "")
            execution_command_id = str(record.get("execution_command_id") or "")
            command_decision_id = str(record.get("decision_id") or "")
            plan_token = str(plan_payload.get("token_id") or "")
            command_token = str(record.get("token_id") or "")
            attempted_command_id = str(attempted_payload.get("execution_command_id") or "")
            if (
                not aggregate_id
                or not event_id
                or not final_intent_id
                or not execution_command_id
                or execution_command_id != command_decision_id
                or attempted_command_id != execution_command_id
                or not plan_token
                or plan_token != command_token
                or not venue_order_id
            ):
                conn.execute(f"RELEASE SAVEPOINT {sp_name}")
                summary["stayed"] += 1
                continue

            receipt_hash = stable_hash(
                {
                    "source": "command_recovery_edli_ack_sync",
                    "command_id": command_id,
                    "execution_command_id": execution_command_id,
                    "venue_order_id": venue_order_id,
                    "command_updated_at": str(record.get("command_updated_at") or ""),
                }
            )
            ack_event = _append_edli_event_qualified(
                conn,
                events_ref=events_ref,
                aggregate_id=aggregate_id,
                event_type="VenueSubmitAcknowledged",
                payload={
                    "schema_version": 1,
                    "event_id": event_id,
                    "final_intent_id": final_intent_id,
                    "execution_command_id": execution_command_id,
                    "execution_receipt_hash": receipt_hash,
                    "venue_order_id": venue_order_id,
                    "venue_ack_received": True,
                    "raw_response_hash": "",
                    "recovery_reason": "TRADE_COMMAND_ACKED_WORLD_LEDGER_STALLED",
                    "command_id": command_id,
                    "source_proof": {
                        "source_function": "command_recovery.reconcile_edli_acknowledged_venue_command_sync",
                        "trade_command_state": str(record.get("state") or ""),
                        "trade_command_venue_order_id": venue_order_id,
                    },
                },
                occurred_at=occurred_at,
                source_authority="existing_executor",
            )
            updated = conn.execute(
                f"""
                UPDATE {cap_usage_ref}
                SET reservation_status = 'CONSUMED',
                    final_intent_id = ?,
                    execution_command_id = ?
                WHERE usage_id = ?
                  AND reservation_status = 'RESERVED'
                """,
                (final_intent_id, execution_command_id, str(record.get("usage_id") or "")),
            )
            if updated.rowcount != 1:
                raise ValueError("EDLI ACK sync failed to consume reserved cap")
            _append_edli_event_qualified(
                conn,
                events_ref=events_ref,
                aggregate_id=aggregate_id,
                event_type="CapTransitioned",
                payload={
                    "schema_version": 1,
                    "event_id": event_id,
                    "final_intent_id": final_intent_id,
                    "execution_command_id": execution_command_id,
                    "execution_receipt_hash": receipt_hash,
                    "to_status": "CONSUMED",
                    "projection_status": "CONSUMED",
                    "transition_reason": "TRADE_COMMAND_ACKED_WORLD_LEDGER_STALLED",
                    "acknowledged_event_hash": ack_event["event_hash"],
                    "venue_order_id": venue_order_id,
                    "command_id": command_id,
                },
                occurred_at=occurred_at,
                source_authority="live_cap_ledger",
            )
            _rebuild_edli_projection_qualified(
                conn,
                events_ref=events_ref,
                projection_ref=projection_ref,
                aggregate_id=aggregate_id,
            )
            conn.execute(f"RELEASE SAVEPOINT {sp_name}")
            summary["advanced"] += 1
            logger.warning(
                "recovery: EDLI ACK sync consumed cap for aggregate=%s command=%s venue_order_id=%s",
                aggregate_id,
                command_id,
                venue_order_id,
            )
        except Exception as exc:
            conn.execute(f"ROLLBACK TO SAVEPOINT {sp_name}")
            conn.execute(f"RELEASE SAVEPOINT {sp_name}")
            logger.error("recovery: EDLI ACK sync failed for command %s: %s", command_id, exc)
            summary["errors"] += 1
    return summary


def reconcile_edli_rejected_venue_command_sync(conn: sqlite3.Connection) -> dict:
    """Mirror terminal no-fill venue command rejection back into EDLI.

    A command can be authenticated-absence-rejected by the trade-side recovery
    lane after the EDLI aggregate has only reached ExecutionCommandCreated. The
    command/collateral state is terminal, but the EDLI live-cap reservation stays
    RESERVED and the family remains locked unless this pass appends the missing
    aggregate events and releases the cap.
    """

    summary = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
    events_ref = _edli_live_order_events_ref(conn)
    projection_ref = _edli_live_order_projection_ref(conn)
    cap_usage_ref = _edli_live_cap_ref(conn, "edli_live_cap_usage")
    day_slots_ref = _edli_live_cap_ref(conn, "edli_live_cap_day_slots")
    rate_window_ref = _edli_live_cap_ref(conn, "edli_live_cap_rate_window")
    if not events_ref or not projection_ref or not cap_usage_ref or not _table_exists(conn, "venue_commands"):
        return summary
    rows = conn.execute(
        f"""
        SELECT proj.aggregate_id,
               proj.event_id,
               proj.final_intent_id,
               proj.current_state,
               proj.last_event_type,
               plan.payload_json AS plan_payload_json,
               usage.usage_id,
               usage.execution_command_id,
               cmd.command_id,
               cmd.decision_id,
               cmd.idempotency_key,
               cmd.token_id,
               cmd.state,
               cmd.venue_order_id,
               cmd.updated_at AS command_updated_at,
               rejected.payload_json AS rejected_payload_json
        FROM {projection_ref} proj
        JOIN {events_ref} plan
          ON plan.aggregate_id = proj.aggregate_id
         AND plan.event_type = 'SubmitPlanBuilt'
        JOIN {cap_usage_ref} usage
          ON usage.event_id = proj.event_id
         AND usage.final_intent_id = proj.final_intent_id
         AND usage.reservation_status = 'RESERVED'
        JOIN venue_commands cmd
          ON cmd.decision_id = usage.execution_command_id
        JOIN venue_command_events rejected
          ON rejected.command_id = cmd.command_id
         AND rejected.event_type = 'SUBMIT_REJECTED'
        WHERE proj.current_state IN ('EXECUTION_COMMAND_CREATED', 'VENUE_SUBMIT_ATTEMPTED')
          AND proj.last_event_type IN ('ExecutionCommandCreated', 'VenueSubmitAttempted')
          AND COALESCE(proj.venue_order_id, '') = ''
          AND COALESCE(proj.pending_reconcile, 0) = 0
          AND cmd.intent_kind = 'ENTRY'
          AND cmd.state IN ('REJECTED', 'SUBMIT_REJECTED')
          AND COALESCE(cmd.venue_order_id, '') = ''
          AND NOT EXISTS (
              SELECT 1 FROM {events_ref} terminal
              WHERE terminal.aggregate_id = proj.aggregate_id
                AND terminal.event_type IN (
                    'VenueSubmitAcknowledged', 'SubmitRejected', 'SubmitUnknown',
                    'Reconciled', 'CapTransitioned', 'UserOrderObserved',
                    'UserTradeObserved'
                )
          )
        ORDER BY cmd.updated_at, proj.aggregate_id
        """
    ).fetchall()
    summary["scanned"] = len(rows)
    occurred_at = _now_iso()
    for row in rows:
        record = _dict_row(row)
        aggregate_id = str(record.get("aggregate_id") or "")
        command_id = str(record.get("command_id") or "")
        safe_command_id = "".join(ch if ch.isalnum() else "_" for ch in command_id) or "unknown"
        sp_name = f"sp_edli_rejected_sync_{safe_command_id}"
        conn.execute(f"SAVEPOINT {sp_name}")
        try:
            plan_payload = _json_dict(record.get("plan_payload_json"))
            rejected_payload = _json_dict(record.get("rejected_payload_json"))
            event_id = str(record.get("event_id") or plan_payload.get("event_id") or "")
            final_intent_id = str(record.get("final_intent_id") or plan_payload.get("final_intent_id") or "")
            execution_command_id = str(record.get("execution_command_id") or "")
            command_decision_id = str(record.get("decision_id") or "")
            plan_token = str(plan_payload.get("token_id") or "")
            command_token = str(record.get("token_id") or "")
            if (
                not aggregate_id
                or not event_id
                or not final_intent_id
                or not execution_command_id
                or execution_command_id != command_decision_id
                or not plan_token
                or plan_token != command_token
                or str(record.get("venue_order_id") or "").strip()
            ):
                conn.execute(f"RELEASE SAVEPOINT {sp_name}")
                summary["stayed"] += 1
                continue
            proof = rejected_payload.get("venue_absence_proof")
            proof = proof if isinstance(proof, dict) else {}
            try:
                matching_open = int(proof.get("matching_open_order_count", -1))
                matching_trade = int(proof.get("matching_trade_count", -1))
            except (TypeError, ValueError):
                matching_open = matching_trade = -1
            if (
                rejected_payload.get("safe_replay_permitted") is not True
                or matching_open != 0
                or matching_trade != 0
                or str(proof.get("token_id") or command_token) != command_token
            ):
                conn.execute(f"RELEASE SAVEPOINT {sp_name}")
                summary["stayed"] += 1
                continue

            receipt_hash = stable_hash(
                {
                    "source": "command_recovery_edli_rejected_sync",
                    "command_id": command_id,
                    "decision_id": execution_command_id,
                    "command_updated_at": record.get("command_updated_at"),
                    "reason": rejected_payload.get("reason"),
                }
            )
            if str(record.get("last_event_type") or "") == "ExecutionCommandCreated":
                _append_edli_event_qualified(
                    conn,
                    events_ref=events_ref,
                    aggregate_id=aggregate_id,
                    event_type="VenueSubmitAttempted",
                    payload={
                        "schema_version": 1,
                        "event_id": event_id,
                        "final_intent_id": final_intent_id,
                        "execution_command_id": execution_command_id,
                        "idempotency_key": record.get("idempotency_key"),
                        "recovered_from_venue_command_id": command_id,
                        "recovery_reason": "terminal_venue_command_rejected_sync",
                    },
                    occurred_at=occurred_at,
                    source_authority="existing_executor",
                )
            _append_edli_event_qualified(
                conn,
                events_ref=events_ref,
                aggregate_id=aggregate_id,
                event_type="SubmitRejected",
                payload={
                    "schema_version": 1,
                    "event_id": event_id,
                    "final_intent_id": final_intent_id,
                    "execution_command_id": execution_command_id,
                    "execution_receipt_hash": receipt_hash,
                    "reason_code": "VENUE_COMMAND_REJECTED_NO_VENUE_EXPOSURE",
                    "submit_status": "REJECTED",
                    "venue_call_started": True,
                    "venue_ack_received": False,
                    "pre_submit_rejection": False,
                    "venue_order_id": None,
                    "command_id": command_id,
                    "proof_class": "venue_command_authenticated_absence_rejected",
                    "safe_replay_permitted": True,
                    "venue_absence_proof": proof,
                    "source_rejected_payload": {
                        "reason": rejected_payload.get("reason"),
                        "lookup_method": rejected_payload.get("lookup_method"),
                        "recovered_from_state": rejected_payload.get("recovered_from_state"),
                    },
                },
                occurred_at=occurred_at,
                source_authority="existing_executor",
            )
            conn.execute(
                f"UPDATE {cap_usage_ref} SET reservation_status = 'RELEASED' WHERE usage_id = ?",
                (str(record.get("usage_id") or ""),),
            )
            if day_slots_ref:
                conn.execute(f"DELETE FROM {day_slots_ref} WHERE usage_id = ?", (str(record.get("usage_id") or ""),))
            if rate_window_ref:
                conn.execute(f"DELETE FROM {rate_window_ref} WHERE usage_id = ?", (str(record.get("usage_id") or ""),))
            _append_edli_event_qualified(
                conn,
                events_ref=events_ref,
                aggregate_id=aggregate_id,
                event_type="CapTransitioned",
                payload={
                    "schema_version": 1,
                    "event_id": event_id,
                    "final_intent_id": final_intent_id,
                    "execution_command_id": execution_command_id,
                    "execution_receipt_hash": receipt_hash,
                    "to_status": "RELEASED",
                    "projection_status": "RELEASED",
                    "transition_reason": "VENUE_COMMAND_REJECTED_NO_VENUE_EXPOSURE",
                    "command_id": command_id,
                },
                occurred_at=occurred_at,
                source_authority="live_cap_ledger",
            )
            _rebuild_edli_projection_qualified(
                conn,
                events_ref=events_ref,
                projection_ref=projection_ref,
                aggregate_id=aggregate_id,
            )
            conn.execute(f"RELEASE SAVEPOINT {sp_name}")
            summary["advanced"] += 1
        except Exception as exc:
            conn.execute(f"ROLLBACK TO SAVEPOINT {sp_name}")
            conn.execute(f"RELEASE SAVEPOINT {sp_name}")
            logger.error(
                "recovery: command %s EDLI rejected-command sync failed: %s",
                command_id,
                exc,
            )
            summary["errors"] += 1
    return summary


def _reconcile_edli_pre_venue_unknown_thresholds(conn: sqlite3.Connection) -> dict:
    summary = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
    events_ref = _edli_live_order_events_ref(conn)
    projection_ref = _edli_live_order_projection_ref(conn)
    cap_usage_ref = _edli_live_cap_ref(conn, "edli_live_cap_usage")
    if not events_ref or not projection_ref or not cap_usage_ref:
        return summary
    threshold_reason = "EXECUTOR_SUBMIT_UNKNOWN:unknown_side_effect_threshold"
    gate_runtime_prefix = "EXECUTOR_SUBMIT_UNKNOWN:[gate_runtime] BLOCKED"
    rows = conn.execute(
        f"""
        SELECT proj.aggregate_id,
               json_extract(unknown.payload_json, '$.execution_command_id') AS execution_command_id,
               json_extract(unknown.payload_json, '$.reason_code') AS reason_code,
               unknown.payload_json AS unknown_payload_json
        FROM {projection_ref} proj
        JOIN {events_ref} unknown
          ON unknown.aggregate_id = proj.aggregate_id
         AND unknown.event_type = 'SubmitUnknown'
        WHERE proj.pending_reconcile = 1
          AND COALESCE(proj.venue_order_id, '') = ''
          AND COALESCE(json_extract(unknown.payload_json, '$.venue_call_started'), 0) = 0
          AND COALESCE(json_extract(unknown.payload_json, '$.side_effect_known'), 0) = 0
          AND (
              json_extract(unknown.payload_json, '$.reason_code') = ?
              OR json_extract(unknown.payload_json, '$.reason_code') LIKE ?
          )
          AND NOT EXISTS (
              SELECT 1
              FROM venue_commands cmd
              WHERE cmd.decision_id = json_extract(unknown.payload_json, '$.execution_command_id')
          )
        ORDER BY unknown.occurred_at
        """,
        (threshold_reason, f"{gate_runtime_prefix}%"),
    ).fetchall()
    for row in rows:
        summary["scanned"] += 1
        execution_command_id = str(row["execution_command_id"] or "")
        reason_code = str(row["reason_code"] or "")
        if reason_code == threshold_reason:
            reason = "pre_venue_risk_allocator_block_misclassified_unknown"
            proof_class = "pre_venue_no_command_no_venue_order"
        else:
            reason = "pre_venue_gate_runtime_block_misclassified_unknown"
            proof_class = "pre_venue_gate_runtime_block_no_command_no_venue_order"
        conn.execute("SAVEPOINT edli_pre_venue_unknown_threshold_reconcile")
        try:
            advanced = _reconcile_edli_pending_no_order_if_proven(
                conn,
                execution_command_id=execution_command_id,
                occurred_at=_now_iso(),
                reason=reason,
                proof_class=proof_class,
                command_id=None,
                required_predicates={
                    "reason_code": reason_code,
                    "no_venue_command": True,
                    "no_projection_venue_order_id": True,
                    "pending_reconcile": True,
                    "pre_venue_reason_whitelisted": True,
                },
            )
            conn.execute("RELEASE SAVEPOINT edli_pre_venue_unknown_threshold_reconcile")
            if advanced:
                summary["advanced"] += 1
            else:
                summary["stayed"] += 1
        except Exception as exc:
            conn.execute("ROLLBACK TO SAVEPOINT edli_pre_venue_unknown_threshold_reconcile")
            conn.execute("RELEASE SAVEPOINT edli_pre_venue_unknown_threshold_reconcile")
            logger.error(
                "recovery: EDLI pre-venue unknown-threshold reconcile failed for %s: %s",
                execution_command_id,
                exc,
            )
            summary["errors"] += 1
    return summary


def _edli_post_submit_unknown_absence_candidates(conn: sqlite3.Connection) -> list[dict]:
    events_ref = _edli_live_order_events_ref(conn)
    projection_ref = _edli_live_order_projection_ref(conn)
    if not events_ref or not projection_ref:
        return []
    rows = conn.execute(
        f"""
        SELECT proj.aggregate_id,
               json_extract(plan.payload_json, '$.token_id') AS token_id,
               json_extract(unknown.payload_json, '$.execution_command_id') AS execution_command_id,
               json_extract(unknown.payload_json, '$.reason_code') AS reason_code
        FROM {projection_ref} proj
        JOIN {events_ref} unknown
          ON unknown.aggregate_id = proj.aggregate_id
         AND unknown.event_type = 'SubmitUnknown'
        JOIN {events_ref} plan
          ON plan.aggregate_id = proj.aggregate_id
         AND plan.event_type = 'SubmitPlanBuilt'
        WHERE proj.pending_reconcile = 1
          AND COALESCE(proj.venue_order_id, '') = ''
          AND json_extract(unknown.payload_json, '$.venue_call_started') = 1
          AND COALESCE(json_extract(unknown.payload_json, '$.side_effect_known'), 0) = 0
          AND NOT EXISTS (
              SELECT 1
              FROM {events_ref} unsafe
              WHERE unsafe.aggregate_id = proj.aggregate_id
                AND unsafe.event_type IN (
                    'VenueSubmitAcknowledged',
                    'UserOrderObserved',
                    'UserTradeObserved'
                )
          )
          AND NOT EXISTS (
              SELECT 1
              FROM venue_commands cmd
              WHERE cmd.decision_id = json_extract(unknown.payload_json, '$.execution_command_id')
          )
        ORDER BY unknown.occurred_at
        """
    ).fetchall()
    return [_dict_row(row) for row in rows]


def _apply_edli_post_submit_unknown_absence(
    conn: sqlite3.Connection,
    rows: list[dict],
    open_read,
    trade_read,
) -> dict:
    del conn, open_read, trade_read
    # A complete account snapshot is still only a point-in-time observation.
    # It cannot prove that an already-started submit will not become visible
    # after NETWORK and before APPLY. Releasing duplicate/cap authority from
    # token-level absence therefore creates a double-submit race. Only a
    # command/order/trade fact causally bound to the original submit may clear
    # this state.
    count = len(rows)
    if count:
        logger.warning(
            "recovery: keeping %d post-submit unknown aggregates fail-closed; "
            "account snapshot absence is not causal side-effect proof",
            count,
        )
    return {"scanned": count, "advanced": 0, "stayed": count, "errors": 0}


def _reconcile_edli_post_submit_unknown_absence(
    conn: sqlite3.Connection,
    client,
) -> dict:
    """Keep EDLI post-submit unknowns fail-closed until causal proof arrives.

    This covers the no-venue-command gap: the live-order aggregate reached
    SubmitUnknown/PENDING_RECONCILE, but no venue_commands row was ever persisted
    for the execution_command_id. A point-in-time account absence snapshot is not
    causal proof that the started submit cannot appear later, so this pass never
    releases replay, duplicate-lock, or cap authority.
    """

    del client
    rows = _edli_post_submit_unknown_absence_candidates(conn)
    return _apply_edli_post_submit_unknown_absence(conn, rows, None, None)


def _decision_log_pre_sdk_proof(
    conn: sqlite3.Connection,
    command: dict,
) -> dict | None:
    decision_id = str(command.get("decision_id") or "")
    if not decision_id:
        return None
    rows = _causal_decision_log_rows(conn, command)
    for row in rows:
        record = _dict_row(row)
        artifact = _json_dict(record.get("artifact_json"))
        for case in artifact.get("no_trade_cases") or []:
            if not isinstance(case, dict) or case.get("decision_id") != decision_id:
                continue
            reasons = case.get("rejection_reasons") or []
            if isinstance(reasons, str):
                reasons = [reasons]
            reason_text = " | ".join(str(reason) for reason in reasons)
            if case.get("rejection_stage") != "EXECUTION_FAILED":
                return None
            if "execution_intent_rejected:" not in reason_text:
                return None
            if not any(marker in reason_text for marker in _PRE_SDK_COLLATERAL_REASON_MARKERS):
                return None
            return {
                "decision_log_id": record.get("id"),
                "mode": record.get("mode"),
                "started_at": record.get("started_at"),
                "completed_at": record.get("completed_at"),
                "rejection_stage": case.get("rejection_stage"),
                "rejection_reasons": list(reasons),
                "city": case.get("city"),
                "target_date": case.get("target_date"),
                "range_label": case.get("range_label"),
            }
    return None


def _raw_payload(item) -> dict:
    raw = getattr(item, "raw", item)
    return raw if isinstance(raw, dict) else {}


def _epoch_seconds(value) -> float | None:
    if value in (None, ""):
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        pass
    try:
        text = str(value)
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        return datetime.fromisoformat(text).timestamp()
    except ValueError:
        return None


def _raw_mentions_token(raw: dict, token_id: str) -> bool:
    token_fields = (
        "asset_id",
        "token_id",
        "selected_outcome_token_id",
        "outcome_token_id",
    )
    if any(str(raw.get(field) or "") == token_id for field in token_fields):
        return True
    for maker in raw.get("maker_orders") or []:
        if isinstance(maker, dict) and any(str(maker.get(field) or "") == token_id for field in token_fields):
            return True
    return False


def _decimal_matches(left, right) -> bool:
    try:
        return Decimal(str(left)) == Decimal(str(right))
    except (InvalidOperation, TypeError):
        return False


def _fill_price_respects_limit(fill_price, limit_price, *, side: object) -> bool:
    """Return whether a realized fill is no worse than the submitted limit."""

    fill = _positive_decimal_or_none(fill_price)
    limit = _positive_decimal_or_none(limit_price)
    if fill is None or limit is None or fill > 1 or limit > 1:
        return False
    # REST trade aggregation can recover a maker price a few sub-micro units
    # beyond its submitted decimal after complementary-outcome conversion.
    # One USDC precision unit is accounting noise; anything larger remains a
    # genuine limit violation.
    tolerance = Decimal("0.000001")
    normalized_side = str(side or "").upper()
    if normalized_side == "BUY":
        if fill <= limit:
            return True
        return fill <= limit + tolerance and fill <= LIVE_ORDER_MAX_UNIT_PRICE
    if normalized_side == "SELL":
        if fill >= limit:
            return True
        return fill + tolerance >= limit and fill >= LIVE_ORDER_MIN_UNIT_PRICE
    return False


def _fill_size_completes_limit_order(filled_size, command_size, *, side: object) -> bool:
    """Require a full fill while respecting BUY/SELL quantity semantics."""

    filled = _positive_decimal_or_none(filled_size)
    requested = _positive_decimal_or_none(command_size)
    if filled is None or requested is None:
        return False
    residual = requested - filled
    normalized_side = str(side or "").upper()
    if normalized_side == "BUY":
        return residual <= Decimal("0.01")
    if normalized_side == "SELL":
        return -Decimal("0.000001") <= residual <= Decimal("0.01")
    return False


def _raw_matches_command_exposure(raw: dict, command: dict) -> bool:
    token_id = str(command.get("token_id") or "")
    if _raw_mentions_token(raw, token_id):
        return True
    market_id = str(command.get("market_id") or "")
    raw_market = str(raw.get("market") or raw.get("market_id") or raw.get("condition_id") or "")
    if market_id and raw_market != market_id:
        return False
    side = str(command.get("side") or "").upper()
    raw_side = str(raw.get("side") or "").upper()
    if side and raw_side and raw_side != side:
        return False
    if not _decimal_matches(raw.get("price"), command.get("price")):
        return False
    raw_size = _order_original_size(raw)
    return _decimal_matches(raw_size, command.get("size"))


def _raw_matches_command_submit_identity(raw: dict, command: dict) -> bool:
    token_id = str(command.get("token_id") or "")
    if not token_id or not _raw_mentions_token(raw, token_id):
        return False
    raw_side = str(raw.get("side") or "").upper()
    if raw_side != str(command.get("side") or "").upper():
        return False
    if not _decimal_matches(raw.get("price"), command.get("price")):
        return False
    raw_size = _order_original_size(raw)
    if not _decimal_matches(raw_size, command.get("size")):
        return False
    status = _order_status(raw)
    return not status or status in _LIVE_ORDER_STATUSES


def _raw_matches_command_submit_trade_identity(raw: dict, command: dict) -> bool:
    if _review_required_trade_maker_match(command, raw) is not None:
        return True
    token_id = str(command.get("token_id") or "")
    if not token_id or not _raw_mentions_token(raw, token_id):
        return False
    raw_side = str(raw.get("side") or "").upper()
    if not raw_side or raw_side != str(command.get("side") or "").upper():
        return False
    if not _decimal_matches(raw.get("price"), command.get("price")):
        return False
    raw_size = _order_original_size(raw)
    return _decimal_matches(raw_size, command.get("size"))


def _summarize_venue_match(raw: dict) -> dict:
    return {
        "id": raw.get("id") or raw.get("order_id") or raw.get("taker_order_id"),
        "status": _order_status(raw),
        "asset_id": raw.get("asset_id") or raw.get("token_id"),
        "price": raw.get("price"),
        "size": _order_original_size(raw),
        "match_time": raw.get("match_time"),
        "last_update": raw.get("last_update"),
    }


def _detached_terminal_ghost_open_orders(
    conn: sqlite3.Connection,
    *,
    current_command: VenueCommand,
    matching_open_orders: Sequence[Mapping[str, object]],
) -> list[dict[str, object]] | None:
    """Prove every exposure-level open match belongs to an older ghost.

    SCOPE: only the exact matching open-order identities returned by the same
    complete authenticated account snapshot used for the current unknown
    submit. DRAIN: each older terminal command keeps its own unresolved
    exchange-ghost cancel obligation. RESET: the current command may be
    terminalized only while its exact point order is independently absent;
    any unowned, nonterminal, same/newer, or trade-matched exposure fails closed.
    """

    matches = list(matching_open_orders)
    if not matches:
        return None
    current_created = _epoch_seconds(current_command.created_at)
    if current_created is None:
        return None
    detached: list[dict[str, object]] = []
    for match in matches:
        order_id = str(
            match.get("id")
            or match.get("order_id")
            or match.get("orderID")
            or ""
        ).strip()
        if not order_id or order_id == str(current_command.venue_order_id or ""):
            return None
        rows = conn.execute(
            """
            SELECT owner.command_id, owner.state, owner.market_id, owner.token_id,
                   owner.side, owner.created_at, finding.finding_id
              FROM venue_commands AS owner
              JOIN exchange_reconcile_findings AS finding
                ON finding.kind = 'exchange_ghost_order'
               AND finding.subject_id = owner.venue_order_id
               AND finding.resolved_at IS NULL
               AND finding.context = 'operator'
               AND json_valid(finding.evidence_json)
               AND json_extract(finding.evidence_json, '$.reason') =
                   'terminal_command_venue_order_reappeared_open'
             WHERE owner.venue_order_id = ?
               AND owner.state IN ('CANCELLED', 'EXPIRED', 'REJECTED', 'SUBMIT_REJECTED')
            """,
            (order_id,),
        ).fetchall()
        owners = {_dict_row(row)["command_id"]: _dict_row(row) for row in rows}
        if len(owners) != 1:
            return None
        owner = next(iter(owners.values()))
        owner_created = _epoch_seconds(owner.get("created_at"))
        if (
            owner_created is None
            or owner_created >= current_created
            or str(owner.get("command_id") or "") == current_command.command_id
            or str(owner.get("market_id") or "") != current_command.market_id
            or str(owner.get("token_id") or "") != current_command.token_id
            or str(owner.get("side") or "").upper()
            != str(current_command.side or "").upper()
        ):
            return None
        detached.append(
            {
                "venue_order_id": order_id,
                "owner_command_id": str(owner["command_id"]),
                "owner_command_state": str(owner["state"]),
                "owner_created_at": str(owner["created_at"]),
                "exchange_ghost_finding_id": str(owner["finding_id"]),
            }
        )
    return detached


def build_review_required_no_venue_exposure_proof(
    conn: sqlite3.Connection,
    command_id: str,
    adapter,
    *,
    observed_at: str | None = None,
) -> dict:
    """Read venue surfaces and prove a REVIEW_REQUIRED command has no exposure."""

    command = _review_required_command(conn, command_id)
    events = _command_events(conn, command_id)
    review_reason = _latest_review_required_payload(events).get("reason")
    if review_reason not in _NO_VENUE_EXPOSURE_REVIEW_REASONS:
        raise ValueError("no-exposure proof only supports no-venue-order-id recovery")
    token_id = str(command.get("token_id") or "")
    created_epoch = _epoch_seconds(command.get("created_at")) or 0.0
    now = observed_at or _now_iso()
    open_orders = list(adapter.get_open_orders())
    trades = list(adapter.get_trades())
    matching_open = [
        _summarize_venue_match(raw)
        for raw in (_raw_payload(order) for order in open_orders)
        if _raw_matches_command_submit_identity(raw, command)
    ]
    matching_trades = []
    for trade in trades:
        raw = _raw_payload(trade)
        if not _raw_matches_command_submit_trade_identity(raw, command):
            continue
        trade_epoch = _epoch_seconds(raw.get("match_time") or raw.get("last_update"))
        if trade_epoch is not None and trade_epoch < created_epoch:
            continue
        matching_trades.append(_summarize_venue_match(raw))
    return {
        "schema_version": 1,
        "source": "authenticated_clob_user_read",
        "owner_scope": "authenticated_funder",
        "observed_at": now,
        "command_id": command_id,
        "decision_id": str(command.get("decision_id") or ""),
        "market_id": str(command.get("market_id") or ""),
        "token_id": token_id,
        "side": str(command.get("side") or ""),
        "price": str(Decimal(str(command.get("price")))),
        "size": str(Decimal(str(command.get("size")))),
        "open_orders_checked": True,
        "trades_checked": True,
        "open_orders_query_complete": True,
        "trades_query_complete": True,
        "pagination_scope": "sdk_get_trades_returned_all_visible_user_trades",
        "time_window_start": command.get("created_at"),
        "time_window_end": now,
        "open_order_count": len(open_orders),
        "trade_count": len(trades),
        "matching_open_order_count": len(matching_open),
        "matching_trade_count": len(matching_trades),
        "matching_open_orders": matching_open[:10],
        "matching_trades": matching_trades[:10],
    }


def clear_review_required_no_venue_side_effect(
    conn: sqlite3.Connection,
    command_id: str,
    *,
    source_commit: str,
    source_function: str,
    source_reason: str,
    reviewed_by: str = "operator",
    occurred_at: str | None = None,
) -> dict:
    """Terminalize a REVIEW_REQUIRED command only with positive no-side-effect proof.

    This is not a generic state editor. It requires DB predicates proving no
    venue identity/facts/final envelope exist and decision-log evidence that
    the command's decision failed at a pre-SDK collateral boundary.
    """

    command = _review_required_command(conn, command_id)
    predicates, predicate_failures = _review_no_side_effect_predicates(conn, command)
    if predicate_failures:
        raise ValueError(
            "review clearance predicates failed: " + ", ".join(sorted(predicate_failures))
        )
    decision_id = str(command.get("decision_id") or "")
    decision_proof = _decision_log_pre_sdk_proof(conn, command)
    if decision_proof is None:
        raise ValueError(
            "review clearance requires decision_log EXECUTION_FAILED "
            "execution_intent_rejected collateral proof"
        )
    if not str(source_commit or "").strip():
        raise ValueError("source_commit is required")
    if source_function not in {"_live_order", "execute_exit_order"}:
        raise ValueError("source_function must identify the executor boundary")
    if not str(source_reason or "").strip():
        raise ValueError("source_reason is required")
    now = occurred_at or _now_iso()
    payload = {
        "schema_version": 1,
        "reason": "review_cleared_no_venue_side_effect",
        "command_id": command_id,
        "decision_id": decision_id,
        "proof_class": "pre_sdk_no_side_effect",
        "side_effect_boundary_crossed": False,
        "sdk_submit_attempted": False,
        "required_predicates": predicates,
        "source_proof": {
            "source_commit": source_commit,
            "source_function": source_function,
            "source_reason": source_reason,
            "decision_id": decision_id,
            "deployed_source_boundary": (
                "collateral reservation occurs before PolymarketClient construction "
                "and before place_limit_order"
            ),
        },
        "review_required_proof": {
            "reason": _latest_review_required_payload(
                _command_events(conn, command_id)
            ).get("reason"),
            "allowed_reasons": sorted(_PRE_SDK_REVIEW_REQUIRED_REASONS),
        },
        "decision_log_proof": decision_proof,
        "reviewed_by": reviewed_by,
        "cleared_at": now,
    }
    append_event(
        conn,
        command_id=command_id,
        event_type=CommandEventType.REVIEW_CLEARED_NO_VENUE_SIDE_EFFECT.value,
        occurred_at=now,
        payload=payload,
    )
    return payload


def _review_no_exposure_predicates(
    conn: sqlite3.Connection,
    command: dict,
) -> tuple[dict, list[str]]:
    predicates, _failures = _review_no_side_effect_predicates(conn, command)
    predicates.pop("review_required_reason_pre_sdk", None)
    latest_reason = _latest_review_required_payload(
        _command_events(conn, str(command["command_id"]))
    ).get("reason")
    predicates["review_required_reason_recovery_no_venue_order_id"] = (
        latest_reason in _NO_VENUE_EXPOSURE_REVIEW_REASONS
    )
    failures = [name for name, ok in predicates.items() if not ok]
    return predicates, failures


def clear_review_required_no_venue_exposure(
    conn: sqlite3.Connection,
    command_id: str,
    *,
    venue_absence_proof: dict,
    source_commit: str,
    source_function: str,
    reviewed_by: str = "operator",
    occurred_at: str | None = None,
) -> dict:
    """Terminalize recovery_no_venue_order_id only after fresh venue absence proof."""

    command = _review_required_command(conn, command_id)
    predicates, predicate_failures = _review_no_exposure_predicates(conn, command)
    if predicate_failures:
        raise ValueError(
            "review no-exposure predicates failed: " + ", ".join(sorted(predicate_failures))
        )
    latest_reason = _latest_review_required_payload(_command_events(conn, command_id)).get("reason")
    if latest_reason not in _NO_VENUE_EXPOSURE_REVIEW_REASONS:
        raise ValueError("review no-exposure clearance only supports no-venue-order-id recovery")
    if int(venue_absence_proof.get("matching_open_order_count", -1)) != 0:
        raise ValueError("review no-exposure clearance found matching open orders")
    if int(venue_absence_proof.get("matching_trade_count", -1)) != 0:
        raise ValueError("review no-exposure clearance found matching trades")
    if not str(source_commit or "").strip():
        raise ValueError("source_commit is required")
    if source_function not in {"command_recovery._reconcile_row", "operator_review"}:
        raise ValueError("source_function must identify the recovery/operator boundary")
    now = occurred_at or _now_iso()
    decision_id = str(command.get("decision_id") or "")
    payload = {
        "schema_version": 1,
        "reason": "review_cleared_no_venue_exposure",
        "command_id": command_id,
        "decision_id": decision_id,
        "proof_class": "venue_absence_no_exposure",
        "side_effect_boundary_crossed": "unknown",
        "sdk_submit_attempted": "unknown",
        "required_predicates": predicates,
        "venue_absence_proof": venue_absence_proof,
        "source_proof": {
            "source_commit": source_commit,
            "source_function": source_function,
            "source_reason": "recovery_no_venue_order_id",
        },
        "review_required_proof": {
            "reason": latest_reason,
            "allowed_reasons": sorted(_NO_VENUE_EXPOSURE_REVIEW_REASONS),
        },
        "reviewed_by": reviewed_by,
        "cleared_at": now,
    }
    append_event(
        conn,
        command_id=command_id,
        event_type=CommandEventType.REVIEW_CLEARED_NO_VENUE_EXPOSURE.value,
        occurred_at=now,
        payload=payload,
    )
    return payload


def _review_required_no_venue_live_order_recovery(
    conn: sqlite3.Connection,
    cmd: VenueCommand,
    client,
) -> str:
    events = _command_events(conn, cmd.command_id)
    latest_reason = _latest_review_required_payload(events).get("reason")
    if latest_reason not in _NO_VENUE_EXPOSURE_REVIEW_REASONS:
        return "stayed"
    if str(cmd.venue_order_id or "").strip():
        return "stayed"
    command = _dict_row(
        conn.execute(
            "SELECT * FROM venue_commands WHERE command_id = ?",
            (cmd.command_id,),
        ).fetchone()
    )
    try:
        open_orders = [_raw_payload(order) for order in _client_open_orders(client)]
        trades = [_raw_payload(trade) for trade in _client_trades(client)]
    except Exception as exc:  # noqa: BLE001 - recovery should retry on venue read failure.
        logger.warning(
            "recovery: command %s REVIEW_REQUIRED no-venue live-order proof read failed: %s",
            cmd.command_id,
            exc,
        )
        return "error"

    matching_open_orders = [
        raw
        for raw in open_orders
        if _raw_matches_command_submit_identity(raw, command)
    ]
    if len(matching_open_orders) != 1:
        if len(matching_open_orders) > 1:
            logger.warning(
                "recovery: command %s REVIEW_REQUIRED no-venue stayed; "
                "ambiguous matching open orders=%d",
                cmd.command_id,
                len(matching_open_orders),
            )
        return "stayed"

    matching_trades = _matching_trades_for_command(
        client,
        command,
        trades=trades,
    )
    if matching_trades:
        logger.info(
            "recovery: command %s REVIEW_REQUIRED no-venue stayed; "
            "matching trades=%d require fill authority",
            cmd.command_id,
            len(matching_trades),
        )
        return "stayed"

    order = dict(matching_open_orders[0])
    venue_order_id = str(_extract_order_id(order) or "").strip()
    status = _order_status(order) or "LIVE"
    matched_size = _point_order_matched_size(order, side=command.get("side"))
    if not venue_order_id or status not in _LIVE_ORDER_STATUSES or not _decimal_is_zero(matched_size):
        logger.info(
            "recovery: command %s REVIEW_REQUIRED no-venue stayed; "
            "order_id=%s status=%s matched_size=%s",
            cmd.command_id,
            venue_order_id or "<missing>",
            status or "UNKNOWN",
            matched_size,
        )
        return "stayed"

    now = _now_iso()
    order_summary = _summarize_venue_match(order)
    payload = {
        "schema_version": 1,
        "reason": "review_cleared_venue_order_live",
        "command_id": cmd.command_id,
        "venue_order_id": venue_order_id,
        "proof_class": "recovery_no_venue_order_id_live_order",
        "side_effect_boundary_crossed": True,
        "sdk_submit_attempted": True,
        "required_predicates": {
            "latest_event_is_review_required": True,
            "review_reason_recovery_no_venue_order_id": True,
            "venue_order_id_absent_before_recovery": True,
            "proof_venue_order_id_present": True,
            "unique_matching_open_order": True,
            "matching_open_order_matches_command": True,
            "authenticated_live_order_seen": True,
            "point_order_matched_size_not_positive": True,
            "no_matching_trades": True,
            "no_trade_facts": _count_facts(conn, "venue_trade_facts", cmd.command_id) == 0,
        },
        "venue_order_live_proof": {
            "source": "authenticated_clob_user_open_orders_read",
            "owner_scope": "authenticated_funder",
            "observed_at": now,
            "venue_order_id": venue_order_id,
            "point_order_status": status,
            "matched_size": matched_size,
            "matching_open_order_count": 1,
            "matching_trade_count": 0,
            "matching_open_orders": [order_summary],
            "point_order": order,
        },
        "source_proof": {
            "source_function": "command_recovery._reconcile_row",
            "source_reason": "recovery_no_venue_order_id_live_order",
        },
        "reviewed_by": "command_recovery",
        "cleared_at": now,
    }
    safe_command_id = "".join(ch if ch.isalnum() else "_" for ch in cmd.command_id)
    sp_name = f"sp_no_venue_live_order_{safe_command_id}"
    conn.execute(f"SAVEPOINT {sp_name}")
    try:
        append_event(
            conn,
            command_id=cmd.command_id,
            event_type=CommandEventType.REVIEW_CLEARED_VENUE_ORDER_LIVE.value,
            occurred_at=now,
            payload=payload,
        )
        append_order_fact(
            conn,
            venue_order_id=venue_order_id,
            command_id=cmd.command_id,
            state="RESTING" if status == "RESTING" else "LIVE",
            remaining_size=str(order.get("size") or order.get("remaining_size") or command.get("size") or ""),
            matched_size=matched_size,
            source="REST",
            observed_at=now,
            venue_timestamp=now,
            raw_payload_hash=_canonical_payload_hash(
                {
                    "source": "command_recovery_no_venue_live_order",
                    "command_id": cmd.command_id,
                    "venue_order_id": venue_order_id,
                    "exchange_order": order,
                }
            ),
            raw_payload_json={
                "source": "command_recovery_no_venue_live_order",
                "command_id": cmd.command_id,
                "venue_order_id": venue_order_id,
                "exchange_order": order,
            },
        )
        _resolve_m5_exchange_ghost_findings(
            conn,
            venue_order_id=venue_order_id,
            resolved_at=now,
            resolution="command_recovery_no_venue_live_order_adopted",
        )
        conn.execute(f"RELEASE SAVEPOINT {sp_name}")
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {sp_name}")
        conn.execute(f"RELEASE SAVEPOINT {sp_name}")
        raise
    logger.info(
        "recovery: command %s REVIEW_REQUIRED no-venue -> ACKED "
        "(venue_order_id=%s status=%s)",
        cmd.command_id,
        venue_order_id,
        status,
    )
    return "advanced"


def _review_required_cancel_failed_already_canceled_fill_recovery(
    conn: sqlite3.Connection,
    cmd: VenueCommand,
    client=None,
) -> str:
    """Clear a REVIEW_REQUIRED command when cancel failed after venue finality.

    This covers the post-live partial/full-fill race:
      ACKED -> CANCEL_REQUESTED -> venue already canceled -> legacy parser wrote
      CANCEL_FAILED/REVIEW_REQUIRED, while a positive trade fact already proves
      the exact venue side effect. ENTRY projects acquired exposure; EXIT
      projects sale truth or keeps a partial sale pending until the remainder
      is resolved.
    """

    # SCOPE: only the exact bound ENTRY/BUY or EXIT/SELL command whose latest
    # cancel result says the venue order is already canceled or matched.
    # DRAIN: canonical positive trade facts bound to that command+order advance
    # it to PARTIAL/FILLED; missing or contradictory truth stays REVIEW_REQUIRED.
    # RESET: the command event transition removes REVIEW_REQUIRED once and the
    # normal entry/exit projection lanes consume the durable fill facts.
    intent_side = (cmd.intent_kind, str(cmd.side or "").upper())
    if (
        cmd.state != CommandState.REVIEW_REQUIRED
        or intent_side
        not in {
            (IntentKind.ENTRY, "BUY"),
            (IntentKind.EXIT, "SELL"),
        }
        or not str(cmd.venue_order_id or "").strip()
    ):
        return "stayed"
    events = _command_events(conn, cmd.command_id)
    if _cancel_failed_already_canceled_payload(events) is None:
        return "stayed"
    rows = conn.execute(
        "WITH "
        + _canonical_trade_fact_cte()
        + ", "
        + _economic_trade_fact_cte()
        + """
        SELECT trade_fact_id,
               trade_id,
               venue_order_id,
               state,
               filled_size,
               fill_price,
               source,
               observed_at,
               venue_timestamp,
               tx_hash
          FROM economic_trade_fact
         WHERE command_id = ?
           AND venue_order_id = ?
           AND state IN ('MATCHED', 'MINED', 'CONFIRMED')
           AND CAST(COALESCE(filled_size, '0') AS REAL) > 0
           AND CAST(COALESCE(fill_price, '0') AS REAL) > 0
         ORDER BY proof_rank DESC, local_sequence DESC
        """,
        (cmd.command_id, str(cmd.venue_order_id)),
    ).fetchall()
    if not rows:
        logger.info(
            "recovery: command %s REVIEW_REQUIRED already-canceled stayed; "
            "positive trade fact count=%d",
            cmd.command_id,
            len(rows),
        )
        return "stayed"
    trade_facts = sorted(
        (_dict_row(row) for row in rows),
        key=lambda fact: str(fact.get("trade_id") or ""),
    )
    venue_order_id = str(cmd.venue_order_id or "")
    total_size = Decimal("0")
    total_cost = Decimal("0")
    observed_at = ""
    for trade_fact in trade_facts:
        if str(trade_fact.get("venue_order_id") or "") != venue_order_id:
            return "stayed"
        size = _positive_decimal_or_none(trade_fact.get("filled_size"))
        price = _positive_decimal_or_none(trade_fact.get("fill_price"))
        trade_id = str(trade_fact.get("trade_id") or "")
        if size is None or price is None or not trade_id:
            return "stayed"
        total_size += size
        total_cost += size * price
        fact_time = str(trade_fact.get("venue_timestamp") or trade_fact.get("observed_at") or "")
        if fact_time > observed_at:
            observed_at = fact_time
    if total_size <= 0 or total_cost <= 0:
        return "stayed"
    filled_size = format(total_size, "f")
    fill_price = format(total_cost / total_size, "f")
    observed_at = observed_at or _now_iso()
    command = _dict_row(
        conn.execute(
            "SELECT * FROM venue_commands WHERE command_id = ?",
            (cmd.command_id,),
        ).fetchone()
    )
    complete = _fill_size_completes_limit_order(
        filled_size,
        command.get("size"),
        side=command.get("side"),
    )
    if not complete and intent_side == (IntentKind.ENTRY, "BUY"):
        # "Already canceled or matched" proves only that the cancel response
        # raced venue finality; it does not prove the cumulative fill or that
        # no remainder is still live.  A partial ENTRY therefore uses the same
        # exact terminal-remainder proof as CANCEL_UNKNOWN.  DB-only recovery
        # deliberately stays REVIEW_REQUIRED until authenticated complete
        # account reads are available.
        if client is None:
            return "stayed"
        try:
            point_order = _venue_order_payload(client.get_order(venue_order_id))
            open_order_read = _client_read_items(client, "get_open_orders")
            trade_read = _client_read_items(client, "get_trades")
        except Exception as exc:
            logger.warning(
                "recovery: command %s REVIEW_REQUIRED already-canceled partial "
                "account proof unavailable: %s",
                cmd.command_id,
                exc,
            )
            return "error"
        point_order_no_live_record = _point_order_no_live_record(
            point_order,
            expected_order_id=venue_order_id,
        )
        point_order_terminal = bool(
            point_order is not None
            and _extract_order_id(point_order) == venue_order_id
            and _terminal_fact_state_for_venue_status(
                _order_status(point_order),
                venue_resp_present=True,
            )
            is not None
        )
        matching_open_orders = _matching_open_orders_for_command(
            client,
            command,
            open_orders=open_order_read.items,
        )
        return _review_required_cancel_unknown_terminal_partial_recovery(
            conn,
            command=command,
            point_order=point_order,
            point_order_no_live_record=point_order_no_live_record,
            point_order_terminal=point_order_terminal,
            matching_open_orders=matching_open_orders,
            account_trade_items=trade_read.items,
            venue_read_proof={
                "open_orders_query_complete": open_order_read.query_complete,
                "open_orders_pagination_scope": open_order_read.pagination_scope,
                "trades_query_complete": trade_read.query_complete,
                "trades_pagination_scope": trade_read.pagination_scope,
            },
        )
    aggregate_confirmed = all(
        str(fact.get("state") or "").upper() == "CONFIRMED"
        and str(fact.get("source") or "").upper() in {"REST", "WS_USER"}
        for fact in trade_facts
    )
    if complete and not aggregate_confirmed:
        return "stayed"
    order_fact_source = (
        "REST"
        if any(str(fact.get("source") or "").upper() == "REST" for fact in trade_facts)
        else "WS_USER"
    )
    intent_name = str(cmd.intent_kind.value).lower()
    event_type = (
        CommandEventType.FILL_CONFIRMED.value
        if complete
        else CommandEventType.PARTIAL_FILL_OBSERVED.value
    )
    payload = {
        "schema_version": 1,
        "reason": (
            "review_cleared_confirmed_fill"
            if complete
            else "terminal_partial_order_fact_corrected"
        ),
        "command_id": cmd.command_id,
        "decision_id": str(command.get("decision_id") or ""),
        "venue_order_id": venue_order_id,
        "trade_id": str(trade_facts[0].get("trade_id") or ""),
        "trade_ids": [str(fact.get("trade_id") or "") for fact in trade_facts],
        "filled_size": filled_size,
        "fill_price": fill_price,
        "proof_class": (
            "authenticated_trade_fact_full_fill"
            if complete
            else "terminal_partial_order_fact"
        ),
        "side_effect_boundary_crossed": True,
        "sdk_submit_attempted": True,
        "required_predicates": {
            **(
                {
                    "command_state_review_required": True,
                    "latest_event_is_review_boundary": True,
                    "authenticated_confirmed_trade_facts": True,
                    "bound_venue_order_id_matches_trade": True,
                    "trade_facts_cover_command_or_leave_only_dust": True,
                    "source_fill_time_valid": True,
                }
                if complete
                else {
                    "terminal_order_remainder_zero": True,
                    "canonical_trade_facts_match_terminal_order_fact": True,
                    "cumulative_fill_below_requested_size": True,
                }
            )
        },
        "matched_size": filled_size,
        "remaining_size": "0",
        "requested_size": str(command.get("size") or ""),
        "trade_fact_proof": [
            {
                "trade_fact_id": fact.get("trade_fact_id"),
                "trade_id": fact.get("trade_id"),
                "state": fact.get("state"),
                "source": fact.get("source"),
                "filled_size": fact.get("filled_size"),
                "fill_price": fact.get("fill_price"),
                "observed_at": fact.get("observed_at"),
                "venue_timestamp": fact.get("venue_timestamp"),
                "tx_hash": fact.get("tx_hash"),
            }
            for fact in trade_facts
        ],
        "source_proof": {
            "source_commit": "runtime",
            "source_function": "command_recovery._reconcile_row",
            "source_reason": (
                f"cancel_failed_already_canceled_positive_{intent_name}_fill"
            ),
        },
        "reviewed_by": "command_recovery",
        "cleared_at": observed_at,
    }
    safe_command_id = "".join(ch if ch.isalnum() else "_" for ch in cmd.command_id)
    sp_name = f"sp_already_cancelled_{intent_name}_fill_{safe_command_id}"
    conn.execute(f"SAVEPOINT {sp_name}")
    try:
        append_order_fact(
            conn,
            venue_order_id=venue_order_id,
            command_id=cmd.command_id,
            state="MATCHED" if complete else "PARTIALLY_MATCHED",
            remaining_size="0",
            matched_size=filled_size,
            source=order_fact_source,
            observed_at=observed_at,
            venue_timestamp=observed_at,
            raw_payload_hash=_payload_hash({**payload, "fact_type": "order"}),
            raw_payload_json=payload,
        )
        append_event(
            conn,
            command_id=cmd.command_id,
            event_type=event_type,
            occurred_at=observed_at,
            payload=payload,
        )
        if cmd.intent_kind == IntentKind.ENTRY:
            _append_matched_order_fill_projection(
                conn,
                command={**command, "venue_order_id": venue_order_id},
                venue_order_id=venue_order_id,
                matched_size=filled_size,
                fill_price=fill_price,
                observed_at=observed_at,
                order_fact_source=order_fact_source,
            )
        else:
            _append_exit_order_fill_projection(
                conn,
                command={**command, "venue_order_id": venue_order_id},
                venue_order_id=venue_order_id,
                matched_size=filled_size,
                fill_price=fill_price,
                observed_at=observed_at,
                event_type=event_type,
                raise_on_error=True,
            )
        conn.execute(f"RELEASE SAVEPOINT {sp_name}")
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {sp_name}")
        conn.execute(f"RELEASE SAVEPOINT {sp_name}")
        raise
    logger.info(
        "recovery: command %s REVIEW_REQUIRED already-canceled -> %s "
        "(venue_order_id=%s trade_id=%s filled_size=%s)",
        cmd.command_id,
        "FILLED" if complete else "PARTIAL",
        venue_order_id,
        str(trade_facts[0].get("trade_id") or ""),
        filled_size,
    )
    return "advanced"


def _review_required_cancel_failed_already_canceled_no_fill_recovery(
    conn: sqlite3.Connection,
    cmd: VenueCommand,
    client,
) -> str:
    """Expire a proven unfilled command after an idempotent cancel race."""

    # SCOPE: only the exact bound ENTRY/BUY or EXIT/SELL command whose cancel
    # response says already canceled/matched and whose authenticated account
    # reads all prove zero exposure.
    # DRAIN: terminal point-order zero fill + complete open-order/trade absence.
    # RESET: EXPIRED releases the entry commitment or the held position back to
    # continuous exit redecision; incomplete/ambiguous reads fail closed.
    intent_side = (cmd.intent_kind, str(cmd.side or "").upper())
    if (
        cmd.state != CommandState.REVIEW_REQUIRED
        or intent_side
        not in {
            (IntentKind.ENTRY, "BUY"),
            (IntentKind.EXIT, "SELL"),
        }
        or not str(cmd.venue_order_id or "").strip()
    ):
        return "stayed"
    events = _command_events(conn, cmd.command_id)
    if _cancel_failed_already_canceled_payload(events) is None:
        return "stayed"
    if _trade_fact_count(conn, cmd.command_id) != 0:
        return "stayed"

    command = _dict_row(
        conn.execute(
            "SELECT * FROM venue_commands WHERE command_id = ?",
            (cmd.command_id,),
        ).fetchone()
    )
    venue_order_id = str(cmd.venue_order_id or "")
    try:
        point_order = _venue_order_payload(client.get_order(venue_order_id))
        open_orders = _client_open_orders(client)
        trades = _client_trades(client)
    except Exception as exc:  # noqa: BLE001 - authenticated proof may retry later.
        logger.warning(
            "recovery: command %s REVIEW_REQUIRED already-canceled no-fill read failed: %s",
            cmd.command_id,
            exc,
        )
        return "error"
    if (
        point_order is None
        and getattr(client, "venue_reads_are_complete", False) is True
    ):
        point_order = {
            "orderID": venue_order_id,
            "status": "UNKNOWN",
            "source_error": "complete_snapshot_point_order_absence",
        }
    point_order_no_live_record = _point_order_no_live_record(
        point_order,
        expected_order_id=venue_order_id,
    )
    point_order_absence_complete = (
        getattr(client, "venue_reads_are_complete", False) is True
    )
    if (
        point_order is None
        or (
            _extract_order_id(point_order) != venue_order_id
            and not point_order_no_live_record
        )
    ):
        return "stayed"
    status = _order_status(point_order)
    venue_resp_present_for_terminal_state = None
    fact_state = _terminal_fact_state_for_venue_status(
        status,
        venue_resp_present=True,
    )
    no_fill_proven, _ = _terminal_point_order_zero_fill_proven(
        conn,
        command_id=cmd.command_id,
        point_order=point_order,
    )
    matching_open_orders = _matching_open_orders_for_command(
        client,
        command,
        open_orders=open_orders,
    )
    matching_trades = _matching_trades_for_command(
        client,
        command,
        trades=trades,
    )
    source_reason = "cancel_failed_already_canceled_point_order_terminal_no_fill"
    fact_source_reason = source_reason
    if (
        point_order_no_live_record
        and point_order_absence_complete
        and not matching_open_orders
        and not matching_trades
        and _fill_trade_fact_count(conn, cmd.command_id) == 0
    ):
        no_fill_proven = True
        fact_state = _terminal_fact_state_for_venue_status(
            status,
            venue_resp_present=False,
        )
        venue_resp_present_for_terminal_state = False
        fact_source_reason = (
            "cancel_failed_already_canceled_point_order_no_live_record_terminal_no_fill"
        )
    if fact_state is None or not no_fill_proven or matching_open_orders or matching_trades:
        return "stayed"

    current = _dict_row(
        conn.execute(
            "SELECT phase, shares, cost_basis_usd, order_id, city, target_date, "
            "strategy_key "
            "FROM position_current WHERE position_id = ? LIMIT 1",
            (str(command.get("position_id") or ""),),
        ).fetchone()
    )
    try:
        shares = Decimal(str(current.get("shares") or "0"))
        cost_basis = Decimal(str(current.get("cost_basis_usd") or "0"))
    except (InvalidOperation, TypeError, ValueError):
        return "stayed"
    phase = str(current.get("phase") or "")
    zero_pending = (
        phase in {"pending_entry", "voided"}
        and shares == 0
        and cost_basis == 0
    )
    existing_position = (
        cmd.intent_kind == IntentKind.ENTRY
        and phase in {"active", "day0_window", "pending_exit"}
        and shares > 0
        and cost_basis > 0
        and str(current.get("order_id") or "") != venue_order_id
    )
    existing_exit = (
        cmd.intent_kind == IntentKind.EXIT
        and phase in {"active", "day0_window", "pending_exit"}
        and shares > 0
        and cost_basis >= 0
    )
    if not (zero_pending or existing_position or existing_exit):
        return "stayed"

    finding_identity_exact, finding_id = _exact_m5_local_orphan_finding_id(
        conn,
        venue_order_id=venue_order_id,
    )
    if not finding_identity_exact:
        logger.info(
            "recovery: command %s REVIEW_REQUIRED already-canceled stayed "
            "(local-orphan finding identity is ambiguous)",
            cmd.command_id,
        )
        return "stayed"

    now = _now_iso()
    intent_name = str(cmd.intent_kind.value).lower()
    safe_command_id = "".join(ch if ch.isalnum() else "_" for ch in cmd.command_id)
    sp_name = f"sp_already_cancelled_{intent_name}_no_fill_{safe_command_id}"
    conn.execute(f"SAVEPOINT {sp_name}")
    try:
        fact_id, fact_payload = _append_point_order_terminal_no_fill_fact(
            conn,
            command=command,
            observed_at=now,
            venue_status=status,
            point_order=point_order,
            matching_open_orders=matching_open_orders,
            matching_trades=matching_trades,
            source_reason=fact_source_reason,
            venue_resp_present_for_terminal_state=venue_resp_present_for_terminal_state,
        )
        locked_identity_exact, locked_finding_id = _exact_m5_local_orphan_finding_id(
            conn,
            venue_order_id=venue_order_id,
        )
        if not locked_identity_exact or locked_finding_id != finding_id:
            raise RuntimeError("already-canceled local-orphan finding identity changed")
        resolved_findings = _resolve_m5_local_orphan_findings(
            conn,
            command_id=cmd.command_id,
            venue_order_id=venue_order_id,
            resolved_at=now,
            resolution="command_recovery_already_canceled_terminal_no_fill",
            finding_id=finding_id,
        )
        if finding_id is not None and resolved_findings != 1:
            raise RuntimeError(
                f"already-canceled exact finding CAS failed for {finding_id}"
            )
        if existing_exit:
            released = _release_exit_after_terminal_no_fill(
                conn,
                command={
                    **command,
                    "position_city": current.get("city"),
                    "position_target_date": current.get("target_date"),
                    "position_strategy_key": current.get("strategy_key"),
                },
                observed_at=now,
                order_fact_id=fact_id,
                terminal_payload=fact_payload,
            )
            if not released:
                raise RuntimeError(
                    "exit terminal no-fill proof did not release redecision "
                    f"for command {cmd.command_id}"
                )
        payload = {
            "schema_version": 1,
            "reason": "review_cleared_no_venue_exposure",
            "command_id": cmd.command_id,
            "venue_order_id": venue_order_id,
            "proof_class": "cancel_failed_already_canceled_terminal_no_fill",
            "side_effect_boundary_crossed": True,
            "sdk_cancel_attempted": True,
            "required_predicates": {
                "latest_event_is_cancel_failed": True,
                "cancel_failed_already_canceled": True,
                "venue_order_id_present": True,
                "venue_order_id_matches_point_read": True,
                "point_order_no_live_record": point_order_no_live_record,
                "point_order_absence_complete": point_order_absence_complete,
                "point_order_terminal_no_fill": True,
                "point_order_matched_size_zero": True,
                "no_trade_facts": True,
                "no_matching_open_orders": True,
                "no_matching_trades": True,
                "position_projection_not_bound_to_command": True,
                **(
                    {}
                    if cmd.intent_kind == IntentKind.ENTRY
                    else {
                        "position_retains_positive_shares": True,
                        "position_phase_allows_exit_redecision": True,
                    }
                ),
            },
            "terminal_order_fact_id": fact_id,
            "terminal_order_fact": fact_payload,
            "resolved_m5_local_orphan_finding_id": finding_id,
            "resolved_m5_local_orphan_findings": resolved_findings,
            "venue_absence_proof": {
                "source": "authenticated_clob_user_read",
                "owner_scope": "authenticated_funder",
                "observed_at": now,
                "command_id": cmd.command_id,
                "decision_id": str(command.get("decision_id") or ""),
                "market_id": str(command.get("market_id") or ""),
                "token_id": str(command.get("token_id") or ""),
                "side": str(command.get("side") or ""),
                "price": str(Decimal(str(command.get("price")))),
                "size": str(Decimal(str(command.get("size")))),
                "time_window_start": command.get("created_at"),
                "time_window_end": now,
                "open_orders_checked": True,
                "trades_checked": True,
                "open_orders_query_complete": True,
                "trades_query_complete": True,
                "pagination_scope": "sdk_get_trades_returned_all_visible_user_trades",
                "matching_open_order_count": 0,
                "matching_trade_count": 0,
                "matching_open_orders": [],
                "matching_trades": [],
                "point_order_status": status,
                "point_order": point_order,
            },
            "source_proof": {
                "source_commit": "runtime",
                "source_function": "command_recovery._reconcile_row",
                "source_reason": fact_source_reason,
            },
            "reviewed_by": "command_recovery",
            "cleared_at": now,
        }
        append_event(
            conn,
            command_id=cmd.command_id,
            event_type=CommandEventType.REVIEW_CLEARED_NO_VENUE_EXPOSURE.value,
            occurred_at=now,
            payload=payload,
        )
        if zero_pending:
            _append_entry_order_voided_projection(
                conn,
                command=command,
                order_fact={
                    **command,
                    "order_fact_id": fact_id,
                    "order_fact_state": fact_state,
                    "order_fact_observed_at": now,
                    "order_fact_venue_order_id": venue_order_id,
                    "order_fact_remaining_size": "0",
                    "order_fact_matched_size": "0",
                    "order_fact_source": "REST",
                },
                occurred_at=now,
            )
        conn.execute(f"RELEASE SAVEPOINT {sp_name}")
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {sp_name}")
        conn.execute(f"RELEASE SAVEPOINT {sp_name}")
        raise
    logger.info(
        "recovery: command %s REVIEW_REQUIRED already-canceled -> EXPIRED "
        "(venue_order_id=%s status=%s)",
        cmd.command_id,
        venue_order_id,
        status,
    )
    return "advanced"


def _review_required_matched_submit_trade_fact_recovery(
    conn: sqlite3.Connection,
    cmd: VenueCommand,
) -> str:
    """Promote an exact durable fill fact without waiting for venue I/O.

    ``matched_submit_missing_trade_id`` means submit already returned a bound
    order id and positive matched economics, but no trade identity.  The
    continuous fill synchronizer later appends the authenticated trade fact.
    Once exactly one canonical CONFIRMED fact covers the submitted BUY at a
    limit-respecting price, another network snapshot cannot add authority; it
    can only delay exposure projection and keep the governor in reduce-only.
    """

    if (
        cmd.state != CommandState.REVIEW_REQUIRED
        or cmd.intent_kind != IntentKind.ENTRY
        or str(cmd.side or "").upper() != "BUY"
        or not str(cmd.venue_order_id or "").strip()
    ):
        return "stayed"
    latest_reason = _latest_review_required_payload(
        _command_events(conn, cmd.command_id)
    ).get("reason")
    if latest_reason != "matched_submit_missing_trade_id":
        return "stayed"

    command = _dict_row(
        conn.execute(
            "SELECT * FROM venue_commands WHERE command_id = ?",
            (cmd.command_id,),
        ).fetchone()
    )
    rows = conn.execute(
        "WITH "
        + _canonical_trade_fact_cte()
        + ", "
        + _economic_trade_fact_cte()
        + """
        SELECT trade_fact_id,
               trade_id,
               venue_order_id,
               state,
               filled_size,
               fill_price,
               source,
               observed_at,
               venue_timestamp,
               tx_hash
          FROM economic_trade_fact
         WHERE command_id = ?
           AND venue_order_id = ?
           AND state = 'CONFIRMED'
           AND source IN ('REST', 'WS_USER')
           AND CAST(COALESCE(filled_size, '0') AS REAL) > 0
           AND CAST(COALESCE(fill_price, '0') AS REAL) > 0
         ORDER BY proof_rank DESC, local_sequence DESC
        """,
        (cmd.command_id, str(cmd.venue_order_id)),
    ).fetchall()
    if len(rows) != 1:
        return "stayed"
    trade_fact = _dict_row(rows[0])
    filled_size = str(trade_fact.get("filled_size") or "")
    fill_price = str(trade_fact.get("fill_price") or "")
    if not _fill_price_respects_limit(
        fill_price,
        command.get("price"),
        side=command.get("side"),
    ) or not _fill_size_completes_limit_order(
        filled_size,
        command.get("size"),
        side=command.get("side"),
    ):
        return "stayed"

    venue_order_id = str(trade_fact.get("venue_order_id") or "")
    trade_id = str(trade_fact.get("trade_id") or "")
    observed_at = str(trade_fact.get("observed_at") or _now_iso())
    payload = {
        "schema_version": 1,
        "reason": "review_cleared_confirmed_fill",
        "command_id": cmd.command_id,
        "decision_id": str(command.get("decision_id") or ""),
        "venue_order_id": venue_order_id,
        "trade_id": trade_id,
        "filled_size": filled_size,
        "fill_price": fill_price,
        "proof_class": "matched_submit_missing_trade_id_confirmed_trade",
        "side_effect_boundary_crossed": True,
        "sdk_submit_attempted": True,
        "required_predicates": {
            "latest_event_is_review_required": True,
            "review_reason_matched_submit_missing_trade_id": True,
            "positive_trade_fact": True,
            "maker_order_token_matches_command": True,
            "bound_venue_order_id_matches_trade": venue_order_id
            == str(cmd.venue_order_id),
            "maker_order_not_open": True,
            "venue_size_quantization_residual_lt_0_01": True,
        },
        "trade_fact_proof": {
            "trade_fact_id": trade_fact.get("trade_fact_id"),
            "state": trade_fact.get("state"),
            "source": trade_fact.get("source"),
            "observed_at": trade_fact.get("observed_at"),
            "venue_timestamp": trade_fact.get("venue_timestamp"),
            "tx_hash": trade_fact.get("tx_hash"),
        },
        "source_proof": {
            "source_commit": "runtime",
            "source_function": "command_recovery._reconcile_row",
            "source_reason": "durable_confirmed_trade_fact_precedes_venue_snapshot",
        },
        "reviewed_by": "command_recovery",
        "cleared_at": observed_at,
    }
    safe_command_id = "".join(
        ch if ch.isalnum() else "_" for ch in cmd.command_id
    )
    sp_name = f"sp_matched_submit_fact_{safe_command_id}"
    conn.execute(f"SAVEPOINT {sp_name}")
    try:
        append_order_fact(
            conn,
            venue_order_id=venue_order_id,
            command_id=cmd.command_id,
            state="MATCHED",
            remaining_size="0",
            matched_size=filled_size,
            source=str(trade_fact.get("source") or "REST"),
            observed_at=observed_at,
            venue_timestamp=str(
                trade_fact.get("venue_timestamp") or observed_at
            ),
            raw_payload_hash=_payload_hash({**payload, "fact_type": "order"}),
            raw_payload_json=payload,
        )
        append_event(
            conn,
            command_id=cmd.command_id,
            event_type=CommandEventType.FILL_CONFIRMED.value,
            occurred_at=observed_at,
            payload=payload,
        )
        _append_matched_order_fill_projection(
            conn,
            command={**command, "venue_order_id": venue_order_id},
            venue_order_id=venue_order_id,
            matched_size=filled_size,
            fill_price=fill_price,
            observed_at=observed_at,
            order_fact_source=str(trade_fact.get("source") or "REST"),
        )
        conn.execute(f"RELEASE SAVEPOINT {sp_name}")
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {sp_name}")
        conn.execute(f"RELEASE SAVEPOINT {sp_name}")
        raise
    logger.warning(
        "recovery: command %s REVIEW_REQUIRED matched-submit durable fact -> "
        "FILLED (venue_order_id=%s trade_id=%s filled_size=%s)",
        cmd.command_id,
        venue_order_id,
        trade_id,
        filled_size,
    )
    return "advanced"


def _authenticated_entry_trade_fact_candidates(
    conn: sqlite3.Connection,
    *,
    command_id: str | None = None,
) -> list[dict]:
    """Return live entry commands whose confirmed fills outrun command state."""

    if not all(
        _table_exists(conn, table)
        for table in (
            "venue_commands",
            "venue_submission_envelopes",
            "venue_trade_facts",
            "venue_command_events",
            "position_current",
            "position_events",
            "execution_fact",
        )
    ):
        return []
    params: list[object] = []
    command_clause = ""
    if str(command_id or "").strip():
        command_clause = " AND cmd.command_id = ?"
        params.append(str(command_id).strip())
    rows = conn.execute(
        "WITH "
        + _canonical_trade_fact_cte()
        + """
        SELECT cmd.*,
               envelope.order_type AS submission_order_type,
               envelope.price AS submission_price,
               envelope.size AS submission_size,
               pc.phase AS projected_phase,
               pc.shares AS projected_shares,
               pc.cost_basis_usd AS projected_cost_basis_usd
          FROM venue_commands cmd
          JOIN venue_submission_envelopes envelope
            ON envelope.envelope_id = cmd.envelope_id
          LEFT JOIN position_current pc
            ON pc.position_id = cmd.position_id
         WHERE cmd.intent_kind = 'ENTRY'
           AND cmd.side = 'BUY'
           AND (
                cmd.state IN (
                    'SUBMITTING',
                    'POST_ACKED',
                    'ACKED',
                    'PARTIAL',
                    'CANCEL_PENDING',
                    'FILLED'
                )
                OR (
                    cmd.state = 'REVIEW_REQUIRED'
                    AND EXISTS (
                        SELECT 1
                          FROM venue_command_events review
                         WHERE review.command_id = cmd.command_id
                           AND review.event_type = 'REVIEW_REQUIRED'
                           AND review.sequence_no = (
                                SELECT MAX(latest.sequence_no)
                                  FROM venue_command_events latest
                                 WHERE latest.command_id = cmd.command_id
                                   AND latest.event_type = 'REVIEW_REQUIRED'
                           )
                           AND json_extract(review.payload_json, '$.reason') =
                               'partial_remainder_point_order_filled_without_full_trade_fact'
                    )
                )
           )
           AND COALESCE(cmd.venue_order_id, '') != ''
           AND (
                pc.position_id IS NULL
                OR pc.phase IN (
                    'pending_entry', 'active', 'day0_window', 'pending_exit'
                )
           )
           AND EXISTS (
                SELECT 1
                  FROM canonical_trade_fact fact
                 WHERE fact.command_id = cmd.command_id
                   AND fact.venue_order_id = cmd.venue_order_id
                   AND fact.state IN ('MATCHED', 'MINED', 'CONFIRMED')
                   AND fact.source IN ('REST', 'WS_USER')
                   AND CAST(COALESCE(fact.filled_size, '0') AS REAL) > 0
                   AND CAST(COALESCE(fact.fill_price, '0') AS REAL) > 0
           )
           AND (
                cmd.state != 'FILLED'
                OR (
                    lower(COALESCE(pc.order_id, '')) != lower(cmd.venue_order_id)
                    AND EXISTS (
                        SELECT 1
                          FROM execution_fact prior_execution
                          JOIN venue_commands prior_command
                            ON prior_command.command_id = prior_execution.command_id
                         WHERE prior_execution.position_id = cmd.position_id
                           AND prior_execution.command_id != cmd.command_id
                           AND prior_execution.order_role = 'entry'
                           AND prior_execution.voided_at IS NULL
                           AND prior_execution.filled_at IS NOT NULL
                           AND prior_execution.shares > 0
                           AND prior_command.token_id = cmd.token_id
                    )
                    AND (
                        NOT EXISTS (
                            SELECT 1
                              FROM position_events event
                             WHERE event.position_id = cmd.position_id
                               AND event.event_type = 'ENTRY_ORDER_FILLED'
                               AND (
                                    event.command_id = cmd.command_id
                                    OR lower(COALESCE(event.order_id, '')) =
                                       lower(cmd.venue_order_id)
                               )
                        )
                        OR NOT EXISTS (
                            SELECT 1
                              FROM execution_fact execution
                             WHERE execution.position_id = cmd.position_id
                               AND execution.command_id = cmd.command_id
                               AND execution.order_role = 'entry'
                               AND execution.filled_at IS NOT NULL
                               AND execution.shares > 0
                        )
                    )
                )
           )
        """
        + command_clause
        + " ORDER BY datetime(cmd.updated_at), cmd.command_id",
        tuple(params),
    ).fetchall()
    return [_dict_row(row) for row in rows]


def _authenticated_entry_trade_fact_command_ids(
    conn: sqlite3.Connection,
    *,
    states: tuple[str, ...],
) -> tuple[str, ...]:
    """Return exact current commands that can have authenticated fill debt."""

    if not states or not all(
        _table_exists(conn, table)
        for table in ("venue_commands", "venue_trade_facts")
    ):
        return ()
    placeholders = ",".join("?" for _ in states)
    rows = conn.execute(
        f"""
        SELECT DISTINCT cmd.command_id
          FROM venue_commands AS cmd
               INDEXED BY idx_venue_commands_state
          JOIN venue_trade_facts AS fact
               INDEXED BY idx_trade_facts_command
            ON fact.command_id = cmd.command_id
           AND fact.venue_order_id = cmd.venue_order_id
         WHERE cmd.state IN ({placeholders})
           AND cmd.intent_kind = 'ENTRY'
           AND cmd.side = 'BUY'
           AND COALESCE(cmd.venue_order_id, '') != ''
           AND fact.state IN ('MATCHED', 'MINED', 'CONFIRMED')
           AND fact.source IN ('REST', 'WS_USER')
           AND CAST(COALESCE(fact.filled_size, '0') AS REAL) > 0
           AND CAST(COALESCE(fact.fill_price, '0') AS REAL) > 0
         ORDER BY cmd.command_id
        """,
        states,
    ).fetchall()
    return tuple(
        command_id
        for row in rows
        if (command_id := str(row[0] or "").strip())
    )


def _bounded_authenticated_entry_trade_fact_candidates(
    conn: sqlite3.Connection,
    *,
    states: tuple[str, ...],
) -> list[dict]:
    """Validate only indexed current command identities against the full law."""

    candidates: list[dict] = []
    for command_id in _authenticated_entry_trade_fact_command_ids(
        conn,
        states=states,
    ):
        candidates.extend(
            _authenticated_entry_trade_fact_candidates(
                conn,
                command_id=command_id,
            )
        )
    return candidates


def _confirmed_entry_trade_fact_summary(
    conn: sqlite3.Connection,
    *,
    command_id: str,
    venue_order_id: str,
) -> dict:
    rows = conn.execute(
        "WITH "
        + _canonical_trade_fact_cte()
        + ", "
        + _economic_trade_fact_cte()
        + """
        SELECT fact.trade_fact_id,
               fact.trade_id,
               fact.state,
               fact.filled_size,
               fact.fill_price,
               fact.raw_payload_json,
               fact.source,
               fact.observed_at,
               fact.venue_timestamp,
               cmd.token_id,
               envelope.yes_token_id,
               envelope.no_token_id,
               envelope.selected_outcome_token_id
          FROM economic_trade_fact fact
          JOIN venue_commands cmd
            ON cmd.command_id = fact.command_id
          JOIN venue_submission_envelopes envelope
            ON envelope.envelope_id = cmd.envelope_id
         WHERE fact.command_id = ?
           AND fact.venue_order_id = ?
           AND fact.state IN ('MATCHED', 'MINED', 'CONFIRMED')
           AND fact.source IN ('REST', 'WS_USER')
         ORDER BY fact.trade_id
        """,
        (command_id, venue_order_id),
    ).fetchall()
    filled = Decimal("0")
    cost = Decimal("0")
    latest_at = ""
    sources: set[str] = set()
    trade_ids: list[str] = []
    fact_ids: list[int] = []
    states: list[str] = []
    from src.execution.exchange_reconcile import (
        _json_mapping,
        _taker_buy_trade_economics,
        _trade_payload_for_maker_economics,
    )

    for raw in rows:
        fact = _dict_row(raw)
        exact_taker = _taker_buy_trade_economics(
            _trade_payload_for_maker_economics(
                _json_mapping(fact.get("raw_payload_json"))
            ),
            venue_order_id=venue_order_id,
            selected_token_id=str(
                fact.get("selected_outcome_token_id")
                or fact.get("token_id")
                or ""
            ),
            yes_token_id=str(fact.get("yes_token_id") or ""),
            no_token_id=str(fact.get("no_token_id") or ""),
        )
        if exact_taker is None:
            size = _positive_decimal_or_none(fact.get("filled_size"))
            price = _positive_decimal_or_none(fact.get("fill_price"))
            exact_cost = size * price if size is not None and price is not None else None
        else:
            size, exact_cost = exact_taker
            price = exact_cost / size
        trade_id = str(fact.get("trade_id") or "").strip()
        if size is None or price is None or exact_cost is None or not trade_id:
            continue
        filled += size
        cost += exact_cost
        trade_ids.append(trade_id)
        fact_ids.append(int(fact["trade_fact_id"]))
        states.append(str(fact.get("state") or "").upper())
        sources.add(str(fact.get("source") or "").upper())
        source_at = str(
            fact.get("venue_timestamp") or fact.get("observed_at") or ""
        )
        if _parse_ts(source_at) is not None and source_at > latest_at:
            latest_at = source_at
    return {
        "count": len(trade_ids),
        "filled_size": _decimal_text(filled),
        "fill_price": _decimal_text(cost / filled) if filled > 0 else "",
        "observed_at": latest_at,
        "source": "REST" if "REST" in sources else "WS_USER",
        "trade_ids": trade_ids,
        "trade_fact_ids": fact_ids,
        "states": states,
    }


def _latest_order_fact_matched_size(
    conn: sqlite3.Connection,
    *,
    command_id: str,
    venue_order_id: str,
) -> Decimal:
    row = conn.execute(
        """
        SELECT MAX(CAST(COALESCE(matched_size, '0') AS REAL)) AS matched_size
          FROM venue_order_facts
         WHERE command_id = ?
           AND venue_order_id = ?
        """,
        (command_id, venue_order_id),
    ).fetchone()
    return _decimal_or_none(
        _dict_row(row).get("matched_size") if row else None
    ) or Decimal("0")


def _authenticated_entry_fill_projection_complete(
    conn: sqlite3.Connection,
    *,
    command_id: str,
    position_id: str,
    venue_order_id: str,
    filled_size: Decimal,
    fill_price: Decimal,
) -> bool:
    """Return whether one command's cumulative fill is canonical end to end."""

    event = conn.execute(
        """
        SELECT sequence_no
          FROM position_events
         WHERE position_id = ?
           AND event_type = 'ENTRY_ORDER_FILLED'
           AND (
                command_id = ?
                OR lower(COALESCE(order_id, '')) = lower(?)
           )
         LIMIT 1
        """,
        (position_id, command_id, venue_order_id),
    ).fetchone()
    if event is None:
        return False
    rows = conn.execute(
        """
        SELECT shares, fill_price
          FROM execution_fact
         WHERE position_id = ?
           AND command_id = ?
           AND order_role = 'entry'
           AND filled_at IS NOT NULL
           AND voided_at IS NULL
           AND shares > 0
           AND fill_price > 0
        """,
        (position_id, command_id),
    ).fetchall()
    tolerance = Decimal("0.000001")
    for row in rows:
        shares = _decimal_or_none(row["shares"]) or Decimal("0")
        price = _decimal_or_none(row["fill_price"]) or Decimal("0")
        if (
            abs(shares - filled_size) <= tolerance
            and abs(price - fill_price) <= tolerance
        ):
            break
    else:
        return False

    later_reduction = conn.execute(
        """
        SELECT 1
          FROM position_events
         WHERE position_id = ?
           AND sequence_no > ?
           AND (
                event_type = 'EXIT_ORDER_FILLED'
                OR (
                    json_valid(payload_json)
                    AND json_extract(payload_json, '$.semantic_event')
                        = 'CAPITAL_REDUCTION_FILLED'
                )
           )
         LIMIT 1
        """,
        (position_id, int(event["sequence_no"])),
    ).fetchone()
    if later_reduction is not None:
        return True

    current = conn.execute(
        """
        SELECT phase, shares, cost_basis_usd,
               chain_shares, chain_cost_basis_usd
          FROM position_current
         WHERE position_id = ?
         LIMIT 1
        """,
        (position_id,),
    ).fetchone()
    if current is None or str(current["phase"] or "") not in {
        "pending_entry",
        "active",
        "day0_window",
        "pending_exit",
    }:
        return False

    from src.state.db import query_entry_execution_fill_aggregate

    aggregate = query_entry_execution_fill_aggregate(
        conn,
        position_id,
        strict=True,
    )
    if aggregate is None:
        return False
    projected_shares = _decimal_or_none(current["shares"]) or Decimal("0")
    projected_cost = _decimal_or_none(current["cost_basis_usd"]) or Decimal("0")
    aggregate_shares = (
        _decimal_or_none(aggregate.get("shares_filled")) or Decimal("0")
    )
    aggregate_cost = (
        _decimal_or_none(aggregate.get("filled_cost_basis_usd")) or Decimal("0")
    )
    if (
        abs(projected_shares - aggregate_shares) <= _POSITION_PROJECTION_TOLERANCE
        and abs(projected_cost - aggregate_cost) <= _POSITION_PROJECTION_TOLERANCE
    ):
        return True

    chain_shares = _decimal_or_none(current["chain_shares"]) or Decimal("0")
    chain_cost = _decimal_or_none(current["chain_cost_basis_usd"]) or Decimal("0")
    return bool(
        projected_shares > aggregate_shares
        and projected_cost > aggregate_cost
        and chain_shares >= projected_shares - _POSITION_PROJECTION_TOLERANCE
        and chain_cost >= projected_cost - _POSITION_PROJECTION_TOLERANCE
    )


def _reconcile_authenticated_entry_trade_fact(
    conn: sqlite3.Connection,
    command: dict,
) -> str:
    """Atomically fold exact authenticated fill facts into command and position truth."""

    command_id = str(command.get("command_id") or "")
    venue_order_id = str(command.get("venue_order_id") or "")
    facts = _confirmed_entry_trade_fact_summary(
        conn,
        command_id=command_id,
        venue_order_id=venue_order_id,
    )
    filled = _positive_decimal_or_none(facts.get("filled_size"))
    fill_price = _positive_decimal_or_none(facts.get("fill_price"))
    command_size = _positive_decimal_or_none(command.get("size"))
    requested = _positive_decimal_or_none(command.get("submission_size"))
    command_price = _positive_decimal_or_none(command.get("price"))
    submitted_price = _positive_decimal_or_none(command.get("submission_price"))
    if not facts["count"] or any(
        value is None
        for value in (
            filled,
            fill_price,
            command_size,
            requested,
            command_price,
            submitted_price,
        )
    ):
        return "stayed"
    if command_size != requested or command_price != submitted_price:
        raise ValueError("authenticated entry command/envelope economics mismatch")
    if not _fill_price_respects_limit(
        fill_price,
        submitted_price,
        side=command.get("side"),
    ):
        raise ValueError("authenticated entry fill is worse than submitted limit")
    tolerance = Decimal("0.01")
    share_overfill = filled - requested > tolerance
    order_type = str(command.get("submission_order_type") or "").upper()
    order_type = order_type.removesuffix("_LIMIT")
    filled_notional = filled * fill_price
    submitted_notional = requested * submitted_price
    all_trade_facts_confirmed = bool(
        facts["count"]
        and all(state == "CONFIRMED" for state in facts.get("states", ()))
    )
    price_improved_taker_overfill = bool(
        share_overfill
        and str(command.get("side") or "").upper() == "BUY"
        and order_type in {"FAK", "FOK"}
        and filled_notional <= submitted_notional
    )
    if share_overfill and not price_improved_taker_overfill:
        raise ValueError(
            "authenticated entry fill exceeds submitted share/capital bound"
        )
    command_state = str(command.get("state") or "")
    already_filled = command_state == CommandState.FILLED.value
    partial_control_fold_complete = bool(
        command_state == CommandState.PARTIAL.value
        and _latest_order_fact_matched_size(
            conn,
            command_id=command_id,
            venue_order_id=venue_order_id,
        )
        >= filled - Decimal("0.000001")
    )
    # SCOPE: this exact PARTIAL ENTRY command and its authenticated cumulative
    # fill. DRAIN: the next command-recovery pass projects the same confirmed
    # trade facts without replaying the already-durable control fold. RESET:
    # the command-bound ENTRY_ORDER_FILLED event and execution_fact reproduce
    # the cumulative size and price; PARTIAL state/order facts alone cannot
    # claim owned wealth.
    if partial_control_fold_complete and _authenticated_entry_fill_projection_complete(
        conn,
        command_id=command_id,
        position_id=str(command.get("position_id") or ""),
        venue_order_id=venue_order_id,
        filled_size=filled,
        fill_price=fill_price,
    ):
        return "stayed"

    complete = _fill_size_completes_limit_order(
        filled,
        requested,
        side=command.get("side"),
    )
    if already_filled and not complete:
        raise ValueError(
            "terminal FILLED entry lacks complete authenticated fill economics"
        )
    cancel_pending = command_state == CommandState.CANCEL_PENDING.value
    terminal_fill_review = command_state == CommandState.REVIEW_REQUIRED.value
    if (cancel_pending or terminal_fill_review) and not complete:
        # SCOPE: this exact ENTRY command whose review boundary says the venue
        # order is terminal while confirmed trade facts still cover only a
        # prefix.  A partial prefix cannot clear that boundary or mint shares.
        # DRAIN: authenticated trade ingestion adds the missing command-bound
        # CONFIRMED legs, or the terminal-order recovery proves a true short
        # fill with its dedicated terminal-partial payload.
        # RESET: the next recovery pass recomputes the cumulative facts; only a
        # complete fill or typed terminal-partial proof advances the command.
        return "stayed"
    event_type = (
        CommandEventType.FILL_CONFIRMED.value
        if complete
        else CommandEventType.PARTIAL_FILL_OBSERVED.value
    )
    remaining = max(Decimal("0"), requested - filled)
    observed_at = str(facts.get("observed_at") or _now_iso())
    source = str(facts.get("source") or "REST")
    payload = {
        "schema_version": 1,
        "reason": "authenticated_entry_trade_fact_committed",
        "proof_class": "canonical_confirmed_trade_facts_exact_order",
        "command_id": command_id,
        "decision_id": str(command.get("decision_id") or ""),
        "venue_order_id": venue_order_id,
        "trade_ids": list(facts["trade_ids"]),
        "trade_fact_ids": list(facts["trade_fact_ids"]),
        "filled_size": _decimal_text(filled),
        "fill_price": _decimal_text(fill_price),
        "requested_size": _decimal_text(requested),
        "filled_notional": _decimal_text(filled_notional),
        "submitted_notional": _decimal_text(submitted_notional),
        "fill_bound_semantics": (
            "PRICE_IMPROVED_TAKER_NOTIONAL_BOUNDED"
            if price_improved_taker_overfill
            else "SHARE_AND_NOTIONAL_BOUNDED"
        ),
        "remaining_size": _decimal_text(remaining),
        "source": source,
        "required_predicates": {
            "command_state_accepts_fill": True,
            "entry_buy_identity": True,
            "bound_venue_order_id_matches_trade": True,
            "authenticated_trade_facts": True,
            "authenticated_confirmed_trade_facts": all_trade_facts_confirmed,
            "fill_price_respects_submitted_limit": True,
            "cumulative_fill_within_submitted_capital_bound": True,
            "price_improved_taker_share_overfill": price_improved_taker_overfill,
        },
        "source_proof": {
            "source_function": (
                "command_recovery.reconcile_authenticated_entry_trade_facts"
            ),
            "source_reason": "durable_trade_fact_normal_path",
            "source_commit": "runtime",
        },
    }
    projection_command = command
    snapshot_market_identity: dict[str, object] | None = None
    terminal_fill_decision_log_id: int | None = None
    if terminal_fill_review:
        _, terminal_fill_decision_log_id = _decision_log_trade_case_for_command(
            conn,
            command,
        )
    if not str(command.get("projected_phase") or "").strip():
        projection_command, snapshot_market_identity = (
            _immutable_snapshot_identity_for_missing_entry_projection(conn, command)
        )
    from src.execution.exchange_reconcile import (
        EntryIdentityProjectionBlocked,
        _ensure_entry_fill_position_event,
        _record_entry_identity_finding,
    )

    safe_command_id = "".join(ch if ch.isalnum() else "_" for ch in command_id)
    sp_name = f"sp_authenticated_entry_fill_{safe_command_id}"
    conn.execute(f"SAVEPOINT {sp_name}")
    try:
        if command_state == CommandState.SUBMITTING.value:
            append_event(
                conn,
                command_id=command_id,
                event_type=CommandEventType.SUBMIT_ACKED.value,
                occurred_at=observed_at,
                payload={
                    "schema_version": 1,
                    "reason": "authenticated_entry_trade_fact_implies_submit_ack",
                    "proof_class": "canonical_confirmed_trade_facts_exact_order",
                    "command_id": command_id,
                    "venue_order_id": venue_order_id,
                    "trade_ids": list(facts["trade_ids"]),
                    "source": source,
                    "required_predicates": {
                        "bound_venue_order_id_matches_trade": True,
                        "authenticated_confirmed_trade_facts": True,
                        "positive_fill_economics": True,
                    },
                },
            )
        if cancel_pending:
            append_event(
                conn,
                command_id=command_id,
                event_type=CommandEventType.REVIEW_REQUIRED.value,
                occurred_at=observed_at,
                payload={
                    **payload,
                    "reason": "cancel_pending_authenticated_full_fill",
                    "prior_state": CommandState.CANCEL_PENDING.value,
                },
            )
        fill_event_payload = payload
        if cancel_pending or terminal_fill_review:
            terminal_proof_class = (
                "authenticated_trade_fact_full_fill"
                if all_trade_facts_confirmed
                else "authenticated_trade_fact_terminal_fill"
            )
            terminal_auth_predicate = (
                "authenticated_confirmed_trade_facts"
                if all_trade_facts_confirmed
                else "authenticated_trade_facts"
            )
            fill_event_payload = {
                **payload,
                "reason": "review_cleared_confirmed_fill",
                "proof_class": terminal_proof_class,
                "trade_id": str(facts["trade_ids"][-1]),
                "cleared_at": observed_at,
                "required_predicates": {
                    **payload["required_predicates"],
                    "command_state_review_required": True,
                    "latest_event_is_review_boundary": True,
                    "trade_facts_cover_command_or_leave_only_dust": True,
                    "source_fill_time_valid": True,
                    terminal_auth_predicate: True,
                },
            }
        if not already_filled and not partial_control_fold_complete:
            append_order_fact(
                conn,
                venue_order_id=venue_order_id,
                command_id=command_id,
                state="MATCHED" if complete else "PARTIALLY_MATCHED",
                remaining_size=_decimal_text(remaining),
                matched_size=_decimal_text(filled),
                source=source,
                observed_at=observed_at,
                venue_timestamp=observed_at,
                raw_payload_hash=_payload_hash(payload),
                raw_payload_json=payload,
            )
            append_event(
                conn,
                command_id=command_id,
                event_type=event_type,
                occurred_at=observed_at,
                payload=fill_event_payload,
            )
        _ensure_entry_fill_position_event(
            conn,
            command=projection_command,
            venue_order_id=venue_order_id,
            filled_size=_decimal_text(filled),
            fill_price=_decimal_text(fill_price),
            observed_at=_coerce_iso_datetime(observed_at),
            command_event=event_type,
            order_fact_source=source,
            authoritative_market_metadata=snapshot_market_identity,
            defer_identity_finding_until_rollback=True,
            decision_log_id=terminal_fill_decision_log_id,
        )
        expected_state = (
            CommandState.FILLED.value if complete else CommandState.PARTIAL.value
        )
        command_row = conn.execute(
            "SELECT state FROM venue_commands WHERE command_id = ?",
            (command_id,),
        ).fetchone()
        projection_event = conn.execute(
            """
            SELECT 1
              FROM position_events
             WHERE position_id = ?
               AND event_type = 'ENTRY_ORDER_FILLED'
               AND lower(COALESCE(order_id, '')) = lower(?)
             LIMIT 1
            """,
            (str(command.get("position_id") or ""), venue_order_id),
        ).fetchone()
        execution_fact = conn.execute(
            """
            SELECT 1
              FROM execution_fact
             WHERE position_id = ?
               AND command_id = ?
               AND order_role = 'entry'
               AND filled_at IS NOT NULL
               AND shares > 0
             LIMIT 1
            """,
            (str(command.get("position_id") or ""), command_id),
        ).fetchone()
        if (
            command_row is None
            or str(command_row["state"] or "") != expected_state
            or projection_event is None
            or execution_fact is None
        ):
            raise RuntimeError(
                "authenticated entry fill did not atomically project command and "
                f"position: command_state={str(command_row['state'] or '') if command_row else '<missing>'} "
                f"expected_state={expected_state} position_event={projection_event is not None} "
                f"execution_fact={execution_fact is not None}"
            )
        conn.execute(f"RELEASE SAVEPOINT {sp_name}")
    except EntryIdentityProjectionBlocked as exc:
        conn.execute(f"ROLLBACK TO SAVEPOINT {sp_name}")
        conn.execute(f"RELEASE SAVEPOINT {sp_name}")
        _record_entry_identity_finding(
            conn,
            command=exc.command,
            context=exc.context,
            observed_at=exc.observed_at,
            reason=exc.reason,
            error=exc.error,
        )
        raise
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {sp_name}")
        conn.execute(f"RELEASE SAVEPOINT {sp_name}")
        raise
    logger.warning(
        "recovery: command %s %s authenticated trade facts -> %s "
        "(venue_order_id=%s filled_size=%s fill_price=%s)",
        command_id,
        command.get("state"),
        "FILLED" if complete else "PARTIAL",
        venue_order_id,
        _decimal_text(filled),
        _decimal_text(fill_price),
    )
    return "advanced"


def reconcile_authenticated_entry_trade_facts(
    conn: sqlite3.Connection,
    *,
    command_id: str | None = None,
) -> dict:
    """Project authenticated entry fills without waiting for venue polling."""

    summary = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
    for command in _authenticated_entry_trade_fact_candidates(
        conn,
        command_id=command_id,
    ):
        summary["scanned"] += 1
        try:
            outcome = _reconcile_authenticated_entry_trade_fact(conn, command)
        except Exception:
            logger.exception(
                "recovery: authenticated entry fill repair failed for command %s",
                command.get("command_id"),
            )
            summary["errors"] += 1
            continue
        summary[outcome] += 1
    return summary


def reconcile_review_required_matched_submit_trade_facts(
    conn: sqlite3.Connection,
) -> dict:
    """Recover durable matched-submit fills before any venue snapshot."""

    summary = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
    if not _table_exists(conn, "venue_commands"):
        return summary
    for row in find_unresolved_commands(conn):
        if str(row.get("state") or "") != CommandState.REVIEW_REQUIRED.value:
            continue
        try:
            cmd = VenueCommand.from_row(row)
        except Exception:
            summary["errors"] += 1
            continue
        latest_reason = _latest_review_required_payload(
            _command_events(conn, cmd.command_id)
        ).get("reason")
        if latest_reason != "matched_submit_missing_trade_id":
            continue
        summary["scanned"] += 1
        try:
            outcome = _review_required_matched_submit_trade_fact_recovery(
                conn, cmd
            )
        except Exception:
            logger.exception(
                "recovery: durable matched-submit fact repair failed for command %s",
                cmd.command_id,
            )
            summary["errors"] += 1
            continue
        summary[outcome] += 1
    return summary


def clear_review_required_confirmed_fill(
    conn: sqlite3.Connection,
    command_id: str,
    *,
    source_commit: str,
    source_function: str = "PolymarketUserChannelIngestor._handle_trade",
    reviewed_by: str = "operator",
    occurred_at: str | None = None,
) -> dict:
    """Restore FILLED only when REVIEW_REQUIRED followed an already confirmed fill."""

    command = _review_required_command(conn, command_id)
    events = _command_events(conn, command_id)
    latest_reason = _latest_review_required_payload(events).get("reason")
    if latest_reason != "ws_trade_lifecycle_regression_or_economic_drift":
        raise ValueError("confirmed-fill review clearance only supports WS lifecycle/economic drift reviews")
    fill_payload = None
    for event in reversed(events):
        if event.get("event_type") == CommandEventType.FILL_CONFIRMED.value:
            fill_payload = _json_dict(event.get("payload_json"))
            break
    if fill_payload is None:
        raise ValueError("confirmed-fill review clearance requires a prior FILL_CONFIRMED event")
    trade_id = str(fill_payload.get("trade_id") or "")
    venue_order_id = str(fill_payload.get("venue_order_id") or command.get("venue_order_id") or "")
    row = conn.execute(
        "WITH " + _canonical_trade_fact_cte() + """
        SELECT *
        FROM canonical_trade_fact
        WHERE command_id = ?
          AND trade_id = ?
          AND venue_order_id = ?
          AND state IN ('MATCHED', 'MINED', 'CONFIRMED')
          AND CAST(COALESCE(filled_size, '0') AS REAL) > 0
        """,
        (command_id, trade_id, venue_order_id),
    ).fetchone()
    if row is None:
        raise ValueError("confirmed-fill review clearance requires a matching positive venue_trade_facts row")
    trade_fact = _dict_row(row)
    if not str(source_commit or "").strip():
        raise ValueError("source_commit is required")
    now = occurred_at or _now_iso()
    payload = {
        "schema_version": 1,
        "reason": "review_cleared_confirmed_fill",
        "command_id": command_id,
        "decision_id": str(command.get("decision_id") or ""),
        "venue_order_id": venue_order_id,
        "trade_id": trade_id,
        "filled_size": str(trade_fact.get("filled_size") or ""),
        "fill_price": str(trade_fact.get("fill_price") or ""),
        "proof_class": "prior_fill_confirmed_event_with_positive_trade_fact",
        "required_predicates": {
            "latest_event_is_review_required": bool(events and events[-1].get("event_type") == CommandEventType.REVIEW_REQUIRED.value),
            "review_reason_supported": latest_reason == "ws_trade_lifecycle_regression_or_economic_drift",
            "prior_fill_confirmed_event": True,
            "positive_trade_fact": True,
        },
        "prior_fill_confirmed_event": fill_payload,
        "trade_fact_proof": {
            "trade_fact_id": trade_fact.get("trade_fact_id"),
            "state": trade_fact.get("state"),
            "source": trade_fact.get("source"),
            "observed_at": trade_fact.get("observed_at"),
        },
        "review_required_proof": {
            "reason": latest_reason,
        },
        "source_proof": {
            "source_commit": source_commit,
            "source_function": source_function,
            "source_reason": "ws_trade_lifecycle_regression_or_economic_drift",
        },
        "reviewed_by": reviewed_by,
        "cleared_at": now,
    }
    append_event(
        conn,
        command_id=command_id,
        event_type=CommandEventType.FILL_CONFIRMED.value,
        occurred_at=now,
        payload=payload,
    )
    return payload


def _review_required_no_venue_exposure_recovery(
    conn: sqlite3.Connection,
    cmd: VenueCommand,
    client,
) -> str:
    events = _command_events(conn, cmd.command_id)
    latest_reason = _latest_review_required_payload(events).get("reason")
    if latest_reason not in _NO_VENUE_EXPOSURE_REVIEW_REASONS:
        return "stayed"
    try:
        now = _now_iso()
        proof = build_review_required_no_venue_exposure_proof(
            conn,
            cmd.command_id,
            client,
            observed_at=now,
        )
        clear_review_required_no_venue_exposure(
            conn,
            cmd.command_id,
            venue_absence_proof=proof,
            source_commit="runtime",
            source_function="command_recovery._reconcile_row",
            reviewed_by="command_recovery",
            occurred_at=now,
        )
    except ValueError as exc:
        logger.info(
            "recovery: command %s REVIEW_REQUIRED no-venue-exposure stayed: %s",
            cmd.command_id,
            exc,
        )
        return "stayed"
    except Exception as exc:  # noqa: BLE001 - recovery loops count errors and continue.
        logger.warning(
            "recovery: command %s REVIEW_REQUIRED no-venue-exposure proof failed: %s",
            cmd.command_id,
            exc,
        )
        return "error"
    logger.info(
        "recovery: command %s REVIEW_REQUIRED recovery_no_venue_order_id -> EXPIRED",
        cmd.command_id,
    )
    return "advanced"


def _review_required_trade_maker_match(command: dict, trade: dict) -> dict | None:
    token_id = str(command.get("token_id") or "")
    side = str(command.get("side") or "").upper()
    command_price = command.get("price")
    command_size = _decimal_or_none(command.get("size"))
    bound_order_id = str(command.get("venue_order_id") or "").strip().lower()
    if not token_id or command_size is None:
        return None
    top_order_id = str(
        trade.get("taker_order_id")
        or trade.get("order_id")
        or trade.get("id")
        or ""
    ).strip()
    top_level_owned = (
        str(trade.get("trader_side") or "").upper() == "TAKER"
        or (
            bool(bound_order_id)
            and top_order_id.lower() == bound_order_id
        )
    )
    if top_level_owned and str(
        trade.get("asset_id") or trade.get("token_id") or ""
    ) == token_id:
        if side and str(trade.get("side") or "").upper() == side:
            if _fill_price_respects_limit(
                trade.get("price"),
                command_price,
                side=side,
            ):
                matched = _positive_decimal_or_none(trade.get("size") or trade.get("matched_amount"))
                if _fill_size_completes_limit_order(
                    matched,
                    command_size,
                    side=side,
                ):
                    order_id = top_order_id
                    if order_id:
                        return {
                            "order_id": order_id,
                            "matched_size": _decimal_text(matched),
                            "fill_price": str(trade.get("price") or command_price),
                            "maker_order": {
                                "asset_id": token_id,
                                "side": side,
                                "price": trade.get("price") or command_price,
                                "matched_amount": _decimal_text(matched),
                                "order_id": order_id,
                                "source": "top_level_taker_trade",
                            },
                        }
    for maker in trade.get("maker_orders") or []:
        if not isinstance(maker, dict):
            continue
        order_id = str(maker.get("order_id") or maker.get("id") or "").strip()
        if not bound_order_id or order_id.lower() != bound_order_id:
            continue
        if str(maker.get("asset_id") or maker.get("token_id") or "") != token_id:
            continue
        if side and str(maker.get("side") or "").upper() != side:
            continue
        if not _fill_price_respects_limit(
            maker.get("price"),
            command_price,
            side=side,
        ):
            continue
        matched = _positive_decimal_or_none(maker.get("matched_amount") or maker.get("size"))
        if not _fill_size_completes_limit_order(
            matched,
            command_size,
            side=side,
        ):
            continue
        if not order_id:
            continue
        return {
            "order_id": order_id,
            "matched_size": _decimal_text(matched),
            "fill_price": str(maker.get("price") or command_price),
            "maker_order": maker,
        }
    return None


def _review_required_confirmed_trade_match(
    command: dict,
    client,
) -> tuple[dict, dict, list[dict]] | None:
    try:
        open_orders = [_raw_payload(order) for order in list(client.get_open_orders() or [])]
        trades = _client_trade_payloads(client)
    except Exception:
        logger.debug("recovery: confirmed-trade review proof venue read failed", exc_info=True)
        raise
    open_order_ids = {
        str(order.get("id") or order.get("order_id") or order.get("orderID") or "")
        for order in open_orders
    }
    created_epoch = _epoch_seconds(command.get("created_at")) or 0.0
    matches: list[tuple[dict, dict]] = []
    for trade in trades:
        trade_epoch = _epoch_seconds(trade.get("match_time") or trade.get("last_update"))
        if trade_epoch is not None and trade_epoch < created_epoch:
            continue
        if str(trade.get("status") or trade.get("state") or "").upper() != "CONFIRMED":
            continue
        maker_match = _review_required_trade_maker_match(command, trade)
        if maker_match is None:
            continue
        if maker_match["order_id"] in open_order_ids:
            continue
        matches.append((trade, maker_match))
    if len(matches) != 1:
        return None
    trade, maker_match = matches[0]
    return trade, maker_match, open_orders


def _review_required_confirmed_trade_recovery(
    conn: sqlite3.Connection,
    cmd: VenueCommand,
    client,
) -> str:
    events = _command_events(conn, cmd.command_id)
    latest_reason = _latest_review_required_payload(events).get("reason")
    if latest_reason not in _CONFIRMED_TRADE_REVIEW_REASONS:
        return "stayed"
    command = _dict_row(
        conn.execute(
            "SELECT * FROM venue_commands WHERE command_id = ?",
            (cmd.command_id,),
        ).fetchone()
    )
    try:
        match = _review_required_confirmed_trade_match(command, client)
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "recovery: command %s REVIEW_REQUIRED confirmed-trade proof failed: %s",
            cmd.command_id,
            exc,
        )
        return "error"
    if match is None:
        return "stayed"
    trade, maker_match, open_orders = match
    now = _now_iso()
    venue_order_id = str(maker_match["order_id"])
    bound_venue_order_id = str(command.get("venue_order_id") or "").strip()
    if bound_venue_order_id and venue_order_id != bound_venue_order_id:
        return "stayed"
    trade_id = str(trade.get("id") or trade.get("trade_id") or "")
    filled_size = str(maker_match["matched_size"])
    fill_price = str(maker_match["fill_price"])
    tx_hash = str(trade.get("transaction_hash") or trade.get("tx_hash") or "") or None
    if not trade_id:
        return "stayed"
    payload = {
        "schema_version": 1,
        "reason": "review_cleared_confirmed_fill",
        "command_id": cmd.command_id,
        "decision_id": str(command.get("decision_id") or ""),
        "venue_order_id": venue_order_id,
        "trade_id": trade_id,
        "filled_size": filled_size,
        "fill_price": fill_price,
        "proof_class": (
            "post_ack_persistence_failure_confirmed_trade"
            if latest_reason in _POST_ACK_PERSISTENCE_REVIEW_REASONS
            else f"{latest_reason}_confirmed_trade"
        ),
        "side_effect_boundary_crossed": True,
        "sdk_submit_attempted": (
            True
            if latest_reason == "matched_submit_missing_trade_id"
            or latest_reason in _POST_ACK_PERSISTENCE_REVIEW_REASONS
            else "unknown"
        ),
        "required_predicates": {
            "latest_event_is_review_required": True,
            "review_reason_confirmed_trade_recoverable": True,
            "review_reason": latest_reason,
            "review_reason_recovery_no_venue_order_id": (
                latest_reason == "recovery_no_venue_order_id"
            ),
            "review_reason_matched_submit_missing_trade_id": (
                latest_reason == "matched_submit_missing_trade_id"
            ),
            "review_reason_post_ack_persistence_failure": (
                latest_reason in _POST_ACK_PERSISTENCE_REVIEW_REASONS
            ),
            "review_reason_order_not_found": (
                latest_reason == "recovery_order_not_found_at_venue"
            ),
            "positive_trade_fact": True,
            "maker_order_token_matches_command": True,
            "bound_venue_order_id_matches_trade": (
                not bound_venue_order_id or venue_order_id == bound_venue_order_id
            ),
            "maker_order_not_open": True,
            "venue_size_quantization_residual_lt_0_01": True,
        },
        "trade_fact_proof": {
            "source": "authenticated_clob_user_trades",
            "observed_at": now,
            "trade_status": str(trade.get("status") or trade.get("state") or ""),
            "trade": trade,
            "maker_order": maker_match["maker_order"],
            "open_order_ids_checked": [
                str(order.get("id") or order.get("order_id") or order.get("orderID") or "")
                for order in open_orders
            ],
        },
        "review_required_proof": {
            "reason": latest_reason,
        },
        "source_proof": {
            "source_commit": "runtime",
            "source_function": "command_recovery._reconcile_row",
            "source_reason": f"{latest_reason}_confirmed_trade",
        },
        "reviewed_by": "command_recovery",
        "cleared_at": now,
    }
    append_order_fact(
        conn,
        venue_order_id=venue_order_id,
        command_id=cmd.command_id,
        state="MATCHED",
        remaining_size="0",
        matched_size=filled_size,
        source="REST",
        observed_at=now,
        venue_timestamp=now,
        raw_payload_hash=_canonical_payload_hash({**payload, "fact_type": "order"}),
        raw_payload_json=payload,
    )
    append_trade_fact(
        conn,
        trade_id=trade_id,
        venue_order_id=venue_order_id,
        command_id=cmd.command_id,
        state="CONFIRMED",
        filled_size=filled_size,
        fill_price=fill_price,
        source="REST",
        observed_at=now,
        venue_timestamp=now,
        tx_hash=tx_hash,
        raw_payload_hash=_canonical_payload_hash({**payload, "fact_type": "trade"}),
        raw_payload_json=payload,
    )
    append_event(
        conn,
        command_id=cmd.command_id,
        event_type=CommandEventType.FILL_CONFIRMED.value,
        occurred_at=now,
        payload=payload,
    )
    _append_matched_order_fill_projection(
        conn,
        command={**command, "venue_order_id": venue_order_id},
        venue_order_id=venue_order_id,
        matched_size=filled_size,
        fill_price=fill_price,
        observed_at=now,
    )
    logger.info(
        "recovery: command %s REVIEW_REQUIRED %s -> FILLED "
        "(venue_order_id=%s trade_id=%s)",
        cmd.command_id,
        latest_reason,
        venue_order_id,
        trade_id,
    )
    return "advanced"


def clear_submit_unknown_geoblock_403(
    conn: sqlite3.Connection,
    command_id: str,
    *,
    reviewed_by: str = "operator",
    occurred_at: str | None = None,
) -> dict:
    """Terminalize a deterministic CLOB geoblock 403 as rejected.

    This is intentionally narrower than general unknown-side-effect recovery.
    It only handles synchronous Polymarket ``PolyApiException`` geoblock 403
    responses with no persisted venue identity, final envelope, order facts,
    trade facts, or position records. Timeouts, 5xx, connection failures, and
    ambiguous SDK exceptions remain unresolved.
    """

    command = _submit_unknown_command(conn, command_id)
    predicates, predicate_failures = _geoblock_403_predicates(conn, command)
    if predicate_failures:
        raise ValueError(
            "geoblock 403 terminalization predicates failed: "
            + ", ".join(sorted(predicate_failures))
        )
    now = occurred_at or _now_iso()
    payload = {
        "schema_version": 1,
        "reason": "venue_rejected_geoblock_403",
        "command_id": command_id,
        "decision_id": str(command.get("decision_id") or ""),
        "proof_class": "deterministic_venue_geoblock_403",
        "side_effect_boundary_crossed": True,
        "venue_order_created": False,
        "required_predicates": predicates,
        "idempotency_key": str(command.get("idempotency_key") or ""),
        "reviewed_by": reviewed_by,
        "cleared_at": now,
    }
    append_event(
        conn,
        command_id=command_id,
        event_type=CommandEventType.SUBMIT_REJECTED.value,
        occurred_at=now,
        payload=payload,
    )
    return payload


def _recover_no_venue_order_id_submit(
    conn: sqlite3.Connection,
    cmd: VenueCommand,
    client,
    *,
    now: str,
) -> str:
    """Resolve a post-HTTP submit row that has no venue order id.

    A deterministic synchronous venue rejection can fail to persist its terminal
    event if the trade DB is locked after the HTTP response. Treat that row like
    unknown-side-effect recovery: prove whether the idempotency key exists at
    the venue, adopt it if found, otherwise release after the safe replay window.
    """

    lookup_status, venue_resp, venue_absence_proof, lookup_method = (
        _lookup_unknown_side_effect_order(conn, cmd, client)
    )
    if lookup_status == "unavailable":
        logger.warning(
            "recovery: command %s SUBMITTING without venue_order_id stayed "
            "(lookup unavailable via %s)",
            cmd.command_id,
            lookup_method,
        )
        return "stayed"

    venue_order_id = _extract_order_id(venue_resp, cmd.venue_order_id)
    if venue_resp is not None:
        venue_status = _order_status(venue_resp)
        payload = {
            "venue_order_id": venue_order_id,
            "venue_status": venue_status,
            "venue_response": venue_resp,
            "idempotency_key": cmd.idempotency_key.value,
            "lookup_method": lookup_method,
        }
        if venue_status == "CONFIRMED":
            append_event(
                conn,
                command_id=cmd.command_id,
                event_type=CommandEventType.REVIEW_REQUIRED.value,
                occurred_at=now,
                payload={
                    **payload,
                    "reason": "recovery_confirmed_requires_trade_fact",
                    "semantic_guard": (
                        "order_status_confirmed_is_not_fill_economics_authority"
                    ),
                },
            )
            logger.warning(
                "recovery: command %s SUBMITTING/no-venue-id -> REVIEW_REQUIRED "
                "(venue status=%s order %s; explicit trade fact required)",
                cmd.command_id, venue_status, venue_order_id,
            )
            return "advanced"
        if venue_status in {"FILLED", "MATCHED", "MINED", "PARTIAL", "PARTIALLY_MATCHED", "PARTIALLY_FILLED"}:
            append_event(
                conn,
                command_id=cmd.command_id,
                event_type=CommandEventType.PARTIAL_FILL_OBSERVED.value,
                occurred_at=now,
                payload=payload,
            )
            logger.info(
                "recovery: command %s SUBMITTING/no-venue-id -> PARTIAL "
                "(venue status=%s order %s)",
                cmd.command_id, venue_status, venue_order_id,
            )
            return "advanced"
        if venue_status == "REJECTED":
            append_event(
                conn,
                command_id=cmd.command_id,
                event_type=CommandEventType.SUBMIT_REJECTED.value,
                occurred_at=now,
                payload={**payload, "reason": "recovery_venue_rejected_no_venue_order_id"},
            )
            logger.info(
                "recovery: command %s SUBMITTING/no-venue-id -> REJECTED (venue status=%s)",
                cmd.command_id, venue_status,
            )
            return "advanced"
        append_event(
            conn,
            command_id=cmd.command_id,
            event_type=CommandEventType.SUBMIT_ACKED.value,
            occurred_at=now,
            payload=payload,
        )
        logger.info(
            "recovery: command %s SUBMITTING/no-venue-id -> ACKED "
            "(venue status=%s order %s)",
            cmd.command_id, venue_status, venue_order_id,
        )
        return "advanced"

    age = _age_seconds(cmd, now=datetime.now(timezone.utc))
    if age is None or age < _SAFE_REPLAY_MIN_AGE_SECONDS:
        logger.info(
            "recovery: command %s SUBMITTING/no-venue-id not found but age=%s; "
            "staying until safe replay window elapses",
            cmd.command_id, age,
        )
        return "stayed"
    append_event(
        conn,
        command_id=cmd.command_id,
        event_type=CommandEventType.SUBMIT_REJECTED.value,
        occurred_at=now,
        payload={
            "reason": "safe_replay_permitted_no_order_found",
            "safe_replay_permitted": True,
            "previous_unknown_command_id": cmd.command_id,
            "idempotency_key": cmd.idempotency_key.value,
            "age_seconds": age,
            "lookup_method": lookup_method,
            "venue_absence_proof": venue_absence_proof,
            "recovered_from_state": "SUBMITTING",
        },
    )
    logger.warning(
        "recovery: command %s SUBMITTING/no-venue-id -> SUBMIT_REJECTED "
        "(safe replay permitted; idempotency key not found after %.1fs)",
        cmd.command_id, age,
    )
    return "advanced"


def _reconcile_row(
    conn: sqlite3.Connection,
    cmd: VenueCommand,
    client,
) -> str:
    """Apply one resolution-table row.  Returns 'advanced', 'stayed', or 'error'.

    Raises nothing — all exceptions are caught and logged; the loop counts them.
    """
    try:
        state = cmd.state

        if state == CommandState.REVIEW_REQUIRED:
            outcome = _review_required_typed_pre_sdk_rejection_recovery(conn, cmd)
            if outcome != "stayed":
                return outcome
            outcome = _review_required_bound_entry_order_recovery(conn, cmd, client)
            if outcome != "stayed":
                return outcome
            outcome = _review_required_bound_fak_exit_recovery(conn, cmd, client)
            if outcome != "stayed":
                return outcome
            outcome = _review_required_cancel_failed_already_canceled_fill_recovery(
                conn,
                cmd,
                client,
            )
            if outcome != "stayed":
                return outcome
            outcome = _review_required_cancel_failed_already_canceled_no_fill_recovery(
                conn,
                cmd,
                client,
            )
            if outcome != "stayed":
                return outcome
            outcome = _review_required_post_ack_terminal_no_fill_recovery(conn, cmd, client)
            if outcome != "stayed":
                return outcome
            outcome = _review_required_cancel_unknown_live_order_recovery(conn, cmd, client)
            if outcome != "stayed":
                return outcome
            outcome = _review_required_confirmed_trade_recovery(conn, cmd, client)
            if outcome != "stayed":
                return outcome
            outcome = _review_required_no_venue_live_order_recovery(conn, cmd, client)
            if outcome != "stayed":
                return outcome
            return _review_required_no_venue_exposure_recovery(conn, cmd, client)

        now = _now_iso()

        # ------------------------------------------------------------------ #
        # SUBMITTING without venue_order_id: no ACK was persisted. This may be #
        # an ack-lost live order or a deterministic venue reject whose terminal#
        # SUBMIT_REJECTED write hit a transient DB lock. Use the same          #
        # idempotency/absence proof path as unknown-side-effect recovery.      #
        # ------------------------------------------------------------------ #
        if state == CommandState.SUBMITTING and not cmd.venue_order_id:
            return _recover_no_venue_order_id_submit(conn, cmd, client, now=now)

        # ------------------------------------------------------------------ #
        # M2: SUBMIT_UNKNOWN_SIDE_EFFECT                                      #
        # ------------------------------------------------------------------ #
        if state == CommandState.SUBMIT_UNKNOWN_SIDE_EFFECT:
            command = _dict_row(
                conn.execute(
                    "SELECT * FROM venue_commands WHERE command_id = ?",
                    (cmd.command_id,),
                ).fetchone()
            )
            geoblock_payload = _terminalize_submit_unknown_geoblock_403_if_proven(
                conn,
                command,
                occurred_at=now,
            )
            if geoblock_payload is not None:
                logger.info(
                    "recovery: command %s SUBMIT_UNKNOWN_SIDE_EFFECT -> "
                    "SUBMIT_REJECTED (deterministic geoblock 403)",
                    cmd.command_id,
                )
                return "advanced"
            fok_killed_payload = _terminalize_submit_unknown_fok_killed_400_if_proven(
                conn,
                command,
                occurred_at=now,
            )
            if fok_killed_payload is not None:
                logger.info(
                    "recovery: command %s SUBMIT_UNKNOWN_SIDE_EFFECT -> "
                    "SUBMIT_REJECTED (deterministic FOK killed 400)",
                    cmd.command_id,
                )
                return "advanced"
            fak_no_match_payload = _terminalize_submit_unknown_fak_no_match_400_if_proven(
                conn,
                command,
                occurred_at=now,
            )
            if fak_no_match_payload is not None:
                logger.info(
                    "recovery: command %s SUBMIT_UNKNOWN_SIDE_EFFECT -> "
                    "SUBMIT_REJECTED (deterministic FAK no-match 400)",
                    cmd.command_id,
                )
                return "advanced"
            invalid_amount_payload = _terminalize_submit_unknown_invalid_amount_400_if_proven(
                conn,
                command,
                occurred_at=now,
            )
            if invalid_amount_payload is not None:
                logger.info(
                    "recovery: command %s SUBMIT_UNKNOWN_SIDE_EFFECT -> "
                    "SUBMIT_REJECTED (deterministic invalid amount 400)",
                    cmd.command_id,
                )
                return "advanced"

            lookup_status, venue_resp, venue_absence_proof, lookup_method = (
                _lookup_unknown_side_effect_order(conn, cmd, client)
            )
            if lookup_status == "unavailable":
                logger.warning(
                    "recovery: command %s SUBMIT_UNKNOWN_SIDE_EFFECT cannot be resolved; "
                    "client lacks a complete venue lookup surface or venue reads found "
                    "ambiguous matching exposure",
                    cmd.command_id,
                )
                return "error"

            venue_order_id = _extract_order_id(venue_resp, cmd.venue_order_id)
            if venue_resp is not None:
                venue_status = _order_status(venue_resp)
                payload = {
                    "venue_order_id": venue_order_id,
                    "venue_status": venue_status,
                    "venue_response": venue_resp,
                    "idempotency_key": cmd.idempotency_key.value,
                }
                if venue_status == "CONFIRMED":
                    append_event(
                        conn,
                        command_id=cmd.command_id,
                        event_type=CommandEventType.REVIEW_REQUIRED.value,
                        occurred_at=now,
                        payload={
                            **payload,
                            "reason": "recovery_confirmed_requires_trade_fact",
                            "semantic_guard": (
                                "order_status_confirmed_is_not_fill_economics_authority"
                            ),
                        },
                    )
                    logger.warning(
                        "recovery: command %s SUBMIT_UNKNOWN_SIDE_EFFECT -> REVIEW_REQUIRED "
                        "(venue status=%s order %s; explicit trade fact required)",
                        cmd.command_id, venue_status, venue_order_id,
                    )
                    return "advanced"
                if venue_status in {"FILLED", "MATCHED", "MINED", "PARTIAL", "PARTIALLY_MATCHED", "PARTIALLY_FILLED"}:
                    append_event(
                        conn,
                        command_id=cmd.command_id,
                        event_type=CommandEventType.PARTIAL_FILL_OBSERVED.value,
                        occurred_at=now,
                        payload=payload,
                    )
                    logger.info(
                        "recovery: command %s SUBMIT_UNKNOWN_SIDE_EFFECT -> PARTIAL "
                        "(venue status=%s order %s)",
                        cmd.command_id, venue_status, venue_order_id,
                    )
                    return "advanced"
                if venue_status == "REJECTED":
                    append_event(
                        conn,
                        command_id=cmd.command_id,
                        event_type=CommandEventType.SUBMIT_REJECTED.value,
                        occurred_at=now,
                        payload={**payload, "reason": "recovery_venue_rejected"},
                    )
                    logger.info(
                        "recovery: command %s SUBMIT_UNKNOWN_SIDE_EFFECT -> SUBMIT_REJECTED "
                        "(venue status=%s)",
                        cmd.command_id, venue_status,
                    )
                    return "advanced"
                append_event(
                    conn,
                    command_id=cmd.command_id,
                    event_type=CommandEventType.SUBMIT_ACKED.value,
                    occurred_at=now,
                    payload=payload,
                )
                logger.info(
                    "recovery: command %s SUBMIT_UNKNOWN_SIDE_EFFECT -> ACKED "
                    "(venue status=%s order %s)",
                    cmd.command_id, venue_status, venue_order_id,
                )
                return "advanced"

            age = _age_seconds(cmd, now=datetime.now(timezone.utc))
            if age is None or age < _SAFE_REPLAY_MIN_AGE_SECONDS:
                logger.info(
                    "recovery: command %s SUBMIT_UNKNOWN_SIDE_EFFECT not found but age=%s; "
                    "staying until safe replay window elapses",
                    cmd.command_id, age,
                )
                return "stayed"
            safe_command_id = "".join(ch if ch.isalnum() else "_" for ch in cmd.command_id)
            sp_name = f"sp_submit_unknown_absence_{safe_command_id}"
            conn.execute(f"SAVEPOINT {sp_name}")
            try:
                resolved_findings = _resolve_m5_local_orphan_findings(
                    conn,
                    command_id=cmd.command_id,
                    venue_order_id=str(cmd.venue_order_id or ""),
                    resolved_at=now,
                    resolution="command_recovery_exact_submit_absence",
                )
                append_event(
                    conn,
                    command_id=cmd.command_id,
                    event_type=CommandEventType.SUBMIT_REJECTED.value,
                    occurred_at=now,
                    payload={
                        "reason": "safe_replay_permitted_no_order_found",
                        "safe_replay_permitted": True,
                        "previous_unknown_command_id": cmd.command_id,
                        "idempotency_key": cmd.idempotency_key.value,
                        "age_seconds": age,
                        "lookup_method": lookup_method,
                        "venue_absence_proof": venue_absence_proof,
                        "resolved_m5_local_orphan_findings": resolved_findings,
                    },
                )
                continuation = _release_submit_unknown_exit_after_authenticated_absence(
                    conn,
                    command=command,
                    observed_at=now,
                    absence_proof=venue_absence_proof or {},
                )
                if continuation is not None and not _emit_terminal_no_fill_redecision_from_recovery(
                    conn,
                    continuation=continuation,
                    occurred_at=now,
                ):
                    raise RuntimeError("authenticated-absence EXIT release did not emit redecision")
                conn.execute(f"RELEASE SAVEPOINT {sp_name}")
            except Exception:
                conn.execute(f"ROLLBACK TO SAVEPOINT {sp_name}")
                conn.execute(f"RELEASE SAVEPOINT {sp_name}")
                raise
            logger.warning(
                "recovery: command %s SUBMIT_UNKNOWN_SIDE_EFFECT -> SUBMIT_REJECTED "
                "(safe replay permitted; idempotency key not found after %.1fs)",
                cmd.command_id, age,
            )
            return "advanced"

        # ------------------------------------------------------------------ #
        # States that require a venue lookup (need venue_order_id).           #
        # SUBMITTING+id, UNKNOWN, CANCEL_PENDING all fall here.               #
        # ------------------------------------------------------------------ #
        venue_order_id = cmd.venue_order_id

        if not venue_order_id:
            # UNKNOWN without a venue_order_id: operator must intervene.
            if state == CommandState.UNKNOWN:
                append_event(
                    conn,
                    command_id=cmd.command_id,
                    event_type=CommandEventType.REVIEW_REQUIRED.value,
                    occurred_at=now,
                    payload={"reason": "recovery_unknown_no_venue_order_id"},
                )
                logger.warning(
                    "recovery: command %s UNKNOWN without venue_order_id -> REVIEW_REQUIRED",
                    cmd.command_id,
                )
                return "advanced"
            # CANCEL_PENDING without a venue_order_id: can't verify at venue.
            if state == CommandState.CANCEL_PENDING:
                logger.warning(
                    "recovery: command %s CANCEL_PENDING without venue_order_id; skipping",
                    cmd.command_id,
                )
                return "stayed"
            return "stayed"

        # Venue lookup — exceptions propagate to caller's per-row try/except.
        try:
            venue_resp = _venue_order_payload(client.get_order(venue_order_id))
        except Exception as exc:
            # Network / auth error: leave in current state, retry next cycle.
            logger.warning(
                "recovery: venue lookup for command %s (venue_order_id=%s) raised: %s; "
                "leaving in %s",
                cmd.command_id, venue_order_id, exc, state.value,
            )
            return "error"

        # ------------------------------------------------------------------ #
        # SUBMITTING + venue_order_id                                         #
        # ------------------------------------------------------------------ #
        if state == CommandState.SUBMITTING:
            if venue_resp is not None:
                # Inspect venue status — pre-fix code unconditionally emitted
                # SUBMIT_ACKED even when status="REJECTED" (HIGH-2).
                venue_status = _order_status(venue_resp)
                if venue_status == "REJECTED":
                    append_event(
                        conn,
                        command_id=cmd.command_id,
                        event_type=CommandEventType.SUBMIT_REJECTED.value,
                        occurred_at=now,
                        payload={"reason": "recovery_venue_rejected", "venue_order_id": venue_order_id, "venue_status": venue_status},
                    )
                    logger.info(
                        "recovery: command %s SUBMITTING -> REJECTED (venue status=%s)",
                        cmd.command_id, venue_status,
                    )
                    return "advanced"
                if venue_status in {"CANCELLED", "CANCELED", "EXPIRED"}:
                    no_fill_proven, no_fill_reason = _terminal_point_order_zero_fill_proven(
                        conn,
                        command_id=cmd.command_id,
                        point_order=venue_resp,
                    )
                    if not no_fill_proven:
                        append_event(
                            conn,
                            command_id=cmd.command_id,
                            event_type=CommandEventType.REVIEW_REQUIRED.value,
                            occurred_at=now,
                            payload={
                                "reason": no_fill_reason,
                                "venue_order_id": venue_order_id,
                                "venue_status": venue_status,
                                "venue_response": venue_resp,
                            },
                        )
                        logger.warning(
                            "recovery: command %s SUBMITTING terminal status=%s lacks zero-fill proof -> REVIEW_REQUIRED (%s)",
                            cmd.command_id,
                            venue_status,
                            no_fill_reason,
                        )
                        return "advanced"
                    append_event(
                        conn,
                        command_id=cmd.command_id,
                        event_type=CommandEventType.EXPIRED.value,
                        occurred_at=now,
                        payload={
                            "reason": "recovery_venue_terminal_no_fill",
                            "venue_order_id": venue_order_id,
                            "venue_status": venue_status,
                            "zero_fill_proof": no_fill_reason,
                        },
                    )
                    logger.info(
                        "recovery: command %s SUBMITTING -> EXPIRED (venue terminal zero-fill status=%s)",
                        cmd.command_id,
                        venue_status,
                    )
                    return "advanced"
                # Live / matched / active — ack it.
                append_event(
                    conn,
                    command_id=cmd.command_id,
                    event_type=CommandEventType.SUBMIT_ACKED.value,
                    occurred_at=now,
                    payload={"venue_order_id": venue_order_id, "venue_status": venue_status, "venue_response": venue_resp},
                )
                logger.info(
                    "recovery: command %s SUBMITTING -> ACKED (venue status=%s order %s)",
                    cmd.command_id, venue_status, venue_order_id,
                )
                return "advanced"
            else:
                # Venue returned None (order not found). Pre-fix emitted
                # EXPIRED which is grammar-illegal from SUBMITTING (HIGH-1
                # symmetric fix). Use REVIEW_REQUIRED for consistency with
                # the no-venue_order_id branch — operator distinguishes
                # "never placed" from "ack lost".
                append_event(
                    conn,
                    command_id=cmd.command_id,
                    event_type=CommandEventType.REVIEW_REQUIRED.value,
                    occurred_at=now,
                    payload={"reason": "recovery_order_not_found_at_venue", "venue_order_id": venue_order_id},
                )
                logger.warning(
                    "recovery: command %s SUBMITTING -> REVIEW_REQUIRED (order not found at venue)",
                    cmd.command_id,
                )
                return "advanced"

        # ------------------------------------------------------------------ #
        # UNKNOWN                                                             #
        # ------------------------------------------------------------------ #
        if state == CommandState.UNKNOWN:
            if venue_resp is not None:
                # Same status-aware branching as SUBMITTING (HIGH-2 symmetric).
                venue_status = _order_status(venue_resp)
                if venue_status == "REJECTED":
                    append_event(
                        conn,
                        command_id=cmd.command_id,
                        event_type=CommandEventType.SUBMIT_REJECTED.value,
                        occurred_at=now,
                        payload={"reason": "recovery_venue_rejected", "venue_order_id": venue_order_id, "venue_status": venue_status},
                    )
                    logger.info(
                        "recovery: command %s UNKNOWN -> REJECTED (venue status=%s)",
                        cmd.command_id, venue_status,
                    )
                    return "advanced"
                if venue_status in {"CANCELLED", "CANCELED", "EXPIRED"}:
                    no_fill_proven, no_fill_reason = _terminal_point_order_zero_fill_proven(
                        conn,
                        command_id=cmd.command_id,
                        point_order=venue_resp,
                    )
                    if not no_fill_proven:
                        append_event(
                            conn,
                            command_id=cmd.command_id,
                            event_type=CommandEventType.REVIEW_REQUIRED.value,
                            occurred_at=now,
                            payload={
                                "reason": no_fill_reason,
                                "venue_order_id": venue_order_id,
                                "venue_status": venue_status,
                                "venue_response": venue_resp,
                            },
                        )
                        logger.warning(
                            "recovery: command %s UNKNOWN terminal status=%s lacks zero-fill proof -> REVIEW_REQUIRED (%s)",
                            cmd.command_id,
                            venue_status,
                            no_fill_reason,
                        )
                        return "advanced"
                    append_event(
                        conn,
                        command_id=cmd.command_id,
                        event_type=CommandEventType.EXPIRED.value,
                        occurred_at=now,
                        payload={
                            "reason": "recovery_venue_terminal_no_fill",
                            "venue_order_id": venue_order_id,
                            "venue_status": venue_status,
                            "zero_fill_proof": no_fill_reason,
                        },
                    )
                    logger.info(
                        "recovery: command %s UNKNOWN -> EXPIRED (venue terminal zero-fill status=%s)",
                        cmd.command_id,
                        venue_status,
                    )
                    return "advanced"
                append_event(
                    conn,
                    command_id=cmd.command_id,
                    event_type=CommandEventType.SUBMIT_ACKED.value,
                    occurred_at=now,
                    payload={"venue_order_id": venue_order_id, "venue_status": venue_status, "venue_response": venue_resp},
                )
                logger.info(
                    "recovery: command %s UNKNOWN -> ACKED (venue status=%s order %s)",
                    cmd.command_id, venue_status, venue_order_id,
                )
                return "advanced"
            else:
                # Cannot decide: never placed vs immediately cancelled.
                append_event(
                    conn,
                    command_id=cmd.command_id,
                    event_type=CommandEventType.REVIEW_REQUIRED.value,
                    occurred_at=now,
                    payload={"reason": "recovery_unknown_order_not_found_at_venue", "venue_order_id": venue_order_id},
                )
                logger.warning(
                    "recovery: command %s UNKNOWN u2192 REVIEW_REQUIRED (order not found; ambiguous)",
                    cmd.command_id,
                )
                return "advanced"

        # ------------------------------------------------------------------ #
        # CANCEL_PENDING                                                      #
        # ------------------------------------------------------------------ #
        if state == CommandState.CANCEL_PENDING:
            if venue_resp is None:
                # Order missing at venue u2014 cancel was processed.
                append_event(
                    conn,
                    command_id=cmd.command_id,
                    event_type=CommandEventType.CANCEL_ACKED.value,
                    occurred_at=now,
                    payload={"reason": "recovery_order_missing_at_venue", "venue_order_id": venue_order_id},
                )
                logger.info(
                    "recovery: command %s CANCEL_PENDING u2192 CANCELLED (order missing at venue)",
                    cmd.command_id,
                )
                return "advanced"
            venue_status = _order_status(venue_resp)
            if venue_status in _CANCEL_TERMINAL_STATUSES:
                append_event(
                    conn,
                    command_id=cmd.command_id,
                    event_type=CommandEventType.CANCEL_ACKED.value,
                    occurred_at=now,
                    payload={"venue_order_id": venue_order_id, "venue_status": venue_status},
                )
                logger.info(
                    "recovery: command %s CANCEL_PENDING u2192 CANCELLED (venue status=%s)",
                    cmd.command_id, venue_status,
                )
                return "advanced"
            if (
                cmd.intent_kind == IntentKind.ENTRY
                and venue_status in _LIVE_ORDER_STATUSES
                and _decimal_is_zero(_explicit_point_order_matched_size(venue_resp))
            ):
                events = _command_events(conn, cmd.command_id)
                cancel_requested_payload = _latest_maker_rest_cancel_requested_payload(events)
                if cancel_requested_payload is not None:
                    cancel_request_age = _maker_rest_cancel_request_age_seconds(events, now_iso=now)
                    if (
                        cancel_request_age is not None
                        and cancel_request_age < _MAKER_REST_CANCEL_LIVE_READ_GRACE_SECONDS
                    ):
                        logger.info(
                            "recovery: command %s CANCEL_PENDING maker-rest cancel still "
                            "inside live-read grace %.1fs; venue status=%s; leaving",
                            cmd.command_id,
                            cancel_request_age,
                            venue_status,
                        )
                        return "stayed"
                    append_event(
                        conn,
                        command_id=cmd.command_id,
                        event_type=CommandEventType.CANCEL_REPLACE_BLOCKED.value,
                        occurred_at=now,
                        payload={
                            "venue_order_id": venue_order_id,
                            "reason": "post_cancel_unknown_possible_side_effect",
                            "requires_m5_reconcile": True,
                            "semantic_cancel_status": "CANCEL_UNKNOWN",
                            "cancel_outcome": {
                                "status": "LIVE_AFTER_CANCEL_REQUEST",
                                "venue_status": venue_status,
                                "source": "command_recovery_cancel_pending_live_read",
                                "latest_cancel_requested_payload": cancel_requested_payload,
                            },
                        },
                    )
                    review_cmd = replace(cmd, state=CommandState.REVIEW_REQUIRED)
                    outcome = _review_required_cancel_unknown_live_order_recovery(
                        conn,
                        review_cmd,
                        client,
                    )
                    if outcome == "error":
                        return "error"
                    return "advanced"
            # Order still active; cancel ack pending.
            logger.info(
                "recovery: command %s CANCEL_PENDING; venue status=%s; leaving (cancel ack pending)",
                cmd.command_id, venue_status,
            )
            return "stayed"

        # Should not reach here for valid IN_FLIGHT_STATES.
        logger.warning("recovery: command %s state=%s not handled; skipping", cmd.command_id, state.value)
        return "stayed"

    except ValueError as exc:
        # Illegal grammar transition from append_event u2014 log and skip.
        logger.error(
            "recovery: command %s invalid transition: %s; skipping row",
            cmd.command_id, exc,
        )
        return "error"
    except Exception as exc:
        logger.error(
            "recovery: command %s raised %s: %s; skipping row",
            cmd.command_id, type(exc).__name__, exc,
        )
        return "error"


def drain_screen_redecision_cancel_obligations(
    client,
    *,
    deadline_monotonic: float,
) -> dict[str, int]:
    """Execute only marked screen cancel debt in the bounded recovery lane.

    SCOPE is one command/order marker. DRAIN is the scheduled command-recovery
    cadence. RESET is the executor's ACKED/CANCELLED evidence; unstarted work
    remains CANCEL_PENDING for the next cadence.
    """

    from src.execution.venue_cancel_journal import (
        dispatch_screen_redecision_cancel_obligations,
        find_screen_redecision_cancel_obligations,
    )
    from src.state.db import get_trade_connection, get_trade_connection_read_only

    summary = {"scanned": 0, "cancelled": 0, "deferred": 0, "errors": 0}
    if time.monotonic() >= deadline_monotonic:
        summary["deferred"] = 1
        return summary
    try:
        read_conn = get_trade_connection_read_only(
            deadline_monotonic=deadline_monotonic,
        )
    except sqlite3.OperationalError as exc:
        if time.monotonic() >= deadline_monotonic or "DB_CONNECTION_DEADLINE_EXPIRED" in str(exc):
            summary["deferred"] = 1
            return summary
        raise
    try:
        remaining_ms = max(1, int((deadline_monotonic - time.monotonic()) * 1000))
        read_conn.execute(f"PRAGMA busy_timeout = {remaining_ms}")
        read_conn.set_progress_handler(lambda: int(time.monotonic() >= deadline_monotonic), 1000)
        entries = find_screen_redecision_cancel_obligations(
            read_conn,
            deadline_monotonic=deadline_monotonic,
        )
    finally:
        read_conn.close()
    if not entries:
        return summary
    summary["scanned"] = len(entries)
    obligation_deadline = min(
        time.monotonic() + _SCREEN_CANCEL_OPERATION_BUDGET_SECONDS,
        deadline_monotonic,
    )

    class _DeadlineClient:
        def __init__(self, wrapped):
            self._wrapped = wrapped

        def get_order(self, order_id, *, deadline_monotonic=None):
            deadline = deadline_monotonic or obligation_deadline
            if deadline is not None and time.monotonic() >= deadline:
                raise TimeoutError("screen_cancel_obligation_deadline_exhausted")
            return self._wrapped.get_order(order_id, deadline_monotonic=deadline)

        def cancel_order(self, order_id, *, deadline_monotonic=None):
            deadline = deadline_monotonic or obligation_deadline
            if time.monotonic() >= deadline:
                raise TimeoutError("screen_cancel_obligation_deadline_exhausted")
            return self._wrapped.cancel_order(
                order_id,
                deadline_monotonic=deadline,
            )

    stats = dispatch_screen_redecision_cancel_obligations(
        entries,
        _DeadlineClient(client),
        conn_factory=lambda *, deadline_monotonic: get_trade_connection(
            write_class="live",
            deadline_monotonic=deadline_monotonic,
        ),
        deadline_monotonic=obligation_deadline,
        owner=_SCREEN_CANCEL_DISPATCH_BOOT_ID,
    )
    summary["cancelled"] = int(stats.get("cancelled", 0) or 0)
    summary["errors"] = int(stats.get("errors", 0) or 0) + int(stats.get("journal_failed", 0) or 0)
    summary["deferred"] = int(stats.get("deferred", 0) or 0)
    return summary


def reconcile_unresolved_commands(
    conn: Optional[sqlite3.Connection] = None,
    client=None,
    *,
    scope: str = "full",
    deadline_monotonic: float | None = None,
) -> dict:
    """Scan unresolved venue_commands and apply reconciliation events.

    Returns a summary dict {"scanned": N, "advanced": M, "stayed": K, "errors": L}
    so cycle_runner can record it in the cycle summary.

    Each row in IN_FLIGHT_STATES is looked up at the venue (if it has a
    venue_order_id) and an event is appended per §P1.S4. Rows in
    REVIEW_REQUIRED are skipped (operator-handoff). Rows without a
    venue_order_id and in SUBMITTING get a REVIEW_REQUIRED event since recovery
    cannot distinguish never-placed from ack-lost side effects.

    ``scope="full"`` keeps the historical complete sweep. ``scope="live_tick"``
    is for the live order daemon's frequent scheduler cadence: it reconciles the
    critical in-flight command surface, terminal/no-fill locks, and current
    partial/fill maintenance without holding one long-lived DB connection.
    ``scope="boot_fast"`` is narrower: it clears submit/cap/family locks before
    scheduler start and repairs command-backed execution facts needed by the
    capital allocator, but deliberately skips historical maker-fill economics
    and partial-remainder maintenance so boot cannot be delayed by old filled
    rows.
    ``scope="restart_preflight"`` is the deploy-time recovery seam: it runs only
    the venue-backed in-flight command scan, DB-local ACKED/live-entry and
    matched-cancel entry projection repair, and the no-venue EXIT retry
    projection needed to clear restart-dangerous pending entries/exits before
    the read-only restart preflight. It must stay narrower than ``live_tick``.

    DB connection: if conn is None, opens get_trade_connection_with_world_required()
    internally (with a try/finally to close). CycleRunner passes the per-cycle
    trade/world connection; the internal-open path remains the external-caller
    fallback.

    PolymarketClient: if client is None, lazily constructed here.

    CONNECTION TOPOLOGY (dependency_db_locked antibody, 2026-06-11):

      * ``conn`` PROVIDED (legacy cycle_runner lane + all INV-31 anchor tests):
        the caller owns the connection lifetime and threads its own per-cycle
        trade/world connection through every pass — the historical shape. This
        path is byte-identical to before.

      * ``conn is None`` (the EDLI scheduled-job lane, #28c): runs the
        per-pass SHORT-CONNECTION three-phase flow via
        ``src.execution.venue_sync_contract``. No single connection is held
        across venue REST I/O, and no connection spans more than one pass — so
        the sweep can never again pin the zeus_trades WAL write lock across a
        multi-minute venue-read sweep and starve other writers into the
        DATA_DEGRADED / RISK_GUARD_BLOCKED cascade observed since ~03:36Z on
        2026-06-11. Reconciliation SEMANTICS are unchanged: each pass body runs
        verbatim against a venue snapshot captured off-lock.
    """
    if scope not in {"full", "live_tick", "boot_fast", "restart_preflight"}:
        raise ValueError(f"unsupported command recovery scope: {scope!r}")
    if conn is not None and scope != "full":
        raise ValueError("non-full command recovery scopes require conn=None")
    if conn is not None and deadline_monotonic is not None:
        raise ValueError("caller-owned recovery cannot use a scheduled deadline")

    if client is None:
        from src.data.polymarket_client import PolymarketClient
        remaining = (
            max(0.1, min(2.0, deadline_monotonic - time.monotonic()))
            if deadline_monotonic is not None
            else None
        )
        client = PolymarketClient(public_http_timeout=remaining)

    summary = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
    started_at = _now_iso()

    if conn is None and scope in {"live_tick", "full"} and deadline_monotonic is not None:
        obligation_summary = drain_screen_redecision_cancel_obligations(
            client,
            deadline_monotonic=deadline_monotonic,
        )
        summary["screen_redecision_cancel_obligations"] = obligation_summary
        summary["advanced"] += int(obligation_summary.get("cancelled", 0) or 0)
        summary["stayed"] += int(obligation_summary.get("deferred", 0) or 0)
        summary["errors"] += int(obligation_summary.get("errors", 0) or 0)

    if conn is None:
        # Scheduled-job lane: per-pass short connections, no conn across network.
        _reconcile_passes_short_conn(
            client,
            summary,
            started_at,
            scope=scope,
            deadline_monotonic=deadline_monotonic,
        )
        logger.info(
            "recovery: scanned=%d advanced=%d stayed=%d errors=%d",
            summary["scanned"], summary["advanced"], summary["stayed"], summary["errors"],
        )
        return summary

    # Legacy caller-owned-connection lane (unchanged).
    _reconcile_passes_inline(conn, client, summary, started_at)
    logger.info(
        "recovery: scanned=%d advanced=%d stayed=%d errors=%d",
        summary["scanned"], summary["advanced"], summary["stayed"], summary["errors"],
    )
    return summary


def _reconcile_passes_inline(
    conn: sqlite3.Connection,
    client,
    summary: dict,
    started_at: str,
) -> None:
    """Legacy caller-owned-connection pass sequence.

    The caller (cycle_runner or an INV-31 anchor test) owns ``conn`` and threads
    it through every pass. Positive matched order facts intentionally run before
    terminal no-fill projection so late venue fills cannot be voided by an older
    cancel/expire terminal row.
    """
    if True:  # preserve original indentation of the extracted body verbatim
        edli_confirmed_command_summary = reconcile_edli_confirmed_legacy_command_repairs(conn)
        summary["edli_confirmed_legacy_command_repair"] = edli_confirmed_command_summary
        summary["advanced"] += edli_confirmed_command_summary["advanced"]
        summary["stayed"] += edli_confirmed_command_summary["stayed"]
        summary["errors"] += edli_confirmed_command_summary["errors"]

        stale_intent_summary = reconcile_stale_intent_created_no_submit(
            conn,
            updated_before=started_at,
        )
        summary["stale_intent_created_no_submit"] = stale_intent_summary
        summary["advanced"] += stale_intent_summary["advanced"]
        summary["stayed"] += stale_intent_summary["stayed"]
        summary["errors"] += stale_intent_summary["errors"]

        abandoned_ghost_summary = reconcile_abandoned_unsubmitted_ghosts(
            conn,
            updated_before=started_at,
        )
        summary["abandoned_unsubmitted_ghosts"] = abandoned_ghost_summary
        summary["advanced"] += int(abandoned_ghost_summary.get("advanced", 0))
        summary["stayed"] += int(abandoned_ghost_summary.get("stayed", 0))
        summary["errors"] += int(abandoned_ghost_summary.get("errors", 0))

        review_mutex_summary = reconcile_review_required_exit_mutex_releases(conn)
        summary["review_required_exit_mutex_release"] = review_mutex_summary
        summary["advanced"] += review_mutex_summary["advanced"]
        summary["stayed"] += review_mutex_summary["stayed"]
        summary["errors"] += review_mutex_summary["errors"]

        authenticated_entry_fill_summary = (
            reconcile_authenticated_entry_trade_facts(conn)
        )
        summary["authenticated_entry_trade_fact"] = authenticated_entry_fill_summary
        summary["advanced"] += authenticated_entry_fill_summary["advanced"]
        summary["stayed"] += authenticated_entry_fill_summary["stayed"]
        summary["errors"] += authenticated_entry_fill_summary["errors"]

        matched_submit_fact_summary = (
            reconcile_review_required_matched_submit_trade_facts(conn)
        )
        summary["review_required_matched_submit_trade_fact"] = (
            matched_submit_fact_summary
        )
        summary["advanced"] += matched_submit_fact_summary["advanced"]
        summary["stayed"] += matched_submit_fact_summary["stayed"]
        summary["errors"] += matched_submit_fact_summary["errors"]

        rows = find_unresolved_commands(conn)
        summary["scanned"] = len(rows)

        for row in rows:
            try:
                cmd = VenueCommand.from_row(row)
            except Exception as exc:
                logger.error(
                    "recovery: malformed row (command_id=%r): %s; skipping",
                    row.get("command_id"), exc,
                )
                summary["errors"] += 1
                continue

            try:
                outcome = _reconcile_row(conn, cmd, client)
            except PositiveOrderFactContradictionError:
                logger.info(
                    "recovery: command %s stayed for positive-fill reconciliation",
                    cmd.command_id,
                )
                summary["stayed"] += 1
                continue
            if outcome == "advanced":
                summary["advanced"] += 1
            elif outcome == "stayed":
                summary["stayed"] += 1
            else:
                summary["errors"] += 1

        local_orphan_summary = reconcile_local_orphan_no_fill_findings(conn, client)
        summary["local_orphan_no_fill_findings"] = local_orphan_summary
        summary["advanced"] += local_orphan_summary["advanced"]
        summary["stayed"] += local_orphan_summary["stayed"]
        summary["errors"] += local_orphan_summary["errors"]

        terminal_point_summary = reconcile_terminal_point_orders(conn, client)
        summary["terminal_point_orders"] = terminal_point_summary
        summary["advanced"] += terminal_point_summary["advanced"]
        summary["stayed"] += terminal_point_summary["stayed"]
        summary["errors"] += terminal_point_summary["errors"]

        matched_summary = reconcile_matched_order_facts(conn, client)
        summary["matched_order_facts"] = matched_summary
        summary["advanced"] += matched_summary["advanced"]
        summary["stayed"] += matched_summary["stayed"]
        summary["errors"] += matched_summary["errors"]

        filled_exit_tx_summary = reconcile_filled_exit_trade_fact_tx_repairs(conn)
        summary["filled_exit_trade_fact_tx_repair"] = filled_exit_tx_summary
        summary["advanced"] += filled_exit_tx_summary["advanced"]
        summary["stayed"] += filled_exit_tx_summary["stayed"]
        summary["errors"] += filled_exit_tx_summary["errors"]

        cancel_ack_terminal_summary = reconcile_cancel_ack_terminal_no_fill_facts(conn)
        summary["cancel_ack_terminal_no_fill_facts"] = cancel_ack_terminal_summary
        summary["advanced"] += cancel_ack_terminal_summary["advanced"]
        summary["stayed"] += cancel_ack_terminal_summary["stayed"]
        summary["errors"] += cancel_ack_terminal_summary["errors"]

        cancel_ack_partial_summary = reconcile_cancel_ack_terminal_partial_facts(conn)
        summary["cancel_ack_terminal_partial_facts"] = cancel_ack_partial_summary
        summary["advanced"] += cancel_ack_partial_summary["advanced"]
        summary["stayed"] += cancel_ack_partial_summary["stayed"]
        summary["errors"] += cancel_ack_partial_summary["errors"]

        terminal_summary = reconcile_terminal_order_facts(conn)
        summary["terminal_order_facts"] = terminal_summary
        summary["advanced"] += terminal_summary["advanced"]
        summary["stayed"] += terminal_summary["stayed"]
        summary["errors"] += terminal_summary["errors"]

        stale_terminal_summary = reconcile_stale_terminal_no_fill_findings(conn)
        summary["stale_terminal_no_fill_findings"] = stale_terminal_summary
        summary["advanced"] += stale_terminal_summary["advanced"]
        summary["stayed"] += stale_terminal_summary["stayed"]
        summary["errors"] += stale_terminal_summary["errors"]

        edli_post_submit_absence_summary = _reconcile_edli_post_submit_unknown_absence(
            conn,
            client,
        )
        summary["edli_post_submit_unknown_absence"] = edli_post_submit_absence_summary
        summary["advanced"] += edli_post_submit_absence_summary["advanced"]
        summary["stayed"] += edli_post_submit_absence_summary["stayed"]
        summary["errors"] += edli_post_submit_absence_summary["errors"]

        completed_partial_summary = reconcile_completed_partial_order_facts(conn)
        summary["completed_partial_order_facts"] = completed_partial_summary
        summary["advanced"] += completed_partial_summary["advanced"]
        summary["stayed"] += completed_partial_summary["stayed"]
        summary["errors"] += completed_partial_summary["errors"]

        matched_cancel_review_summary = reconcile_matched_cancel_review_required_entries(conn)
        summary["matched_cancel_review_required_entries"] = matched_cancel_review_summary
        summary["advanced"] += matched_cancel_review_summary["advanced"]
        summary["errors"] += matched_cancel_review_summary["errors"]

        terminal_positive_entry_projection_summary = (
            reconcile_terminal_positive_entry_projection_repairs(conn)
        )
        summary["terminal_positive_entry_projection_repair"] = (
            terminal_positive_entry_projection_summary
        )
        summary["advanced"] += terminal_positive_entry_projection_summary["advanced"]
        summary["stayed"] += terminal_positive_entry_projection_summary["stayed"]
        summary["errors"] += terminal_positive_entry_projection_summary["errors"]

        edli_pre_venue_summary = _reconcile_edli_pre_venue_unknown_thresholds(conn)
        summary["edli_pre_venue_unknown_thresholds"] = edli_pre_venue_summary
        summary["advanced"] += edli_pre_venue_summary["advanced"]
        summary["stayed"] += edli_pre_venue_summary["stayed"]
        summary["errors"] += edli_pre_venue_summary["errors"]

        edli_absence_sync_summary = _reconcile_venue_command_absence_sync(conn)
        summary["venue_command_absence_sync"] = edli_absence_sync_summary
        summary["advanced"] += edli_absence_sync_summary["advanced"]
        summary["stayed"] += edli_absence_sync_summary["stayed"]
        summary["errors"] += edli_absence_sync_summary["errors"]

        edli_ack_sync_summary = reconcile_edli_acknowledged_venue_command_sync(conn)
        summary["edli_acknowledged_venue_command_sync"] = edli_ack_sync_summary
        summary["advanced"] += edli_ack_sync_summary["advanced"]
        summary["stayed"] += edli_ack_sync_summary["stayed"]
        summary["errors"] += edli_ack_sync_summary["errors"]

        edli_rejected_sync_summary = reconcile_edli_rejected_venue_command_sync(conn)
        summary["edli_rejected_venue_command_sync"] = edli_rejected_sync_summary
        summary["advanced"] += edli_rejected_sync_summary["advanced"]
        summary["stayed"] += edli_rejected_sync_summary["stayed"]
        summary["errors"] += edli_rejected_sync_summary["errors"]

        live_entry_repair_summary = reconcile_live_entry_projection_repairs(conn, client=client)
        summary["live_entry_projection_repair"] = live_entry_repair_summary
        summary["advanced"] += live_entry_repair_summary["advanced"]
        summary["stayed"] += live_entry_repair_summary["stayed"]
        summary["errors"] += live_entry_repair_summary["errors"]

        filled_entry_link_summary = reconcile_filled_entry_position_link_repairs(conn)
        summary["filled_entry_position_link_repair"] = filled_entry_link_summary
        summary["advanced"] += filled_entry_link_summary["advanced"]
        summary["stayed"] += filled_entry_link_summary["stayed"]
        summary["errors"] += filled_entry_link_summary["errors"]

        filled_entry_repair_summary = reconcile_filled_entry_projection_repairs(conn, client=client)
        summary["filled_entry_projection_repair"] = filled_entry_repair_summary
        summary["advanced"] += filled_entry_repair_summary["advanced"]
        summary["stayed"] += filled_entry_repair_summary["stayed"]
        summary["errors"] += filled_entry_repair_summary["errors"]

        edli_entry_posterior_summary = reconcile_edli_entry_posterior_projection_repairs(
            conn,
            client=client,
        )
        summary["edli_entry_posterior_projection_repair"] = edli_entry_posterior_summary
        summary["advanced"] += edli_entry_posterior_summary["advanced"]
        summary["stayed"] += edli_entry_posterior_summary["stayed"]
        summary["errors"] += edli_entry_posterior_summary["errors"]

        invalid_entry_authority_summary = reconcile_invalid_open_entry_authority_reviews(conn)
        summary["invalid_open_entry_authority_review"] = invalid_entry_authority_summary
        summary["advanced"] += invalid_entry_authority_summary["advanced"]
        summary["stayed"] += invalid_entry_authority_summary["stayed"]
        summary["errors"] += invalid_entry_authority_summary["errors"]

        hard_terminal_projection_summary = reconcile_hard_terminal_position_projection_repairs(conn)
        summary["hard_terminal_position_projection_repair"] = hard_terminal_projection_summary
        summary["advanced"] += hard_terminal_projection_summary["advanced"]
        summary["stayed"] += hard_terminal_projection_summary["stayed"]
        summary["errors"] += hard_terminal_projection_summary["errors"]

        filled_entry_lot_summary = reconcile_filled_entry_position_lot_repairs(conn)
        summary["filled_entry_position_lot_repair"] = filled_entry_lot_summary
        summary["advanced"] += filled_entry_lot_summary["advanced"]
        summary["stayed"] += filled_entry_lot_summary["stayed"]
        summary["errors"] += filled_entry_lot_summary["errors"]

        filled_entry_execution_fact_summary = reconcile_filled_entry_execution_fact_repairs(conn)
        summary["filled_entry_execution_fact_repair"] = filled_entry_execution_fact_summary
        summary["advanced"] += filled_entry_execution_fact_summary["advanced"]
        summary["stayed"] += filled_entry_execution_fact_summary["stayed"]
        summary["errors"] += filled_entry_execution_fact_summary["errors"]

        entry_obligation_summary = reconcile_terminal_entry_exposure_obligations(conn)
        summary["terminal_entry_exposure_obligations"] = entry_obligation_summary
        summary["advanced"] += entry_obligation_summary["advanced"]
        summary["stayed"] += entry_obligation_summary["stayed"]
        summary["errors"] += entry_obligation_summary["errors"]

        exit_pending_summary = reconcile_exit_pending_projections(conn)
        summary["exit_pending_projections"] = exit_pending_summary
        summary["advanced"] += exit_pending_summary["advanced"]
        summary["stayed"] += exit_pending_summary["stayed"]
        summary["errors"] += exit_pending_summary["errors"]

        exit_lifecycle_alignment_summary = reconcile_exit_lifecycle_alignment_repairs(conn)
        summary["exit_lifecycle_alignment_repair"] = exit_lifecycle_alignment_summary
        summary["advanced"] += exit_lifecycle_alignment_summary["advanced"]
        summary["stayed"] += exit_lifecycle_alignment_summary["stayed"]
        summary["errors"] += exit_lifecycle_alignment_summary["errors"]

        recovered_partial_exit_summary = reconcile_recovered_partial_exit_economics(
            conn, observed_at=started_at
        )
        summary["recovered_partial_exit_economics"] = recovered_partial_exit_summary
        summary["advanced"] += recovered_partial_exit_summary["advanced"]
        summary["stayed"] += recovered_partial_exit_summary["stayed"]
        summary["errors"] += recovered_partial_exit_summary["errors"]

        confirmed_phantom_void_summary = repair_confirmed_phantom_voids(conn)
        summary["confirmed_phantom_void_repair"] = confirmed_phantom_void_summary
        summary["advanced"] += confirmed_phantom_void_summary["advanced"]
        summary["stayed"] += confirmed_phantom_void_summary["stayed"]
        summary["errors"] += confirmed_phantom_void_summary["errors"]

        chain_absence_projection_summary = repair_confirmed_chain_absence_positive_projections(conn)
        summary["confirmed_chain_absence_projection_repair"] = chain_absence_projection_summary
        summary["advanced"] += chain_absence_projection_summary["advanced"]
        summary["stayed"] += chain_absence_projection_summary["stayed"]
        summary["errors"] += chain_absence_projection_summary["errors"]

        partial_summary = reconcile_partial_remainders(
            conn,
            client,
            updated_before=started_at,
        )
        summary["partial_remainders"] = partial_summary
        summary["advanced"] += partial_summary["advanced"]
        summary["stayed"] += partial_summary["stayed"]
        summary["errors"] += partial_summary["errors"]

        terminal_exit_release_summary = reconcile_pending_exit_terminal_order_releases(conn)
        summary["pending_exit_terminal_order_releases"] = terminal_exit_release_summary
        summary["advanced"] += terminal_exit_release_summary["advanced"]
        summary["stayed"] += terminal_exit_release_summary["stayed"]
        summary["errors"] += terminal_exit_release_summary["errors"]

        from src.execution.exchange_reconcile import reconcile_recorded_maker_fill_economics

        maker_fill_summary = reconcile_recorded_maker_fill_economics(
            conn,
            observed_at=started_at,
            live_tick_scope=True,
        )
        summary["recorded_maker_fill_economics"] = maker_fill_summary
        summary["advanced"] += maker_fill_summary["corrected"]
        summary["errors"] += maker_fill_summary["errors"]

        # Maker-fill reconciliation may refresh an execution_fact from a
        # stale terminal MATCHED order fact. Re-apply canonical trade/order
        # truth so a terminal FAK partial is still recorded as PARTIAL.
        post_maker_execution_summary = reconcile_filled_entry_execution_fact_repairs(conn)
        summary["post_maker_execution_fact_repair"] = post_maker_execution_summary
        summary["advanced"] += post_maker_execution_summary["advanced"]
        summary["stayed"] += post_maker_execution_summary["stayed"]
        summary["errors"] += post_maker_execution_summary["errors"]

        closed_shift_summary = release_closed_shift_bin_exit_leases(
            conn,
            observed_at=started_at,
        )
        summary["closed_shift_bin_exit_leases"] = closed_shift_summary
        summary["advanced"] += closed_shift_summary["advanced"]
        summary["stayed"] += closed_shift_summary["stayed"]
        summary["errors"] += closed_shift_summary["errors"]

        stale_rebalance_entry_summary = release_stale_rebalance_entry_leases(
            conn,
            observed_at=started_at,
        )
        summary["stale_rebalance_entry_leases"] = stale_rebalance_entry_summary
        summary["advanced"] += stale_rebalance_entry_summary["advanced"]
        summary["stayed"] += stale_rebalance_entry_summary["stayed"]
        summary["errors"] += stale_rebalance_entry_summary["errors"]


def _accumulate(
    summary: dict,
    key: str,
    pass_summary: dict,
    *,
    advanced_key: str = "advanced",
    fold_stayed: bool = True,
) -> None:
    """Fold a pass summary into the running total exactly as the legacy body did.

    ``fold_stayed`` mirrors the legacy asymmetry: every pass folded ``stayed``
    EXCEPT the final ``reconcile_recorded_maker_fill_economics`` pass, which only
    contributed ``corrected`` -> advanced and ``errors``.
    """
    existing = summary.get(key)
    if isinstance(existing, dict):
        merged = dict(existing)
        for count_key in ("scanned", "advanced", "stayed", "errors"):
            if count_key in pass_summary or count_key in merged:
                merged[count_key] = int(merged.get(count_key, 0) or 0) + int(
                    pass_summary.get(count_key, 0) or 0
                )
        if advanced_key not in {"advanced", "stayed", "errors", "scanned"}:
            merged[advanced_key] = int(merged.get(advanced_key, 0) or 0) + int(
                pass_summary.get(advanced_key, 0) or 0
            )
        continuations = list(existing.get("continuations") or [])
        continuations.extend(pass_summary.get("continuations") or [])
        if continuations:
            merged["continuations"] = continuations
        summary[key] = merged
    else:
        summary[key] = pass_summary
    summary["advanced"] += pass_summary[advanced_key]
    if fold_stayed:
        summary["stayed"] += pass_summary.get("stayed", 0)
    summary["errors"] += pass_summary["errors"]


def _recovery_apply_conn_factory(
    conn_factory,
    *,
    scope: str,
    deadline_monotonic: float | None = None,
    monitor_preemptible: bool = True,
):
    bounded_scope = scope in {"live_tick", "restart_preflight"} or (
        scope == "full" and deadline_monotonic is not None
    )
    if not bounded_scope:
        return conn_factory

    def _nowait_conn():
        if deadline_monotonic is not None and time.monotonic() >= deadline_monotonic:
            raise _LiveTickDBBudgetExhausted
        if getattr(conn_factory, "supports_nonblocking_flocks", False):
            conn = conn_factory(blocking=False, busy_timeout_ms=0)
        else:
            conn = conn_factory()
        try:
            if not getattr(conn_factory, "supports_nonblocking_flocks", False):
                conn.execute("PRAGMA busy_timeout = 0")
            if deadline_monotonic is not None:
                from src.state.write_coordinator import (
                    DBIdentity,
                    default_runtime_write_coordinator,
                )

                coordinator = default_runtime_write_coordinator()
                pending_monitor = coordinator.has_pending_monitor_waiter

                def _apply_progress_cancelled() -> int:
                    if time.monotonic() >= deadline_monotonic:
                        return 1
                    if monitor_preemptible and pending_monitor(
                        (DBIdentity.TRADE,)
                    ):
                        _RECOVERY_MONITOR_PREEMPTION.pending = True
                        return 1
                    return 0

                set_progress_handler = getattr(conn, "set_progress_handler", None)
                if callable(set_progress_handler):
                    set_progress_handler(
                        _apply_progress_cancelled,
                        _LIVE_TICK_DB_PROGRESS_OPCODES,
                    )
        except BaseException:
            conn.close()
            raise
        return conn

    return _nowait_conn


class _PriorityRecoveryConnection:
    """Close a recovery connection and its one process-shared writer lease."""

    def __init__(self, conn, lease_context) -> None:
        self._conn = conn
        self._lease_context = lease_context
        self._closed = False
        self._lease_released = False

    def __getattr__(self, name):
        return getattr(self._conn, name)

    def __enter__(self):
        if self._closed:
            raise RuntimeError("recovery connection is already closed")
        try:
            enter = getattr(type(self._conn), "__enter__", None)
            if enter is not None:
                enter(self._conn)
        except BaseException:
            self.close()
            raise
        return self

    def __exit__(self, exc_type, exc, tb):
        if self._closed:
            return False
        result = False
        try:
            exit_method = getattr(type(self._conn), "__exit__", None)
            if exit_method is not None:
                result = bool(exit_method(self._conn, exc_type, exc, tb))
        finally:
            self.close()
        return result

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        try:
            self._conn.close()
        finally:
            if not self._lease_released:
                self._lease_released = True
                self._lease_context.__exit__(None, None, None)


def _recovery_priority_conn_factory(
    conn_factory,
    *,
    scope: str,
    deadline_monotonic: float | None = None,
):
    """Add the typed coordinator priority to the canonical recovery factory."""

    if not getattr(conn_factory, "requires_writer_flocks", False):
        return conn_factory

    from src.state.write_coordinator import (
        DBIdentity,
        WritePriority,
        default_runtime_write_coordinator,
    )

    priority = (
        WritePriority.BACKGROUND_RECOVERY
        if scope == "full"
        else WritePriority.RECOVERY_CRITICAL
    )

    def _factory(*, blocking: bool = True, busy_timeout_ms: int | None = None):
        if priority is WritePriority.BACKGROUND_RECOVERY:
            lease_deadline_ms = 0
        elif deadline_monotonic is None:
            lease_deadline_ms = int(_LIVE_TICK_DB_BUDGET_SECONDS * 1000)
        else:
            lease_deadline_ms = max(
                0,
                int((deadline_monotonic - time.monotonic()) * 1000),
            )
        lease_context = default_runtime_write_coordinator().lease(
            (DBIdentity.TRADE,),
            owner=f"command_recovery_{scope}_apply",
            priority=priority,
            deadline_ms=lease_deadline_ms,
        )
        lease_context.__enter__()
        try:
            conn = conn_factory(
                blocking=blocking,
                busy_timeout_ms=busy_timeout_ms,
            )
        except BaseException as exc:
            lease_context.__exit__(type(exc), exc, exc.__traceback__)
            raise
        return _PriorityRecoveryConnection(conn, lease_context)

    _factory.requires_writer_flocks = True  # type: ignore[attr-defined]
    _factory.supports_nonblocking_flocks = getattr(  # type: ignore[attr-defined]
        conn_factory,
        "supports_nonblocking_flocks",
        False,
    )
    return _factory


def _install_recovery_read_deadline(conn, deadline_monotonic: float) -> None:
    """Install the legacy bounded-read deadline callback on ``conn``."""

    set_progress_handler = getattr(conn, "set_progress_handler", None)
    if callable(set_progress_handler):
        set_progress_handler(
            lambda: int(time.monotonic() >= deadline_monotonic),
            _LIVE_TICK_DB_PROGRESS_OPCODES,
        )


def _recovery_read_conn_factory(
    conn_factory,
    *,
    deadline_monotonic: float | None,
):
    if deadline_monotonic is None:
        return conn_factory

    def _bounded_read_conn():
        if time.monotonic() >= deadline_monotonic:
            raise _LiveTickDBBudgetExhausted
        conn = conn_factory()
        try:
            conn.execute("PRAGMA busy_timeout = 0")
            _install_recovery_read_deadline(conn, deadline_monotonic)
        except BaseException:
            conn.close()
            raise
        return conn

    return _bounded_read_conn


def _run_recovery_pass_with_lock_policy(
    label: str,
    fn,
    *,
    scope: str,
    summary: dict,
    deadline_monotonic: float | None = None,
    bounded_lock_retry_delays: Sequence[float] = (),
):
    bounded_scope = scope in {"live_tick", "restart_preflight"} or (
        scope == "full" and deadline_monotonic is not None
    )
    if bounded_scope and (
        summary.get("db_lock_deferred") or summary.get("db_budget_deferred")
    ):
        return None

    lock_retry_delays = (
        tuple(max(0.0, float(delay)) for delay in bounded_lock_retry_delays)
        if bounded_scope
        else _RECOVERY_LOCK_RETRY_DELAYS
    )
    for attempt in range(len(lock_retry_delays) + 1):
        _RECOVERY_MONITOR_PREEMPTION.pending = False
        try:
            return fn()
        except _LiveTickDBBudgetExhausted:
            summary["db_budget_deferred"] = True
            summary["db_budget_deferred_at"] = label
            summary["db_budget_deferred_count"] = 1
            logger.info(
                "recovery: live_tick DB budget exhausted at pass %s; "
                "remaining apply work will retry next tick",
                label,
            )
            return None
        except (BlockingIOError, WriteLeaseTimeout, sqlite3.OperationalError) as exc:
            message = str(exc)
            if bool(getattr(_RECOVERY_MONITOR_PREEMPTION, "pending", False)):
                _RECOVERY_MONITOR_PREEMPTION.pending = False
                summary["monitor_preempted"] = True
                summary["monitor_preempted_at"] = label
                summary["db_lock_deferred"] = True
                summary["db_lock_deferred_at"] = label
                summary["db_lock_deferred_count"] = 1
                logger.info(
                    "recovery: %s pass %s yielded its write quantum to held monitor; "
                    "remaining apply work will retry next tick",
                    scope,
                    label,
                )
                return None
            is_budget = (
                bounded_scope
                and deadline_monotonic is not None
                and time.monotonic() >= deadline_monotonic
                and isinstance(exc, sqlite3.OperationalError)
                and "interrupted" in message.lower()
            )
            if is_budget:
                summary["db_budget_deferred"] = True
                summary["db_budget_deferred_at"] = label
                summary["db_budget_deferred_count"] = 1
                logger.info(
                    "recovery: live_tick DB budget interrupted pass %s; "
                    "remaining apply work will retry next tick",
                    label,
                )
                return None
            is_lock = isinstance(exc, WriteLeaseTimeout) or (
                isinstance(exc, BlockingIOError)
                and "db_writer_lock(" in message
                and "contended on" in message
            ) or (
                isinstance(exc, sqlite3.OperationalError)
                and message.startswith("database is locked")
            )
            if not is_lock:
                raise
            if bounded_scope:
                if attempt < len(lock_retry_delays):
                    delay = lock_retry_delays[attempt]
                    if (
                        deadline_monotonic is None
                        or time.monotonic() + delay < deadline_monotonic
                    ):
                        time.sleep(delay)
                        continue
                summary["db_lock_deferred"] = True
                summary["db_lock_deferred_at"] = label
                summary["db_lock_deferred_count"] = 1
                logger.info(
                    "recovery: bounded %s pass %s deferred on DB contention; "
                    "remaining apply work will retry next tick",
                    scope,
                    label,
                )
                return None
            if attempt >= len(lock_retry_delays):
                raise
            delay = lock_retry_delays[attempt]
            logger.warning(
                "recovery: pass %s hit database lock; retrying in %.1fs (attempt %d/%d)",
                label,
                delay,
                attempt + 1,
                len(lock_retry_delays) + 1,
            )
            time.sleep(delay)


def _recovery_priming_monitor_preempt_requested() -> bool:
    """Return whether the monitor has reserved the trade writer turn.

    Priming must never acquire the writer lease.  The callback is intentionally
    fail-closed: if coordinator state cannot be read, the expensive read is
    interrupted and the caller defers the whole priming/apply continuation.
    """

    try:
        from src.state.write_coordinator import (
            DBIdentity,
            default_runtime_write_coordinator,
        )

        return bool(
            default_runtime_write_coordinator().has_pending_monitor_waiter(
                (DBIdentity.TRADE,)
            )
        )
    except BaseException:  # noqa: BLE001 - preemption state must fail closed.
        logger.warning(
            "recovery: priming monitor-preempt callback failed; interrupting read",
            exc_info=True,
        )
        return True


@contextlib.contextmanager
def _open_recovery_priming_read_connection(
    conn_factory,
    *,
    deadline_monotonic: float,
    preempt_callback: Callable[[], bool] | None = None,
    state: dict[str, str] | None = None,
):
    """Open, interrupt, and close the priming connection as one RO unit.

    The production ``default_trade_read_conn_factory`` opens a ``mode=ro``
    SQLite URI without writer flocks.  ``query_only`` is asserted here too so
    test/fallback factories cannot accidentally turn the priming phase into a
    write path.  Cleanup is kept inside this context rather than delegated to
    the caller: clear the progress handler, rollback any read snapshot, and
    close before APPLY can acquire a writer lease.
    """

    conn = None
    try:
        if time.monotonic() >= deadline_monotonic:
            raise _LiveTickDBBudgetExhausted
        conn = conn_factory()
        conn.execute("PRAGMA query_only = ON")
        query_only = conn.execute("PRAGMA query_only").fetchone()
        if query_only is not None and int(query_only[0]) != 1:
            raise RuntimeError("recovery priming connection is not query_only")

        def _interrupt_priming_read() -> int:
            try:
                if time.monotonic() >= deadline_monotonic:
                    if state is not None:
                        state["reason"] = "deadline"
                    return 1
                if preempt_callback is not None and preempt_callback():
                    if state is not None:
                        state["reason"] = "monitor_preempted"
                    return 1
            except BaseException:  # noqa: BLE001 - callback failure is preempt.
                if state is not None:
                    state["reason"] = "monitor_preempted"
                logger.warning(
                    "recovery: priming interrupt callback failed; interrupting read",
                    exc_info=True,
                )
                return 1
            return 0

        conn.set_progress_handler(
            _interrupt_priming_read,
            _RECOVERY_PRIMING_PROGRESS_OPCODES,
        )
        yield conn
    finally:
        if conn is not None:
            try:
                conn.set_progress_handler(None, 0)
            except Exception:  # noqa: BLE001 - still attempt rollback/close.
                logger.debug(
                    "recovery: priming progress-handler cleanup failed",
                    exc_info=True,
                )
            try:
                conn.rollback()
            except Exception:  # noqa: BLE001 - still close the read connection.
                logger.debug(
                    "recovery: priming read rollback failed",
                    exc_info=True,
                )
            try:
                conn.close()
            except Exception:  # noqa: BLE001 - cleanup is best effort after read.
                logger.warning(
                    "recovery: priming read connection close failed",
                    exc_info=True,
                )


def _active_venue_command_priming_rows(
    conn: sqlite3.Connection,
    *,
    include_filled: bool = True,
) -> list[dict]:
    if not _table_exists(conn, "venue_commands"):
        return []
    active_states = tuple(sorted(_ACKED_ORDER_STATES | _PARTIAL_REMAINDER_STATES))
    if not include_filled:
        active_states = tuple(state for state in active_states if state != CommandState.FILLED.value)
    placeholders = ",".join("?" for _ in active_states)
    rows = conn.execute(
        f"""
        SELECT command_id, venue_order_id, idempotency_key, intent_kind, state
          FROM venue_commands
         WHERE state IN ({placeholders})
           AND COALESCE(venue_order_id, '') != ''
           AND intent_kind IN ('ENTRY', 'EXIT')
         ORDER BY updated_at, command_id
        """,
        active_states,
    ).fetchall()
    return [_dict_row(row) for row in rows]


def _restart_preflight_unresolved_commands(conn: sqlite3.Connection) -> list[dict]:
    restart_states = {
        CommandState.SUBMITTING.value,
        CommandState.UNKNOWN.value,
        CommandState.SUBMIT_UNKNOWN_SIDE_EFFECT.value,
    }
    rows: list[dict] = []
    for row in find_unresolved_commands(conn):
        state = str(row.get("state") or "")
        if state in restart_states:
            rows.append(row)
            continue
        if state != CommandState.REVIEW_REQUIRED.value:
            continue
        command_id = str(row.get("command_id") or "")
        venue_order_id = str(row.get("venue_order_id") or "")
        events = _command_events(conn, command_id)
        if venue_order_id and (
            _cancel_failed_already_canceled_payload(events) is not None
            or _latest_cancel_unknown_payload(events) is not None
        ):
            rows.append(row)
            continue
        latest_reason = _latest_review_required_payload(
            events
        ).get("reason")
        if latest_reason != "matched_submit_missing_trade_id" or not venue_order_id:
            continue
        trade_facts = conn.execute(
            "WITH " + _canonical_trade_fact_cte() + """
            SELECT state, filled_size, fill_price, source, observed_at
              FROM canonical_trade_fact
             WHERE command_id = ?
               AND venue_order_id = ?
               AND state = 'CONFIRMED'
               AND source IN ('REST', 'WS_USER')
               AND CAST(COALESCE(filled_size, '0') AS REAL) > 0
               AND CAST(COALESCE(fill_price, '0') AS REAL) > 0
             ORDER BY proof_rank DESC, local_sequence DESC
            """,
            (command_id, venue_order_id),
        ).fetchall()
        if len(trade_facts) != 1:
            continue
        trade_fact = _dict_row(trade_facts[0])
        if not _fill_price_respects_limit(
            trade_fact.get("fill_price"),
            row.get("price"),
            side=row.get("side"),
        ):
            continue
        command_size = _decimal_or_none(row.get("size"))
        filled_size = _positive_decimal_or_none(trade_fact.get("filled_size"))
        if command_size is None or filled_size is None:
            continue
        if not _fill_size_completes_limit_order(
            filled_size,
            command_size,
            side=row.get("side"),
        ):
            continue
        rows.append(row)
    return rows


def _capital_blocking_cancel_commands(conn: sqlite3.Connection) -> list[dict]:
    """Return unresolved cancels that can retain venue exposure or collateral."""

    if not (
        _table_exists(conn, "venue_commands")
        and _table_exists(conn, "venue_command_events")
    ):
        return []
    rows: list[dict] = []
    for row in find_unresolved_commands(conn):
        state = str(row.get("state") or "")
        command_id = str(row.get("command_id") or "")
        venue_order_id = str(row.get("venue_order_id") or "")
        if not command_id or not venue_order_id:
            continue
        if state == CommandState.CANCEL_PENDING.value:
            rows.append(row)
            continue
        if state != CommandState.REVIEW_REQUIRED.value:
            continue
        events = _command_events(conn, command_id)
        if (
            _cancel_failed_already_canceled_payload(events) is None
            and _latest_cancel_unknown_payload(events) is None
        ):
            continue
        rows.append(row)
    return rows


def _terminal_filled_entry_projection_blocker_command_ids(
    conn: sqlite3.Connection,
) -> tuple[str, ...]:
    """Return confirmed ENTRY fills canonical position truth has not absorbed."""

    required = {
        "venue_commands",
        "venue_trade_facts",
        "position_current",
        "position_events",
        "execution_fact",
    }
    if not all(_table_exists(conn, table) for table in required):
        return ()
    # SCOPE: one recent terminal FILLED ENTRY command, or a REVIEW_REQUIRED
    # matched submit whose authenticated trade has since become CONFIRMED, with
    # positive fill truth but incomplete command-bound position/execution
    # projection.
    # DRAIN: scheduled command recovery runs the existing filled-entry projection
    # repair under current-capital priority for one hour (sixty normal cadences);
    # older debt remains in background recovery rather than monopolizing current
    # capital I/O. RESET: the exact positive position row (including a later
    # legitimate close/settlement phase), ENTRY_ORDER_FILLED event, and
    # execution_fact all exist for that command.
    rows = conn.execute(
        """
        SELECT cmd.command_id
          FROM venue_commands cmd
         WHERE cmd.intent_kind = 'ENTRY'
           AND cmd.side = 'BUY'
           AND cmd.state IN ('FILLED', 'REVIEW_REQUIRED')
           AND COALESCE(cmd.venue_order_id, '') != ''
           AND EXISTS (
                SELECT 1
                  FROM venue_trade_facts fact
                 WHERE fact.command_id = cmd.command_id
                   AND fact.venue_order_id = cmd.venue_order_id
                   AND fact.state = 'CONFIRMED'
                   AND fact.source IN ('REST', 'WS_USER')
                   AND CAST(COALESCE(fact.filled_size, '0') AS REAL) > 0
                   AND CAST(COALESCE(fact.fill_price, '0') AS REAL) > 0
                   AND datetime(fact.observed_at) >= datetime('now', ?)
           )
           AND (
                NOT EXISTS (
                    SELECT 1
                      FROM position_current pc
                     WHERE pc.position_id = cmd.position_id
                       AND pc.phase IN (
                            'active', 'day0_window', 'pending_exit',
                            'economically_closed', 'settled', 'admin_closed'
                       )
                       AND CAST(COALESCE(pc.shares, '0') AS REAL) > 0
                       AND CAST(COALESCE(pc.cost_basis_usd, '0') AS REAL) > 0
                       AND cmd.token_id IN (
                            COALESCE(pc.token_id, ''),
                            COALESCE(pc.no_token_id, '')
                       )
                )
                OR NOT EXISTS (
                    SELECT 1
                      FROM position_events event
                     WHERE event.position_id = cmd.position_id
                       AND event.event_type = 'ENTRY_ORDER_FILLED'
                       AND (
                            event.command_id = cmd.command_id
                            OR lower(COALESCE(event.order_id, '')) =
                               lower(cmd.venue_order_id)
                       )
                )
                OR NOT EXISTS (
                    SELECT 1
                      FROM execution_fact execution
                     WHERE execution.position_id = cmd.position_id
                       AND execution.command_id = cmd.command_id
                       AND execution.order_role = 'entry'
                       AND execution.filled_at IS NOT NULL
                       AND execution.shares > 0
                )
           )
        """,
        (f"-{_TERMINAL_FILL_PROJECTION_PRIORITY_SECONDS} seconds",),
    ).fetchall()
    return tuple(str(row[0]) for row in rows if str(row[0] or "").strip())


def _terminal_filled_entry_projection_blocker_count(
    conn: sqlite3.Connection,
) -> int:
    """Count confirmed ENTRY fills that canonical position truth has not absorbed."""

    return len(_terminal_filled_entry_projection_blocker_command_ids(conn))


def _terminal_filled_exit_projection_blocker_command_ids(
    conn: sqlite3.Connection,
) -> tuple[str, ...]:
    """Return recent terminal EXIT commands not yet booked as released capital."""

    required = {
        "venue_commands",
        "venue_trade_facts",
        "position_current",
        "position_events",
        "execution_fact",
    }
    if not all(_table_exists(conn, table) for table in required):
        return ()
    # SCOPE: one recent terminal FILLED full EXIT/SELL command with authenticated
    # positive fill truth but incomplete command-bound economic-close truth. A
    # completed partial capital reduction leaves a smaller live position and is
    # not an economic-close projection obligation.
    # DRAIN: scheduled command recovery receives current-capital priority and
    # runs exit_pending_projections. RESET: economically_closed position truth,
    # EXIT_ORDER_FILLED, and a positive exit execution_fact all bind the command.
    rows = conn.execute(
        """
        SELECT cmd.command_id
          FROM venue_commands cmd
         WHERE cmd.intent_kind = 'EXIT'
           AND UPPER(COALESCE(cmd.side, '')) = 'SELL'
           AND cmd.state = 'FILLED'
           AND COALESCE(cmd.venue_order_id, '') != ''
           AND EXISTS (
                SELECT 1
                  FROM venue_trade_facts fact
                 WHERE fact.command_id = cmd.command_id
                   AND fact.venue_order_id = cmd.venue_order_id
                   AND fact.state IN ('MATCHED', 'MINED', 'CONFIRMED')
                   AND fact.source IN ('REST', 'WS_USER')
                   AND CAST(COALESCE(fact.filled_size, '0') AS REAL) > 0
                   AND CAST(COALESCE(fact.fill_price, '0') AS REAL) > 0
                   AND datetime(fact.observed_at) >= datetime('now', ?)
           )
           AND (
                NOT EXISTS (
                    SELECT 1
                      FROM position_current known
                     WHERE known.position_id = cmd.position_id
                )
                OR EXISTS (
                    SELECT 1
                      FROM position_current projection
                     WHERE projection.position_id = cmd.position_id
                       AND (
                            projection.phase = 'economically_closed'
                            OR (
                                projection.phase IN (
                                    'active', 'day0_window', 'pending_exit'
                                )
                                AND (
                                    (
                                        CAST(cmd.size AS REAL) =
                                            CAST(projection.shares AS REAL)
                                        AND CAST(cmd.size AS REAL) =
                                            CAST(projection.chain_shares AS REAL)
                                    )
                                    OR (
                                        LOWER(COALESCE(
                                            projection.chain_state, ''
                                        )) = 'chain_confirmed_zero'
                                        AND CAST(COALESCE(
                                            projection.chain_shares, '0'
                                        ) AS REAL) = 0
                                    )
                                )
                            )
                       )
                )
           )
           AND (
                NOT EXISTS (
                    SELECT 1
                      FROM position_current pc
                     WHERE pc.position_id = cmd.position_id
                       AND pc.phase = 'economically_closed'
                       AND pc.exit_price > 0
                       AND pc.realized_pnl_usd IS NOT NULL
                )
                OR NOT EXISTS (
                    SELECT 1
                      FROM position_events event
                     WHERE event.position_id = cmd.position_id
                       AND event.event_type = 'EXIT_ORDER_FILLED'
                       AND (
                            event.command_id = cmd.command_id
                            OR lower(COALESCE(event.order_id, '')) =
                               lower(cmd.venue_order_id)
                       )
                )
                OR NOT EXISTS (
                    SELECT 1
                      FROM execution_fact execution
                     WHERE execution.position_id = cmd.position_id
                       AND execution.command_id = cmd.command_id
                       AND execution.order_role = 'exit'
                       AND execution.filled_at IS NOT NULL
                       AND execution.shares > 0
                )
           )
        """,
        (f"-{_TERMINAL_FILL_PROJECTION_PRIORITY_SECONDS} seconds",),
    ).fetchall()
    return tuple(str(row[0]) for row in rows if str(row[0] or "").strip())


def _terminal_filled_exit_projection_blocker_count(
    conn: sqlite3.Connection,
) -> int:
    """Count recent terminal EXIT fills not yet booked as released capital."""

    return len(_terminal_filled_exit_projection_blocker_command_ids(conn))


def capital_blocking_command_scope(
    conn: sqlite3.Connection,
) -> CapitalBlockingCommandScope:
    """Return the scope lattice for exact current-capital recovery debt.

    Projection debt remains global because canonical wealth has not absorbed a
    confirmed fill. Venue-command debt may remain isolated when every blocker
    names one market; the caller applies the allocator's configured systemic
    market threshold.
    """

    command_rows = list(_capital_blocking_cancel_commands(conn))
    if _table_exists(conn, "venue_commands"):
        command_rows.extend(
            _dict_row(row)
            for row in conn.execute(
                """
                SELECT command_id, market_id
                  FROM venue_commands
                 WHERE state = ?
                   AND intent_kind IN ('ENTRY', 'EXIT')
                   AND COALESCE(venue_order_id, '') != ''
                """,
                (CommandState.SUBMITTING.value,),
            ).fetchall()
        )
    if all(
        _table_exists(conn, table)
        for table in ("entry_exposure_obligations", "venue_commands")
    ):
        # SCOPE: only OPEN entry obligations whose command already carries a
        # terminal no-fill state. DRAIN: the DB-only terminal-obligation pass
        # proves its no-fill event/facts and resolves the exact obligation.
        # RESET: RESOLVED removes the row from this selector immediately.
        # Without this selector, the scheduler classified the command itself as
        # terminal, yielded forever to held monitoring, and left its cash bound
        # deducted from every subsequent global auction.
        terminal_no_fill_states = tuple(
            sorted(_TERMINAL_ENTRY_NO_FILL_COMMAND_STATES)
        )
        existing_command_ids = {
            str(row.get("command_id") or "").strip()
            for row in command_rows
        }
        command_rows.extend(
            row
            for raw in conn.execute(
                f"""
                SELECT command.command_id, command.market_id
                  FROM entry_exposure_obligations obligation
                  JOIN venue_commands command
                    ON command.command_id = obligation.command_id
                 WHERE obligation.status = 'OPEN'
                   AND command.intent_kind = 'ENTRY'
                   AND command.state IN (
                       {','.join('?' for _ in terminal_no_fill_states)}
                   )
                 ORDER BY obligation.created_at, obligation.command_id
                """,
                terminal_no_fill_states,
            ).fetchall()
            if (
                (row := _dict_row(raw))["command_id"]
                not in existing_command_ids
            )
        )
    authenticated_entry_projection_count = 0
    authenticated_nonterminal_states = (
        CommandState.SUBMITTING.value,
        CommandState.POST_ACKED.value,
        CommandState.ACKED.value,
        CommandState.PARTIAL.value,
        CommandState.CANCEL_PENDING.value,
        CommandState.REVIEW_REQUIRED.value,
    )
    for candidate in _bounded_authenticated_entry_trade_fact_candidates(
        conn,
        states=authenticated_nonterminal_states,
    ):
        facts = _confirmed_entry_trade_fact_summary(
            conn,
            command_id=str(candidate.get("command_id") or ""),
            venue_order_id=str(candidate.get("venue_order_id") or ""),
        )
        filled_size = _positive_decimal_or_none(facts.get("filled_size"))
        fill_price = _positive_decimal_or_none(facts.get("fill_price"))
        if filled_size is None or fill_price is None:
            continue
        if not _authenticated_entry_fill_projection_complete(
            conn,
            command_id=str(candidate.get("command_id") or ""),
            position_id=str(candidate.get("position_id") or ""),
            venue_order_id=str(candidate.get("venue_order_id") or ""),
            filled_size=filled_size,
            fill_price=fill_price,
        ):
            authenticated_entry_projection_count += 1
    projection_count = (
        _terminal_filled_entry_projection_blocker_count(conn)
        + _terminal_filled_exit_projection_blocker_count(conn)
        + authenticated_entry_projection_count
        + len(
            _exchange_reconcile.persisted_terminal_late_entry_fill_command_ids(
                conn
            )
        )
    )
    scoped_markets = tuple(
        sorted(
            {
                str(row.get("market_id") or "").strip()
                for row in command_rows
                if str(row.get("market_id") or "").strip()
            }
        )
    )
    unscopeable_count = sum(
        1 for row in command_rows if not str(row.get("market_id") or "").strip()
    )
    return CapitalBlockingCommandScope(
        total_count=len(command_rows) + projection_count,
        scoped_markets=scoped_markets,
        unscopeable_count=unscopeable_count,
        projection_count=projection_count,
    )


def capital_blocking_command_count(conn: sqlite3.Connection) -> int:
    """Return exact unresolved venue side effects that freeze current capital."""

    return capital_blocking_command_scope(conn).total_count


def _identity_bound_submitting_candidates(
    conn: sqlite3.Connection,
    *,
    limit: int = _LIVE_TICK_IDENTITY_BOUND_MAX_CANDIDATES,
    rotation_slot: int | None = None,
) -> tuple[list[dict], int]:
    """Return a bounded, crash-stable rotating slice of known-order submits.

    This is intentionally narrower than account-wide recovery.  A command that
    already names a venue order can obtain positive truth from that exact point
    read; a missing or failed point read is not absence proof and stays out of
    this lane.  The full account snapshot remains the sole authority for
    account-wide negative/absence conclusions.  Both a submit awaiting its
    first ACK and a submit whose ACK side effect became ambiguous retain this
    positive point-read authority.  Rotation derives from the wall-clock tick
    rather than process memory, so a restart cannot reset the cursor and
    permanently starve rows beyond the first batch.
    """
    if not _table_exists(conn, "venue_commands"):
        return [], 0
    candidate_limit = max(1, int(limit))
    total = int(
        conn.execute(
            """
            SELECT COUNT(*)
              FROM venue_commands
             WHERE state IN (?, ?)
               AND intent_kind IN ('ENTRY', 'EXIT')
               AND COALESCE(venue_order_id, '') != ''
            """,
            _IDENTITY_BOUND_INFLIGHT_STATES,
        ).fetchone()[0]
        or 0
    )
    if total <= 0:
        return [], 0
    slot = (
        _identity_bound_rotation_slot()
        if rotation_slot is None
        else max(0, int(rotation_slot))
    )
    def _intent_slice(
        intent_kind: str,
        slice_limit: int,
    ) -> tuple[list[dict], int]:
        intent_total = int(
            conn.execute(
                """
                SELECT COUNT(*)
                  FROM venue_commands
                 WHERE state IN (?, ?)
                   AND intent_kind = ?
                   AND COALESCE(venue_order_id, '') != ''
                """,
                (*_IDENTITY_BOUND_INFLIGHT_STATES, intent_kind),
            ).fetchone()[0]
            or 0
        )
        if intent_total <= 0 or slice_limit <= 0:
            return [], intent_total
        offset = (slot * slice_limit) % intent_total
        rows = conn.execute(
            """
            SELECT *
              FROM venue_commands
             WHERE state IN (?, ?)
               AND intent_kind = ?
               AND COALESCE(venue_order_id, '') != ''
             ORDER BY updated_at, command_id
             LIMIT ? OFFSET ?
            """,
            (
                *_IDENTITY_BOUND_INFLIGHT_STATES,
                intent_kind,
                slice_limit,
                offset,
            ),
        ).fetchall()
        selected = [_dict_row(row) for row in rows]
        if len(selected) < min(slice_limit, intent_total):
            wrap_rows = conn.execute(
                """
                SELECT *
                  FROM venue_commands
                 WHERE state IN (?, ?)
                   AND intent_kind = ?
                   AND COALESCE(venue_order_id, '') != ''
                 ORDER BY updated_at, command_id
                 LIMIT ?
                """,
                (
                    *_IDENTITY_BOUND_INFLIGHT_STATES,
                    intent_kind,
                    min(slice_limit, intent_total) - len(selected),
                ),
            ).fetchall()
            selected.extend(_dict_row(row) for row in wrap_rows)
        return selected, intent_total

    candidates, _exit_total = _intent_slice("EXIT", candidate_limit)
    remaining = candidate_limit - len(candidates)
    if remaining > 0:
        entries, _entry_total = _intent_slice("ENTRY", remaining)
        candidates.extend(entries)
    return candidates, max(0, total - len(candidates))


def _identity_bound_current_commands(
    conn: sqlite3.Connection,
    command_ids: set[str],
) -> dict[str, dict]:
    """Reload exactly the selected commands without re-running rotation."""

    ordered_ids = sorted(command_id for command_id in command_ids if command_id)
    if not ordered_ids:
        return {}
    placeholders = ",".join("?" for _ in ordered_ids)
    rows = conn.execute(
        f"""
        SELECT *
          FROM venue_commands
         WHERE command_id IN ({placeholders})
           AND state IN (?, ?)
           AND intent_kind IN ('ENTRY', 'EXIT')
           AND COALESCE(venue_order_id, '') != ''
        """,
        (*ordered_ids, *_IDENTITY_BOUND_INFLIGHT_STATES),
    ).fetchall()
    return {
        str(row.get("command_id") or ""): row
        for row in (_dict_row(raw) for raw in rows)
    }


def _identity_bound_positive_point_order(
    point_order: dict | None,
    *,
    venue_order_id: str,
) -> bool:
    """Accept only a positive point response that echoes the bound venue id."""
    if not isinstance(point_order, dict):
        return False
    observed_order_id = str(_extract_order_id(point_order) or "")
    if not observed_order_id or observed_order_id != venue_order_id:
        return False
    return _order_status(point_order) not in {"", "UNKNOWN", "NOT_FOUND"}


def _reconcile_identity_bound_submitting_commands(
    conn: sqlite3.Connection,
    *,
    command_ids: set[str],
    point_orders: Mapping[str, dict],
) -> dict:
    """Persist positive exact-order truth without consulting account absence data."""
    summary = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
    current = _identity_bound_current_commands(conn, command_ids)
    point_client = SimpleNamespace(
        get_order=lambda venue_order_id: point_orders.get(str(venue_order_id)),
        authenticated_point_reads_are_complete=True,
    )
    for command_id in sorted(command_ids):
        row = current.get(command_id)
        if row is None:
            continue
        summary["scanned"] += 1
        venue_order_id = str(row.get("venue_order_id") or "")
        point_order = point_orders.get(venue_order_id)
        if not _identity_bound_positive_point_order(
            point_order,
            venue_order_id=venue_order_id,
        ):
            summary["stayed"] += 1
            continue
        try:
            outcome = _reconcile_row(
                conn,
                VenueCommand.from_row(row),
                point_client,
            )
            if outcome == "advanced":
                summary["advanced"] += 1
            elif outcome == "stayed":
                summary["stayed"] += 1
                continue
            else:
                summary["errors"] += 1
                continue
            venue_status = _order_status(point_order)
            explicit_matched_size = _explicit_point_order_matched_size(point_order)
            matched = _positive_decimal_or_none(explicit_matched_size)
            requested = _positive_decimal_or_none(row.get("size"))
            if not (
                _venue_status_can_carry_positive_match(venue_status)
                and matched is not None
                and requested is not None
                and matched <= requested
            ):
                continue
            matched_size = _decimal_text(matched)
            observed_at = _now_iso()
            event_type = _matched_event_type(
                row,
                matched_size,
                venue_status=venue_status,
            )
            remaining_size = _matched_remaining_size(
                row,
                matched_size,
                venue_status=venue_status,
            )
            payload = {
                "reason": "identity_bound_submitting_point_order",
                "command_id": command_id,
                "venue_order_id": venue_order_id,
                "venue_status": venue_status,
                "point_order": point_order,
                "matched_size": matched_size,
                "remaining_size": remaining_size,
                "source_proof": {
                    "source_commit": "runtime",
                    "source_function": "command_recovery._capital_recovery_fast_pass",
                    "source_reason": "identity_bound_positive_point_order",
                },
            }
            append_order_fact(
                conn,
                venue_order_id=venue_order_id,
                command_id=command_id,
                state=_matched_order_fact_state(
                    event_type=event_type,
                    venue_status=venue_status,
                    remaining_size=remaining_size,
                ),
                remaining_size=remaining_size,
                matched_size=matched_size,
                source="REST",
                observed_at=observed_at,
                venue_timestamp=observed_at,
                raw_payload_hash=_payload_hash(payload),
                raw_payload_json=payload,
            )
            fill_summary = reconcile_matched_order_facts(
                conn,
                point_client,
                command_id=command_id,
            )
            summary["advanced"] += fill_summary["advanced"]
            summary["stayed"] += fill_summary["stayed"]
            summary["errors"] += fill_summary["errors"]
        except Exception as exc:  # noqa: BLE001 - one command must not block peers.
            logger.error(
                "recovery: identity-bound submit command %s failed: %s",
                command_id,
                exc,
            )
            summary["errors"] += 1
    return summary


def _collect_recovery_priming_keys(conn: sqlite3.Connection, *, scope: str = "full") -> dict:
    """SNAPSHOT phase helper: gather every venue-read key the apply passes will need.

    Runs only read queries (the per-pass candidate selects + the in-flight scan)
    on a short-lived connection and returns the venue identities needed by this
    invocation. High-cadence scopes collect every current candidate. The full
    historical sweep collects one crash-stable quantum per background class so
    NETWORK work is bounded to the same rows APPLY can advance this invocation.
    Under-collection raises a located ``SnapshotMissError`` at APPLY.
    """
    order_ids: set[str] = set()
    idem_keys: set[str] = set()
    condition_ids: set[str] = set()
    active_command_ids: set[str] = set()
    active_quantum_remaining = False
    matched_command_ids: set[str] = set()
    matched_quantum_remaining = False

    def _harvest(rows) -> None:
        for row in rows or []:
            mapping = row if isinstance(row, dict) else _dict_row(row)
            for col in ("venue_order_id", "order_fact_venue_order_id"):
                val = str(mapping.get(col) or "").strip()
                if val:
                    order_ids.add(val)
            idem = str(mapping.get("idempotency_key") or "").strip()
            if idem:
                idem_keys.add(idem)
            for col in ("env_condition_id", "snapshot_condition_id"):
                cid = str(mapping.get(col) or "").strip()
                if cid:
                    condition_ids.add(cid)

    full_priority_rows: list[dict] = []

    # The in-flight scan (per-row _reconcile_row venue lookups).
    try:
        if scope == "restart_preflight":
            _harvest(_restart_preflight_unresolved_commands(conn))
        elif scope == "full":
            full_priority_rows = _full_quantum_candidates(conn)
            _harvest(full_priority_rows[:1])
        else:
            _harvest(find_unresolved_commands(conn))
    except Exception:  # noqa: BLE001 — a missing table just means no candidates
        logger.debug("recovery: priming scan find_unresolved_commands failed", exc_info=True)
    if scope == "restart_preflight":
        try:
            _harvest(_terminal_point_order_candidates(conn))
        except Exception:  # noqa: BLE001
            logger.debug(
                "recovery: priming restart terminal point orders failed",
                exc_info=True,
            )
        try:
            _harvest(
                _partial_remainder_candidates(
                    conn,
                    terminal_exit_only=True,
                )
            )
        except Exception:  # noqa: BLE001
            logger.debug(
                "recovery: priming terminal EXIT partial remainders failed",
                exc_info=True,
            )
        return {
            "order_ids": order_ids,
            "idempotency_keys": idem_keys,
            "condition_ids": condition_ids,
        }
    if full_priority_rows:
        priority = full_priority_rows[0]
        priority_state = str(priority.get("state") or "")
        priority_order_id = str(priority.get("venue_order_id") or "").strip()
        if priority_order_id and priority_state in {
            CommandState.UNKNOWN.value,
            CommandState.SUBMIT_UNKNOWN_SIDE_EFFECT.value,
        }:
            # One exact unresolved side effect outranks every historical point
            # read. Returning here prevents unrelated active/partial debt from
            # consuming the shared account+order deadline first.
            return {
                "order_ids": order_ids,
                "idempotency_keys": idem_keys,
                "condition_ids": condition_ids,
                "full_priority_inflight_command_id": str(
                    priority.get("command_id") or ""
                ),
                "full_priority_inflight_quantum_remaining": (
                    len(full_priority_rows) > 1
                ),
            }
    if scope in {"live_tick", "boot_fast"}:
        try:
            _harvest(
                _active_venue_command_priming_rows(
                    conn,
                    include_filled=scope != "live_tick",
                )
            )
        except Exception:  # noqa: BLE001 — a missing table just means no candidates
            logger.debug(
                "recovery: priming candidate _active_venue_command_priming_rows failed",
                exc_info=True,
            )
    elif scope == "full":
        # Historical FILLED commands never belong in one account-wide point-read
        # burst. Their durable quantum rotates every minute; current unresolved,
        # partial, and projection candidates remain collected separately below.
        try:
            active_rows = _active_venue_command_priming_rows(
                conn,
                include_filled=True,
            )
            active_batches = _full_background_recovery_command_id_batches(
                [str(row.get("command_id") or "") for row in active_rows]
            )
            if active_batches:
                active_command_ids.update(active_batches[0])
                _harvest(
                    row
                    for row in active_rows
                    if str(row.get("command_id") or "") in active_command_ids
                )
                active_quantum_remaining = len(active_batches) > 1
        except Exception:  # noqa: BLE001 — a missing table just means no candidates
            logger.debug(
                "recovery: priming candidate _active_venue_command_priming_rows failed",
                exc_info=True,
            )
    if scope in {"live_tick", "boot_fast"}:
        for candidate_fn in (
            _local_orphan_no_fill_candidates,
            _terminal_point_order_candidates,
            _latest_unprojected_filled_entry_candidates,
        ):
            try:
                _harvest(candidate_fn(conn))
            except Exception:  # noqa: BLE001
                logger.debug("recovery: priming candidate %s failed", candidate_fn.__name__, exc_info=True)
        try:
            _harvest(
                _latest_matched_order_fact_candidates(
                    conn,
                    skip_stale_terminal_zero=True,
                    skip_projected_hard_terminal=scope == "live_tick",
                )
            )
        except Exception:  # noqa: BLE001
            logger.debug(
                "recovery: priming candidate _latest_matched_order_fact_candidates failed",
                exc_info=True,
            )
        if scope == "live_tick":
            try:
                _harvest(
                    _partial_remainder_candidates(
                        conn,
                        updated_before=None,
                        live_tick_scope=True,
                    )
                )
            except Exception:  # noqa: BLE001
                logger.debug("recovery: priming candidate _partial_remainder_candidates failed", exc_info=True)
        return {
            "order_ids": order_ids,
            "idempotency_keys": idem_keys,
            "condition_ids": condition_ids,
        }

    # Each client-taking pass's candidate query.
    for candidate_fn in (
        _local_orphan_no_fill_candidates,
        _terminal_point_order_candidates,
        _latest_unprojected_live_entry_candidates,
        _latest_unprojected_filled_entry_candidates,
    ):
        try:
            _harvest(candidate_fn(conn))
        except Exception:  # noqa: BLE001
            logger.debug("recovery: priming candidate %s failed", candidate_fn.__name__, exc_info=True)
    try:
        matched_rows = _latest_matched_order_fact_candidates(conn)
        # Match the existing one-command APPLY quantum before any venue I/O.
        # The selected ids are carried in ``priming`` so a minute-boundary
        # rotation cannot make APPLY ask for an identity NETWORK did not capture.
        matched_batches = _full_background_recovery_command_id_batches(
            [str(row.get("command_id") or "") for row in matched_rows]
        )
        if matched_batches:
            matched_command_ids.update(matched_batches[0])
            _harvest(
                row
                for row in matched_rows
                if str(row.get("command_id") or "") in matched_command_ids
            )
            matched_quantum_remaining = len(matched_batches) > 1
    except Exception:  # noqa: BLE001
        logger.debug(
            "recovery: priming candidate _latest_matched_order_fact_candidates failed",
            exc_info=True,
        )
    try:
        _harvest(_partial_remainder_candidates(conn, updated_before=None))
    except Exception:  # noqa: BLE001
        logger.debug("recovery: priming candidate _partial_remainder_candidates failed", exc_info=True)
    try:
        _harvest(_partial_remainder_candidates(conn, terminal_exit_only=True))
    except Exception:  # noqa: BLE001
        logger.debug(
            "recovery: priming terminal EXIT partial remainder candidates failed",
            exc_info=True,
        )

    return {
        "order_ids": order_ids,
        "idempotency_keys": idem_keys,
        "condition_ids": condition_ids,
        "active_command_ids": active_command_ids,
        "active_quantum_remaining": active_quantum_remaining,
        "matched_command_ids": matched_command_ids,
        "matched_quantum_remaining": matched_quantum_remaining,
    }


def _restart_no_venue_exit_retry_candidates(conn: sqlite3.Connection) -> list[dict]:
    if not (
        _table_exists(conn, "venue_commands")
        and _table_exists(conn, "venue_command_events")
        and _table_exists(conn, "venue_order_facts")
        and _table_exists(conn, "venue_trade_facts")
        and _table_exists(conn, "position_current")
    ):
        return []
    pc_cols = _table_columns(conn, "position_current")
    pc_select = ", ".join(f"pc.{col} AS pc_{col}" for col in pc_cols)
    rows = conn.execute(
        f"""
        WITH latest_rejected_exit AS (
            SELECT cmd.command_id,
                   cmd.position_id,
                   cmd.state AS command_state,
                   cmd.venue_order_id,
                   cmd.updated_at AS command_updated_at,
                   cmd.price AS command_price,
                   cmd.size AS command_size,
                   evt.occurred_at AS rejected_at,
                   evt.payload_json AS rejected_payload_json,
                   ROW_NUMBER() OVER (
                       PARTITION BY cmd.position_id
                       ORDER BY datetime(evt.occurred_at) DESC, evt.event_id DESC
                   ) AS rn
              FROM venue_commands cmd
              JOIN venue_command_events evt
                ON evt.command_id = cmd.command_id
               AND evt.event_type = 'SUBMIT_REJECTED'
             WHERE cmd.intent_kind = 'EXIT'
               AND cmd.state IN ('REJECTED', 'SUBMIT_REJECTED')
               AND (
                    COALESCE(cmd.venue_order_id, '') = ''
                    OR (
                        COALESCE(cmd.venue_order_id, '') != ''
                        AND json_extract(
                            evt.payload_json, '$.reason'
                        ) = 'safe_replay_permitted_no_order_found'
                        AND json_extract(
                            evt.payload_json, '$.safe_replay_permitted'
                        ) = 1
                        AND NOT EXISTS (
                            SELECT 1
                              FROM venue_order_facts order_fact
                             WHERE order_fact.command_id = cmd.command_id
                                OR order_fact.venue_order_id = cmd.venue_order_id
                        )
                    )
               )
               AND NOT EXISTS (
                   SELECT 1
                     FROM venue_trade_facts tf
                    WHERE tf.command_id = cmd.command_id
                      AND tf.state IN ('MATCHED', 'MINED', 'CONFIRMED')
                      AND CAST(COALESCE(tf.filled_size, '0') AS REAL) > 0
               )
        )
        SELECT rejected.command_id,
               rejected.command_state,
               rejected.venue_order_id,
               rejected.command_updated_at,
               rejected.command_price,
               rejected.command_size,
               rejected.rejected_at,
               rejected.rejected_payload_json,
               {pc_select}
          FROM latest_rejected_exit rejected
          JOIN position_current pc
            ON pc.position_id = rejected.position_id
         WHERE rejected.rn = 1
           AND pc.phase = 'pending_exit'
         ORDER BY datetime(rejected.rejected_at), rejected.command_id
        """
    ).fetchall()
    return [_dict_row(row) for row in rows]


def _release_no_venue_exit_to_redecision(
    conn: sqlite3.Connection,
    candidate: Mapping[str, object],
) -> bool:
    """Release one proven no-side-effect EXIT from restart-blocking state.

    SCOPE: one position selected by the exact command/fact proof above.
    DRAIN: restart preflight projects the release before evaluating pending exits.
    RESET: the position leaves ``pending_exit``; a future exit requires a new decision.
    """

    current = {
        key.removeprefix("pc_"): value
        for key, value in candidate.items()
        if key.startswith("pc_")
    }
    position_id = str(current.get("position_id") or current.get("trade_id") or "")
    command_id = str(candidate.get("command_id") or "")
    if not position_id or not command_id:
        return False

    occurred_at = _now_iso()
    phase_after = _phase_after_terminal_exit_no_fill(
        {
            "position_city": current.get("city"),
            "position_target_date": current.get("target_date"),
        },
        observed_at=occurred_at,
    )
    projection = dict(current)
    projection.update(
        {
            "phase": phase_after,
            "order_id": None,
            "order_status": "filled",
            "exit_reason": "EXIT_SUBMIT_NO_VENUE_SIDE_EFFECT_RELEASED",
            "exit_retry_count": 0,
            "next_exit_retry_at": None,
            "updated_at": occurred_at,
        }
    )
    event_key = f"{position_id}:exit_submit_absent_released:{command_id}"
    from src.state.ledger import append_many_and_project
    from src.state.projection import upsert_position_current

    existing = conn.execute(
        "SELECT 1 FROM position_events WHERE idempotency_key = ? LIMIT 1",
        (event_key,),
    ).fetchone()
    if existing is not None:
        upsert_position_current(conn, projection)
        return True

    event = {
        "event_id": event_key,
        "position_id": position_id,
        "event_version": 1,
        "sequence_no": _latest_position_sequence(conn, position_id) + 1,
        "event_type": "EXIT_RETRY_RELEASED",
        "occurred_at": occurred_at,
        "phase_before": "pending_exit",
        "phase_after": phase_after,
        "strategy_key": current.get("strategy_key"),
        "decision_id": current.get("decision_id"),
        "snapshot_id": current.get("decision_snapshot_id"),
        "order_id": candidate.get("venue_order_id"),
        "command_id": command_id,
        "caused_by": f"venue_command:{command_id}",
        "idempotency_key": event_key,
        "venue_status": candidate.get("command_state"),
        "source_module": "src.execution.command_recovery",
        "env": _latest_position_env(conn, position_id),
        "payload_json": json.dumps(
            {
                "reason": "exit_submit_absence_returned_to_redecision",
                "proof_class": "submit_rejected_plus_order_and_positive_trade_absence",
                "command_state": candidate.get("command_state"),
                "venue_order_id": candidate.get("venue_order_id"),
                "rejected_at": candidate.get("rejected_at"),
                "phase_after": phase_after,
            },
            sort_keys=True,
            default=str,
        ),
    }
    append_many_and_project(conn, [event], projection)
    return True


def reconcile_restart_no_venue_exit_retry_projections(conn: sqlite3.Connection) -> dict:
    """Return proven no-side-effect EXIT submit failures to redecision."""

    summary = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
    for candidate in _restart_no_venue_exit_retry_candidates(conn):
        summary["scanned"] += 1
        command_id = str(candidate.get("command_id") or "")
        try:
            released = _release_no_venue_exit_to_redecision(conn, candidate)
            position_id = str(candidate.get("pc_position_id") or "")
            current = conn.execute(
                """
                SELECT phase, exit_retry_count, next_exit_retry_at
                  FROM position_current
                 WHERE position_id = ?
                """,
                (position_id,),
            ).fetchone()
            if (
                not released
                or current is None
                or str(current["phase"] or "") == "pending_exit"
                or int(current["exit_retry_count"] or 0) != 0
                or str(current["next_exit_retry_at"] or "")
            ):
                summary["stayed"] += 1
                continue
            summary["advanced"] += 1
        except Exception as exc:  # noqa: BLE001
            logger.error(
                "recovery: restart no-venue EXIT retry projection failed for command %s: %s",
                command_id,
                exc,
            )
            summary["errors"] += 1
    return summary


def _full_quantum_candidate_priority(row: Mapping[str, object]) -> int:
    """Rank unresolved commands by unresolved venue-side-effect risk."""

    state = str(row.get("state") or "")
    venue_order_id = str(row.get("venue_order_id") or "").strip()
    if state == CommandState.SUBMITTING.value and not venue_order_id:
        return 0
    if state in {
        CommandState.UNKNOWN.value,
        CommandState.SUBMIT_UNKNOWN_SIDE_EFFECT.value,
    }:
        return 1
    if state == CommandState.CANCEL_PENDING.value:
        return 2
    if state == CommandState.SUBMITTING.value:
        return 3
    if state in {
        CommandState.POST_ACKED.value,
        CommandState.ACKED.value,
        CommandState.PARTIAL.value,
    }:
        return 4
    return 5


def _full_quantum_candidates(
    conn: sqlite3.Connection,
    *,
    rotation_slot: int | None = None,
) -> list[dict]:
    """Return risk-prioritized, crash-stable, starvation-free full candidates.

    A full sweep applies only its first row.  Stable oldest-first order therefore
    lets one unresolvable historical REVIEW_REQUIRED row monopolize every run.
    Ambiguous submit/cancel side effects outrank known resting exposure, while a
    wall-clock rotation within each risk class guarantees that a repeatedly
    stayed row cannot permanently hide its peers.
    """

    rows = find_unresolved_commands(conn)
    slot = (
        _full_background_recovery_quantum_slot()
        if rotation_slot is None
        else max(0, int(rotation_slot))
    )
    buckets: dict[int, list[dict]] = {}
    for row in rows:
        buckets.setdefault(_full_quantum_candidate_priority(row), []).append(row)
    ordered: list[dict] = []
    for priority in sorted(buckets):
        bucket = sorted(
            buckets[priority],
            key=lambda row: (
                str(row.get("updated_at") or ""),
                str(row.get("command_id") or ""),
            ),
        )
        offset = slot % len(bucket)
        ordered.extend(bucket[offset:] + bucket[:offset])
    return ordered


def _reconcile_passes_short_conn(
    client,
    summary: dict,
    started_at: str,
    *,
    scope: str = "full",
    deadline_monotonic: float | None = None,
) -> None:
    """Scheduled-job lane: per-pass short connections, no connection across network.

    Three structural phases (``src.execution.venue_sync_contract``):

      1. SNAPSHOT  — one short read connection collects every venue-read key the
         client-taking passes will need (candidate order ids, idempotency keys,
         condition ids), then closes.
      2. NETWORK   — with NO connection in scope, capture the venue read surface
         (open orders, trades, per-order point reads) into an immutable
         ``VenueReadSnapshot``. This is where ALL blocking venue REST I/O happens.
      3. APPLY     — every pass runs on its OWN short-lived connection inside one
         bounded ``BEGIN IMMEDIATE ... COMMIT``. Client-taking passes receive the
         venue SNAPSHOT (zero live network), so the write lock is held only for
         that pass's writes and released the instant the pass returns.

    Full-sweep inflight command recovery is one stable row per invocation; the
    specialized debt passes below remain part of the full lane. Each pass body
    is the SAME function the legacy lane calls — reconciliation grammar,
    REVIEW_REQUIRED handoffs, INV-31 invariants and savepoint discipline are
    byte-for-byte unchanged. Only the connection topology differs.
    """
    from src.execution.venue_sync_contract import (
        assert_no_open_connection,
        capture_venue_read_snapshot,
        default_trade_conn_factory,
        default_trade_read_conn_factory,
        open_tracked,
        run_db_only_pass,
        run_three_phase,
    )

    conn_factory = default_trade_conn_factory
    capital_conn_factory = getattr(
        conn_factory,
        "trade_only_factory",
        conn_factory,
    )
    read_conn_factory = (
        default_trade_read_conn_factory
        if getattr(conn_factory, "requires_writer_flocks", False)
        else conn_factory
    )
    scheduler_deadline = deadline_monotonic
    if scheduler_deadline is None and scope in {"live_tick", "full"}:
        scheduler_deadline = time.monotonic() + scheduled_recovery_budget_seconds()

    live_tick_deadline = None
    full_deadline = None
    if scope == "live_tick":
        raw_budget = os.environ.get(
            "ZEUS_LIVE_RECOVERY_DB_BUDGET_SECONDS",
            str(_LIVE_TICK_DB_BUDGET_SECONDS),
        )
        try:
            live_tick_budget = max(0.0, float(raw_budget))
        except (TypeError, ValueError):
            logger.warning(
                "recovery: invalid ZEUS_LIVE_RECOVERY_DB_BUDGET_SECONDS=%r; using %.3f",
                raw_budget,
                _LIVE_TICK_DB_BUDGET_SECONDS,
            )
            live_tick_budget = _LIVE_TICK_DB_BUDGET_SECONDS
        summary["live_tick_db_budget_seconds"] = live_tick_budget
        live_tick_deadline = time.monotonic() + live_tick_budget
        if scheduler_deadline is not None:
            live_tick_deadline = min(live_tick_deadline, scheduler_deadline)
    elif scope == "full":
        full_budget = _full_sweep_budget_seconds()
        summary["full_sweep_budget_seconds"] = full_budget
        full_deadline = scheduler_deadline or (time.monotonic() + full_budget)
    apply_deadline = (
        live_tick_deadline
        or full_deadline
        or (scheduler_deadline if scope == "restart_preflight" else None)
    )
    conn_factory = _recovery_priority_conn_factory(
        conn_factory,
        scope=scope,
        deadline_monotonic=apply_deadline,
    )
    apply_conn_factory = _recovery_apply_conn_factory(
        conn_factory,
        scope=scope,
        deadline_monotonic=apply_deadline,
    )
    read_conn_factory = _recovery_read_conn_factory(
        read_conn_factory,
        # live_tick priority readers own their separate sub-deadlines; applying
        # the tiny cumulative write budget here would suppress exact-order
        # recovery before it starts. The full sweep alone needs one total
        # read/network/apply deadline.
        deadline_monotonic=full_deadline or scheduler_deadline,
    )

    def _run_pass_with_lock_retry(label: str, fn):
        return _run_recovery_pass_with_lock_policy(
            label,
            fn,
            scope=scope,
            summary=summary,
            deadline_monotonic=apply_deadline,
        )

    def _client_pass(
        label, pass_fn, summary_key, *,
        advanced_key="advanced", fold_stayed=True, client_kw=False, **pass_kwargs,
    ):
        """Run a client-taking pass as snapshot -> (shared) network -> apply.

        ``client_kw=True`` passes the venue snapshot as the ``client=`` keyword
        (the projection-repair passes' signature), else positionally.
        """

        def _snapshot(conn):
            # The candidate rows the apply pass re-queries are already primed in
            # the shared venue snapshot; this phase satisfies the contract's
            # open/close discipline and confirms no conn leaks into the network.
            return None

        def _network(_snap):
            return venue_snapshot

        def _apply(conn, snap_client):
            if client_kw:
                ps = pass_fn(conn, client=snap_client, **pass_kwargs)
            else:
                ps = pass_fn(conn, snap_client, **pass_kwargs)
            _accumulate(summary, summary_key, ps, advanced_key=advanced_key, fold_stayed=fold_stayed)
            return ps

        return _run_pass_with_lock_retry(
            label,
            lambda: run_three_phase(
                _snapshot, _network, _apply,
                conn_factory=apply_conn_factory,
                snapshot_conn_factory=read_conn_factory,
                label=f"recovery.{label}",
            ),
        )

    def _db_pass(label, pass_fn, summary_key, *, advanced_key="advanced", fold_stayed=True, **pass_kwargs):
        def _apply(conn):
            ps = pass_fn(conn, **pass_kwargs)
            _accumulate(summary, summary_key, ps, advanced_key=advanced_key, fold_stayed=fold_stayed)
            return ps

        return _run_pass_with_lock_retry(
            label,
            lambda: run_db_only_pass(
                _apply,
                conn_factory=apply_conn_factory,
                label=f"recovery.{label}",
            ),
        )

    def _post_submit_unknown_absence_fast_pass():
        """Record no-command post-submit unknowns as intentionally fail-closed.

        This pass is intentionally ahead of capture_venue_read_snapshot(). The
        aggregate it fixes has no venue_commands row, so the broad priming set
        has no order id to look up and can spend minutes on unrelated historical
        order reads. It performs no network read and no mutation because account
        snapshot absence cannot authorize replay after the submit boundary.
        """

        def _snapshot(conn):
            return _edli_post_submit_unknown_absence_candidates(conn)

        def _network(rows):
            return rows, None, None

        def _apply(conn, payload):
            rows, open_read, trade_read = payload
            if not rows:
                ps = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
            else:
                ps = _apply_edli_post_submit_unknown_absence(
                    conn,
                    rows,
                    open_read,
                    trade_read,
                )
            _accumulate(summary, "edli_post_submit_unknown_absence_fast", ps)
            return ps

        return _run_pass_with_lock_retry(
            "edli_post_submit_unknown_absence_fast",
            lambda: run_three_phase(
                _snapshot,
                _network,
                _apply,
                conn_factory=apply_conn_factory,
                snapshot_conn_factory=read_conn_factory,
                label="recovery.edli_post_submit_unknown_absence_fast",
            ),
        )

    def _full_priority_inflight_fast_pass() -> bool:
        """Resolve one unknown submit before unrelated full-sweep work."""

        if scope != "full":
            return False
        with open_tracked(
            read_conn_factory,
            label="recovery.full_priority_inflight_fast:snapshot",
        ) as conn:
            priming = _collect_recovery_priming_keys(conn, scope="full")
        command_id = str(priming.get("full_priority_inflight_command_id") or "")
        if not command_id:
            return False

        assert_no_open_connection("recovery.full_priority_inflight_fast")
        snapshot = capture_venue_read_snapshot(
            client,
            **_scheduled_venue_snapshot_kwargs(
                "full",
                priming,
                deadline_monotonic=full_deadline,
            ),
        )
        priority_apply_deadline = time.monotonic() + (
            _capital_recovery_db_budget_seconds()
        )
        priority_writer_factory = _recovery_priority_conn_factory(
            default_trade_conn_factory,
            scope="live_tick",
            deadline_monotonic=priority_apply_deadline,
        )
        priority_apply_factory = _recovery_apply_conn_factory(
            priority_writer_factory,
            scope="full",
            deadline_monotonic=priority_apply_deadline,
            monitor_preemptible=False,
        )

        def _apply(conn, snap_client):
            current = conn.execute(
                """
                SELECT * FROM venue_commands
                 WHERE command_id = ?
                   AND state IN (?, ?)
                """,
                (
                    command_id,
                    CommandState.UNKNOWN.value,
                    CommandState.SUBMIT_UNKNOWN_SIDE_EFFECT.value,
                ),
            ).fetchone()
            rows = [_dict_row(current)] if current is not None else []
            result = {"scanned": len(rows), "advanced": 0, "stayed": 0, "errors": 0}
            for row in rows:
                try:
                    outcome = _reconcile_row(
                        conn,
                        VenueCommand.from_row(row),
                        snap_client,
                    )
                except Exception as exc:  # noqa: BLE001 - retain durable continuation.
                    logger.error(
                        "recovery: priority inflight command %s failed: %s",
                        command_id,
                        exc,
                    )
                    result["errors"] += 1
                    continue
                if outcome in {"advanced", "stayed"}:
                    result[outcome] += 1
                else:
                    result["errors"] += 1
            summary["scanned"] = result["scanned"]
            summary["advanced"] += result["advanced"]
            summary["stayed"] += result["stayed"]
            summary["errors"] += result["errors"]
            return result

        _run_recovery_pass_with_lock_policy(
            "full_priority_inflight_apply",
            lambda: run_three_phase(
                lambda conn: None,
                lambda _snap: snapshot,
                _apply,
                conn_factory=priority_apply_factory,
                snapshot_conn_factory=read_conn_factory,
                label="recovery.full_priority_inflight_fast",
            ),
            scope="full",
            summary=summary,
            deadline_monotonic=priority_apply_deadline,
            bounded_lock_retry_delays=_CAPITAL_RECOVERY_LOCK_RETRY_DELAYS,
        )
        summary["full_priority_inflight_only"] = True
        summary["inflight_quantum"] = command_id
        summary["inflight_quantum_remaining"] = bool(
            priming.get("full_priority_inflight_quantum_remaining")
        )
        summary["scope"] = scope
        summary["deferred_full_sweep"] = True
        return True

    def _capital_recovery_fast_pass():
        """Resolve capital-blocking terminal orders before maintenance.

        The general live-tick sweep has a deliberately tiny cumulative DB
        budget.  A large maintenance query must not repeatedly consume that
        budget before command-specific terminal facts can release collateral.
        Venue reads remain bounded to the currently affected order ids and run
        with no DB connection open.
        """
        capital_budget = _capital_recovery_db_budget_seconds()

        def _capital_deadline() -> float:
            return _bounded_recovery_deadline(
                scheduler_deadline,
                capital_budget,
            )

        def _run_capital_pass(label: str, fn, *, deadline_monotonic: float):
            return _run_recovery_pass_with_lock_policy(
                label,
                fn,
                scope="live_tick",
                summary=summary,
                deadline_monotonic=deadline_monotonic,
                bounded_lock_retry_delays=_CAPITAL_RECOVERY_LOCK_RETRY_DELAYS,
            )

        def _capital_apply_conn_factory(
            deadline_monotonic: float,
            *,
            cross_db: bool = False,
        ):
            """Bind exact capital APPLY work to its own fresh writer deadline.

            The ordinary live-tick factory is bound to the cumulative 100 ms
            maintenance budget before this fast lane starts.  Re-wrapping that
            factory with a later deadline cannot revive its already-expired
            inner writer lease.  These passes are trade-owned and already have
            their own bounded capital deadline, so build the priority lease from
            the canonical trade-only base unless the pass also projects WORLD
            truth.  A cross-DB pass must retain the sanctioned WORLD+TRADE
            connection so its complete atomic write set can commit.
            """

            base_factory = conn_factory if cross_db else capital_conn_factory
            priority_factory = _recovery_priority_conn_factory(
                base_factory,
                scope="live_tick",
                deadline_monotonic=deadline_monotonic,
            )
            return _recovery_apply_conn_factory(
                priority_factory,
                scope="live_tick",
                deadline_monotonic=deadline_monotonic,
                # These passes own already-terminal venue/fill truth and are
                # bounded by their dedicated capital deadline.  Once their
                # RECOVERY_CRITICAL lease is acquired, let that short atomic
                # projection/release finish instead of repeatedly aborting it
                # for a continuously queued monitor writer.  Acquisition still
                # yields to a monitor that already owns the coordinator gate.
                monitor_preemptible=False,
            )

        identity_submit_deferred = 0
        with open_tracked(
            read_conn_factory,
            label="recovery.capital_recovery_fast:snapshot",
        ) as conn:
            terminal_fill_review_command_ids = {
                str(row.get("command_id") or "")
                for row in _bounded_authenticated_entry_trade_fact_candidates(
                    conn,
                    states=(CommandState.REVIEW_REQUIRED.value,),
                )
                if str(row.get("state") or "")
                == CommandState.REVIEW_REQUIRED.value
            }
            terminal_entry_projection_command_ids = tuple(
                command_id
                for command_id in (
                    _terminal_filled_entry_projection_blocker_command_ids(conn)
                )
                if command_id not in terminal_fill_review_command_ids
            )
            identity_submit_candidates, identity_submit_deferred = (
                _identity_bound_submitting_candidates(conn)
            )
            exit_fill_projection_command_ids = (
                _terminal_filled_exit_projection_blocker_command_ids(conn)
            )
            exit_fill_projection_open = bool(exit_fill_projection_command_ids) or (
                _recorded_exit_fill_projection_candidates(conn)
            )
            cancel_candidates = _capital_blocking_cancel_commands(conn)
            terminal_late_fill_command_ids = (
                _exchange_reconcile.persisted_terminal_late_entry_fill_command_ids(
                    conn
                )
            )
        terminal_fill_review_result = None
        if terminal_fill_review_command_ids:
            # This is already-authenticated current exposure, not historical
            # maintenance. Give the exact command-bound fold its own capital
            # deadline before any venue read or broad recovery query can spend
            # the cumulative live-tick budget.
            review_deadline = _capital_deadline()
            review_conn_factory = _capital_apply_conn_factory(review_deadline)

            def _fold_terminal_fill_reviews(conn):
                folded = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
                for command_id in sorted(terminal_fill_review_command_ids):
                    result = reconcile_authenticated_entry_trade_facts(
                        conn,
                        command_id=command_id,
                    )
                    for key in folded:
                        folded[key] += int(result.get(key, 0) or 0)
                return folded

            terminal_fill_review_result = _run_capital_pass(
                "authenticated_terminal_fill_review_fast",
                lambda: run_db_only_pass(
                    _fold_terminal_fill_reviews,
                    conn_factory=review_conn_factory,
                    label="recovery.authenticated_terminal_fill_review_fast",
                ),
                deadline_monotonic=review_deadline,
            )
            if terminal_fill_review_result is not None:
                _accumulate(
                    summary,
                    "authenticated_terminal_fill_review_fast",
                    terminal_fill_review_result,
                )
        terminal_entry_projection_result = None
        if terminal_entry_projection_command_ids:
            # A FILLED command with authenticated trade truth but no matching
            # position event/execution fact is current exposure, not historical
            # repair. Process only the exact blocker identities before monitor
            # traffic or a broad recovery scan can consume this tick.
            entry_projection_deadline = _capital_deadline()
            entry_projection_conn_factory = _capital_apply_conn_factory(
                entry_projection_deadline
            )

            def _fold_terminal_entry_projections(conn):
                folded = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
                for command_id in terminal_entry_projection_command_ids:
                    result = reconcile_authenticated_entry_trade_facts(
                        conn,
                        command_id=command_id,
                    )
                    for key in folded:
                        folded[key] += int(result.get(key, 0) or 0)
                return folded

            terminal_entry_projection_result = _run_capital_pass(
                "authenticated_terminal_entry_projection_fast",
                lambda: run_db_only_pass(
                    _fold_terminal_entry_projections,
                    conn_factory=entry_projection_conn_factory,
                    label=(
                        "recovery."
                        "authenticated_terminal_entry_projection_fast"
                    ),
                ),
                deadline_monotonic=entry_projection_deadline,
            )
            if terminal_entry_projection_result is not None:
                _accumulate(
                    summary,
                    "authenticated_terminal_entry_projection_fast",
                    terminal_entry_projection_result,
                )
        exit_fill_result = None
        if exit_fill_projection_open:
            # A confirmed EXIT fill is already executable capital truth.
            # Project it before the cumulative maintenance budget starts:
            # otherwise an older broad repair can consume every live tick and
            # leave a sold position falsely exposed indefinitely.
            exit_fill_deadline = _capital_deadline()
            exit_fill_conn_factory = _capital_apply_conn_factory(
                exit_fill_deadline
            )
            exit_fill_result = _run_capital_pass(
                "recorded_exit_fill_projection_fast",
                lambda: run_db_only_pass(
                    lambda conn: _exchange_reconcile.reconcile_recorded_exit_fill_projections(
                        conn,
                        observed_at=started_at,
                        command_ids=exit_fill_projection_command_ids or None,
                    ),
                    conn_factory=exit_fill_conn_factory,
                    label="recovery.recorded_exit_fill_projection_fast",
                ),
                deadline_monotonic=exit_fill_deadline,
            )
            if exit_fill_result is not None:
                _accumulate(
                    summary,
                    "recorded_exit_fill_projection_fast",
                    exit_fill_result,
                    advanced_key="projected",
                    fold_stayed=False,
                )
        # The selectors below include historical terminal-order joins.  Keep
        # them behind the exact confirmed-fill projections above: on a large
        # canonical DB, a deadline interrupt in one broad selector must not
        # prevent already-known current-capital command ids from reaching
        # their bounded APPLY transaction.
        with open_tracked(
            read_conn_factory,
            label="recovery.capital_recovery_fast:maintenance_snapshot",
        ) as conn:
            terminal_candidates = _terminal_point_order_candidates(conn)
            terminal_fact_candidates = _latest_terminal_order_fact_candidates(conn)
            existing_position_terminal_cancel_ids = (
                _existing_position_terminal_no_fill_cancel_command_ids(
                    conn,
                    terminal_fact_candidates,
                )
            )
            cancel_candidates = [
                candidate
                for candidate in cancel_candidates
                if str(candidate.get("command_id") or "")
                not in existing_position_terminal_cancel_ids
            ]
            terminal_fact_candidates = [
                candidate
                for candidate in terminal_fact_candidates
                if str(candidate.get("command_id") or "")
                not in existing_position_terminal_cancel_ids
            ]
            stale_terminal_finding_candidates = (
                _stale_local_orphan_terminal_no_fill_candidates(conn)
            )
            if cancel_candidates:
                # Exact cancel uncertainty globally removes entry authority.
                # Do not spend its bounded tick on the broader historical
                # partial-remainder scan; that debt remains durable and gets
                # its own pass as soon as the cancel set drains.
                partial_candidates = []
                summary["partial_remainder_scan_deferred_for_cancel"] = True
            else:
                partial_candidates = (
                    _partial_remainder_candidates(
                        conn,
                        live_tick_scope=True,
                    )
                    if all(
                        _table_exists(conn, table)
                        for table in (
                            "venue_commands",
                            "venue_order_facts",
                            "position_current",
                        )
                    )
                    else []
                )
            obligation_states = tuple(
                sorted(
                    _TERMINAL_ENTRY_NO_FILL_COMMAND_STATES
                    | _SETTLEMENT_ABSORBED_ENTRY_COMMAND_STATES
                    | {CommandState.PARTIAL.value}
                )
            )
            terminal_obligation_open = bool(
                _table_exists(conn, "entry_exposure_obligations")
                and conn.execute(
                    f"""
                    SELECT 1
                      FROM entry_exposure_obligations obligation
                      JOIN venue_commands command
                        ON command.command_id = obligation.command_id
                     WHERE obligation.status = 'OPEN'
                       AND command.intent_kind = 'ENTRY'
                       AND command.state IN (
                           {','.join('?' for _ in obligation_states)}
                       )
                     LIMIT 1
                    """,
                    obligation_states,
                ).fetchone()
            )
        existing_position_terminal_cancel_result = None
        if existing_position_terminal_cancel_ids:
            terminal_cancel_deadline = _capital_deadline()
            terminal_cancel_conn_factory = _capital_apply_conn_factory(
                terminal_cancel_deadline,
            )
            existing_position_terminal_cancel_result = _run_capital_pass(
                "existing_position_terminal_no_fill_cancels_fast",
                lambda: run_db_only_pass(
                    lambda conn: reconcile_existing_position_terminal_no_fill_cancels(
                        conn,
                        command_ids=existing_position_terminal_cancel_ids,
                    ),
                    conn_factory=terminal_cancel_conn_factory,
                    label=(
                        "recovery."
                        "existing_position_terminal_no_fill_cancels_fast"
                    ),
                ),
                deadline_monotonic=terminal_cancel_deadline,
            )
            if existing_position_terminal_cancel_result is not None:
                _accumulate(
                    summary,
                    "existing_position_terminal_no_fill_cancels_fast",
                    existing_position_terminal_cancel_result,
                )
        preexisting_terminal_result = None
        if terminal_fact_candidates:
            # User/REST ingest can persist VENUE_WIPED before this sweep reads
            # the prior LIVE fact.  That removes the command from the point-read
            # candidate set, so project the already-durable terminal truth before
            # any venue I/O or historical fill maintenance can consume the tick.
            terminal_fact_deadline = _capital_deadline()
            terminal_fact_conn_factory = _capital_apply_conn_factory(
                terminal_fact_deadline,
                # reconcile_terminal_order_facts releases TRADE capital and
                # projects WORLD EDLI lifecycle in one sanctioned transaction.
                # SCOPE: this exact already-terminal command/fact pair.
                # DRAIN: the dedicated cross-DB writer lease commits both
                # projections atomically. RESET: the terminal command state and
                # released reservation remove the candidate on the next scan.
                cross_db=True,
            )
            preexisting_terminal_result = _run_capital_pass(
                "terminal_order_facts_fast",
                lambda: run_db_only_pass(
                    lambda conn: reconcile_terminal_order_facts(
                        conn,
                        collect_continuations=True,
                        # SCOPE: this exact already-terminal command/fact pair.
                        # DRAIN: commit command/projection truth under the
                        # dedicated capital deadline before any forecast work.
                        # RESET: the returned continuation is emitted by main's
                        # post-recovery redecision bridge after the DB commit.
                        emit_immediate_redecision=False,
                    ),
                    conn_factory=terminal_fact_conn_factory,
                    label="recovery.terminal_order_facts_fast",
                ),
                deadline_monotonic=terminal_fact_deadline,
            )
            if preexisting_terminal_result is not None:
                _accumulate(
                    summary,
                    "terminal_order_facts",
                    preexisting_terminal_result,
                )
        stale_terminal_finding_result = None
        if stale_terminal_finding_candidates:
            # These findings already carry an identity-bound terminal no-fill
            # fact.  They globally force the allocator into reduce-only, so
            # reset them from durable truth before any venue or historical
            # maintenance work can consume the live-tick budget.
            finding_deadline = _capital_deadline()
            finding_conn_factory = _capital_apply_conn_factory(
                finding_deadline,
            )
            stale_terminal_finding_result = _run_capital_pass(
                "stale_terminal_no_fill_findings_fast",
                lambda: run_db_only_pass(
                    reconcile_stale_terminal_no_fill_findings,
                    conn_factory=finding_conn_factory,
                    label="recovery.stale_terminal_no_fill_findings_fast",
                ),
                deadline_monotonic=finding_deadline,
            )
            if stale_terminal_finding_result is not None:
                _accumulate(
                    summary,
                    "stale_terminal_no_fill_findings_fast",
                    stale_terminal_finding_result,
                )
        if identity_submit_deferred:
            summary["identity_bound_inflight_deferred"] = identity_submit_deferred
        terminal_late_fill_result = None
        if terminal_late_fill_command_ids:
            late_fill_deadline = _capital_deadline()
            late_fill_conn_factory = _capital_apply_conn_factory(
                late_fill_deadline,
            )
            terminal_late_fill_result = _run_capital_pass(
                "terminal_late_entry_fill_fast",
                lambda: run_db_only_pass(
                    _exchange_reconcile.reconcile_persisted_terminal_late_entry_fills,
                    conn_factory=late_fill_conn_factory,
                    label="recovery.terminal_late_entry_fill_fast",
                ),
                deadline_monotonic=late_fill_deadline,
            )
            if terminal_late_fill_result is not None:
                _accumulate(
                    summary,
                    "terminal_late_entry_fill_fast",
                    terminal_late_fill_result,
                )
        preexisting_obligation_result = None
        if terminal_obligation_open:
            obligation_deadline = _capital_deadline()
            obligation_conn_factory = _capital_apply_conn_factory(
                obligation_deadline,
            )

            def _materialize_and_release_terminal_entry_obligations(conn):
                """Materialize terminal entry facts and release capital atomically."""

                no_fill = reconcile_cancel_ack_terminal_no_fill_facts(conn)
                partial = reconcile_cancel_ack_terminal_partial_facts(conn)
                obligations = reconcile_terminal_entry_exposure_obligations(conn)
                return {
                    "no_fill": no_fill,
                    "partial": partial,
                    "obligations": obligations,
                }

            terminal_obligation_bundle = _run_capital_pass(
                "terminal_entry_exposure_obligations_fast",
                lambda: run_db_only_pass(
                    _materialize_and_release_terminal_entry_obligations,
                    conn_factory=obligation_conn_factory,
                    label="recovery.terminal_entry_exposure_obligations_fast",
                ),
                deadline_monotonic=obligation_deadline,
            )
            if terminal_obligation_bundle is not None:
                _accumulate(
                    summary,
                    "cancel_ack_terminal_no_fill_facts_fast",
                    terminal_obligation_bundle["no_fill"],
                )
                _accumulate(
                    summary,
                    "cancel_ack_terminal_partial_facts_fast",
                    terminal_obligation_bundle["partial"],
                )
                preexisting_obligation_result = terminal_obligation_bundle[
                    "obligations"
                ]
                _accumulate(
                    summary,
                    "terminal_entry_exposure_obligations_fast",
                    preexisting_obligation_result,
                )
        identity_submit_command_ids = {
            str(row.get("command_id") or "")
            for row in identity_submit_candidates
        }
        identity_submit_order_ids = {
            str(row.get("venue_order_id") or "")
            for row in identity_submit_candidates
            if str(row.get("venue_order_id") or "")
        }
        identity_result = None
        if identity_submit_candidates:
            # Do not require account-wide truth here.  This lane accepts only
            # a response that repeats the command's already-persisted order id;
            # unavailable/NOT_FOUND responses remain durable continuations.
            assert_no_open_connection("recovery.identity_bound_inflight_fast")
            assert scheduler_deadline is not None
            identity_network_deadline = _bounded_recovery_deadline(
                scheduler_deadline,
                _identity_bound_point_read_budget_seconds(),
            )
            point_read_budget = max(
                0.0,
                identity_network_deadline - time.monotonic(),
            )
            if point_read_budget <= 0.0:
                raw_point_orders, point_read_timed_out = {}, True
            else:
                raw_point_orders, point_read_timed_out = (
                    _read_identity_bound_point_orders(
                        identity_submit_order_ids,
                        timeout_seconds=point_read_budget,
                    )
                )
            if point_read_timed_out:
                summary["identity_bound_inflight_point_read_timed_out"] = True
            point_orders = {
                venue_order_id: point_order
                for venue_order_id, point_order in raw_point_orders.items()
                if _identity_bound_positive_point_order(
                    point_order,
                    venue_order_id=venue_order_id,
                )
            }
            identity_apply_deadline = _capital_deadline()
            identity_conn_factory = _capital_apply_conn_factory(
                identity_apply_deadline,
            )
            identity_result = _run_capital_pass(
                "identity_bound_inflight_fast",
                lambda: run_three_phase(
                    lambda conn: None,
                    lambda _snap: point_orders,
                    lambda conn, orders: _reconcile_identity_bound_submitting_commands(
                        conn,
                        command_ids=identity_submit_command_ids,
                        point_orders=orders,
                    ),
                    conn_factory=identity_conn_factory,
                    snapshot_conn_factory=read_conn_factory,
                    label="recovery.identity_bound_inflight_fast",
                ),
                deadline_monotonic=identity_apply_deadline,
            )
            if identity_result is not None:
                _accumulate(summary, "identity_bound_inflight_fast", identity_result)
            summary["identity_bound_inflight_priority_active"] = True
            identity_advanced = int(
                (identity_result or {}).get("advanced", 0) or 0
            ) > 0
            other_capital_candidates = bool(
                cancel_candidates or terminal_candidates or partial_candidates
            )
            if identity_advanced or not other_capital_candidates:
                # A bounded exact-order continuation is the live-tick contract.
                # Defer account-wide and historical reads, but never let an
                # unavailable submit consume the only turn of independent
                # cancel/terminal capital release work.
                return (
                    terminal_fill_review_result
                    or exit_fill_result
                    or existing_position_terminal_cancel_result
                    or preexisting_terminal_result
                    or identity_result
                    or terminal_late_fill_result
                    or preexisting_obligation_result
                )
            summary["identity_bound_inflight_yielded_to_other_capital"] = True
        if not cancel_candidates and not terminal_candidates and not partial_candidates:
            return (
                terminal_fill_review_result
                or exit_fill_result
                or existing_position_terminal_cancel_result
                or preexisting_terminal_result
                or stale_terminal_finding_result
                or terminal_late_fill_result
                or preexisting_obligation_result
            )
        cancel_command_ids = {
            str(row.get("command_id") or "") for row in cancel_candidates
        }
        order_ids = {
            str(row.get("venue_order_id") or "")
            for row in cancel_candidates + terminal_candidates + partial_candidates
            if str(row.get("venue_order_id") or "")
        }
        assert_no_open_connection("recovery.capital_recovery_fast")
        assert scheduler_deadline is not None
        snapshot = capture_venue_read_snapshot(
            client,
            **_scheduled_venue_snapshot_kwargs(
                "live_tick",
                {
                    "order_ids": order_ids,
                    "idempotency_keys": set(),
                    "condition_ids": set(),
                },
                deadline_monotonic=scheduler_deadline,
            ),
        )
        fast_deadline = _capital_deadline()
        # Bind the writer-lease deadline after venue truth is captured.  The
        # ordinary live-tick deadline is intentionally tiny and may already be
        # spent by NETWORK; reusing it here makes the capital fast lane
        # structurally unable to reach APPLY.
        fast_conn_factory = _capital_apply_conn_factory(fast_deadline)

        def _apply_cancel(conn, snap_client):
            ps = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
            current = {
                str(row.get("command_id") or ""): row
                for row in _capital_blocking_cancel_commands(conn)
            }
            for command_id in sorted(cancel_command_ids):
                row = current.get(command_id)
                if row is None:
                    continue
                ps["scanned"] += 1
                try:
                    outcome = _reconcile_row(
                        conn,
                        VenueCommand.from_row(row),
                        snap_client,
                    )
                except Exception as exc:  # noqa: BLE001 - one command must not block peers.
                    logger.error(
                        "recovery: priority cancel-race command %s failed: %s",
                        command_id,
                        exc,
                    )
                    ps["errors"] += 1
                    continue
                if outcome == "advanced":
                    ps["advanced"] += 1
                elif outcome == "stayed":
                    ps["stayed"] += 1
                else:
                    ps["errors"] += 1
            return ps

        cancel_result = None
        if cancel_candidates:
            cancel_result = _run_capital_pass(
                "cancel_recovery_fast",
                lambda: run_three_phase(
                    lambda conn: None,
                    lambda _snap: snapshot,
                    _apply_cancel,
                    conn_factory=fast_conn_factory,
                    snapshot_conn_factory=read_conn_factory,
                    label="recovery.cancel_recovery_fast",
                ),
                deadline_monotonic=fast_deadline,
            )
            if cancel_result is not None:
                _accumulate(summary, "cancel_recovery_fast", cancel_result)

        partial_result = None
        if partial_candidates:
            partial_result = _run_capital_pass(
                "partial_remainder_recovery_fast",
                lambda: run_three_phase(
                    lambda conn: None,
                    lambda _snap: snapshot,
                    lambda conn, snap_client: reconcile_partial_remainders(
                        conn,
                        snap_client,
                        updated_before=started_at,
                        live_tick_scope=True,
                    ),
                    conn_factory=fast_conn_factory,
                    snapshot_conn_factory=read_conn_factory,
                    label="recovery.partial_remainder_recovery_fast",
                ),
                deadline_monotonic=fast_deadline,
            )
            if partial_result is not None:
                _accumulate(
                    summary,
                    "partial_remainder_recovery_fast",
                    partial_result,
                )

        obligation_result = _run_capital_pass(
            "terminal_entry_exposure_obligations_fast",
            lambda: run_db_only_pass(
                reconcile_terminal_entry_exposure_obligations,
                conn_factory=fast_conn_factory,
                label="recovery.terminal_entry_exposure_obligations_fast",
            ),
            deadline_monotonic=fast_deadline,
        )
        if obligation_result is not None:
            _accumulate(
                summary,
                "terminal_entry_exposure_obligations_fast",
                obligation_result,
            )

        terminal_result = None
        if terminal_candidates:
            terminal_result = _run_capital_pass(
                "terminal_point_recovery_fast",
                lambda: run_three_phase(
                    lambda conn: None,
                    lambda _snap: snapshot,
                    reconcile_restart_preflight_terminal_point_orders,
                    conn_factory=fast_conn_factory,
                    snapshot_conn_factory=read_conn_factory,
                    label="recovery.terminal_point_recovery_fast",
                ),
                deadline_monotonic=fast_deadline,
            )
            if terminal_result is not None:
                _accumulate(
                    summary,
                    "terminal_point_recovery_fast",
                    terminal_result,
                )
        return (
            terminal_fill_review_result
            or exit_fill_result
            or existing_position_terminal_cancel_result
            or preexisting_terminal_result
            or stale_terminal_finding_result
            or terminal_late_fill_result
            or preexisting_obligation_result
            or cancel_result
            or partial_result
            or obligation_result
            or terminal_result
        )

    def _entry_posterior_recovery_fast_pass():
        """Restore decision-time q after capital-release work, before maintenance.

        A broad live-tick budget is allowed to expire after the priority capital
        release lane.  A filled position's immutable q is also money-path truth,
        so first prove that repair work exists with a read connection, then give
        only that bounded local write its own short deadline.
        """

        with open_tracked(
            read_conn_factory,
            label="recovery.edli_entry_posterior_projection_repair_fast:snapshot",
        ) as conn:
            if not _edli_entry_posterior_repair_candidates(conn):
                return None
        fast_deadline = _bounded_recovery_deadline(
            scheduler_deadline,
            live_tick_budget,
        )
        fast_conn_factory = _recovery_apply_conn_factory(
            conn_factory,
            scope="live_tick",
            deadline_monotonic=fast_deadline,
        )
        lane_summary: dict = {}
        result = _run_recovery_pass_with_lock_policy(
            "edli_entry_posterior_projection_repair_fast",
            lambda: run_db_only_pass(
                reconcile_edli_entry_posterior_projection_repairs,
                conn_factory=fast_conn_factory,
                label="recovery.edli_entry_posterior_projection_repair_fast",
            ),
            scope="live_tick",
            summary=lane_summary,
            deadline_monotonic=fast_deadline,
        )
        if lane_summary:
            summary["edli_entry_posterior_projection_repair_fast_defer"] = dict(
                lane_summary
            )
            for prefix in ("db_lock_deferred", "db_budget_deferred"):
                if not lane_summary.get(prefix):
                    continue
                for key, value in lane_summary.items():
                    if key.startswith(prefix):
                        summary.setdefault(key, value)
        if result is not None:
            _accumulate(
                summary,
                "edli_entry_posterior_projection_repair_fast",
                result,
            )
        return result

    if scope == "boot_fast":
        # Boot recovery must not perform account-wide or per-order venue reads.
        # Live evidence 2026-06-28 showed the pre-scheduler "boot_fast" path
        # spending minutes inside capture_venue_read_snapshot(get_order * N),
        # which prevented the scheduler, reactor, redecision screen, Day0, and
        # exit monitor from starting. Keep boot to local, already-durable facts
        # that can release impossible locks; the scheduled live_tick sweep owns
        # venue-backed reconciliation once the live loop is running.
        raw_budget = os.environ.get("ZEUS_BOOT_FAST_RECOVERY_BUDGET_SECONDS", "8.0")
        try:
            boot_budget_s = max(0.0, float(raw_budget))
        except (TypeError, ValueError):
            logger.warning(
                "recovery.boot_fast: invalid ZEUS_BOOT_FAST_RECOVERY_BUDGET_SECONDS=%r; using 8.0",
                raw_budget,
            )
            boot_budget_s = 8.0
        boot_started_monotonic = time.monotonic()
        boot_deadline = boot_started_monotonic + boot_budget_s
        boot_deferred: list[str] = []
        boot_defer_reasons: dict[str, str] = {}
        summary["boot_fast_budget_seconds"] = boot_budget_s

        def _defer_boot_pass(label: str, reason: str) -> None:
            if label not in boot_deferred:
                boot_deferred.append(label)
            boot_defer_reasons[label] = reason
            summary["boot_fast_deferred_passes"] = list(boot_deferred)
            summary["boot_fast_defer_reasons"] = dict(boot_defer_reasons)
            summary["boot_fast_deferred"] = True
            if reason.startswith("budget_"):
                summary["boot_fast_budget_exhausted"] = True
            logger.warning(
                "recovery.boot_fast: deferred pass=%s reason=%s elapsed_s=%.3f budget_s=%.3f",
                label,
                reason,
                time.monotonic() - boot_started_monotonic,
                boot_budget_s,
            )

        def _boot_conn_factory() -> sqlite3.Connection:
            if getattr(conn_factory, "supports_nonblocking_flocks", False):
                conn = conn_factory(blocking=False, busy_timeout_ms=0)
            else:
                conn = conn_factory()
            remaining_s = max(0.0, boot_deadline - time.monotonic())
            # Default trade connections wait up to 30s for BEGIN IMMEDIATE.
            # Boot-fast runs before the scheduler exists, so its lock wait must
            # not block before this SQLite timeout can even be installed.
            conn.execute("PRAGMA busy_timeout = %d" % max(1, int(remaining_s * 1000)))
            return conn

        def _boot_db_pass(
            label,
            pass_fn,
            summary_key,
            *,
            advanced_key="advanced",
            fold_stayed=True,
            **pass_kwargs,
        ):
            remaining_s = boot_deadline - time.monotonic()
            if remaining_s <= 0:
                _defer_boot_pass(label, "budget_exhausted_before_pass")
                return None
            logger.info(
                "recovery.boot_fast: starting pass=%s remaining_s=%.3f",
                label,
                remaining_s,
            )

            def _apply(conn):
                def _interrupt_if_deadline_exceeded() -> int:
                    return 1 if time.monotonic() >= boot_deadline else 0

                conn.set_progress_handler(_interrupt_if_deadline_exceeded, 20_000)
                try:
                    ps = pass_fn(conn, **pass_kwargs)
                    _accumulate(
                        summary,
                        summary_key,
                        ps,
                        advanced_key=advanced_key,
                        fold_stayed=fold_stayed,
                    )
                    return ps
                finally:
                    conn.set_progress_handler(None, 0)

            try:
                return run_db_only_pass(
                    _apply,
                    conn_factory=_boot_conn_factory,
                    label=f"recovery.{label}",
                )
            except WriteLeaseTimeout:
                _defer_boot_pass(label, "database_locked_before_scheduler")
                return None
            except BlockingIOError as exc:
                if (
                    "db_writer_lock(" not in str(exc)
                    or "contended on" not in str(exc)
                ):
                    raise
                _defer_boot_pass(label, "database_locked_before_scheduler")
                return None
            except sqlite3.OperationalError as exc:
                msg = str(exc).lower()
                if "interrupted" in msg:
                    _defer_boot_pass(label, "budget_exhausted_during_pass")
                    return None
                if "database is locked" in msg:
                    _defer_boot_pass(label, "database_locked_before_scheduler")
                    return None
                raise
            finally:
                summary["boot_fast_elapsed_seconds"] = round(
                    time.monotonic() - boot_started_monotonic,
                    3,
                )
                logger.info(
                    "recovery.boot_fast: finished pass=%s elapsed_s=%.3f remaining_s=%.3f",
                    label,
                    time.monotonic() - boot_started_monotonic,
                    max(0.0, boot_deadline - time.monotonic()),
                )

        # A terminal SELL underfill is current held collateral, not historical
        # maintenance. Project its exact residual before any broad ENTRY scan can
        # consume boot's finite DB turn.
        _boot_db_pass(
            "terminal_exit_residual_projection_priority",
            lambda conn: reconcile_exit_lifecycle_alignment_repairs(
                conn,
                terminal_partial_limit=_TERMINAL_EXIT_RESIDUAL_PRIORITY_MAX_CANDIDATES,
                terminal_partial_only=True,
                terminal_residual_only=True,
            ),
            "terminal_exit_residual_projection_priority",
        )

        # RiskGuard requires fill-grade portfolio rows to name their durable
        # execution_fact provenance.  Repair that narrow, already-confirmed
        # truth before broader maintenance can consume the boot budget; without
        # it one partial fill can keep all new entries DATA_DEGRADED after a
        # restart even though venue and position facts are already canonical.
        _boot_db_pass(
            "missing_filled_entry_execution_fact_repair",
            reconcile_missing_filled_entry_execution_fact_repairs,
            "missing_filled_entry_execution_fact_repair",
        )
        _boot_db_pass(
            "edli_entry_posterior_projection_repair",
            reconcile_edli_entry_posterior_projection_repairs,
            "edli_entry_posterior_projection_repair",
        )
        _boot_db_pass(
            "completed_partial_order_facts",
            reconcile_completed_partial_order_facts,
            "completed_partial_order_facts",
        )
        _boot_db_pass(
            "authenticated_entry_trade_fact",
            reconcile_authenticated_entry_trade_facts,
            "authenticated_entry_trade_fact",
        )
        _boot_db_pass(
            "edli_confirmed_legacy_command_repair",
            reconcile_edli_confirmed_legacy_command_repairs,
            "edli_confirmed_legacy_command_repair",
        )
        _boot_db_pass(
            "stale_intent_created_no_submit",
            reconcile_stale_intent_created_no_submit,
            "stale_intent_created_no_submit",
            updated_before=started_at,
        )
        _boot_db_pass(
            "abandoned_unsubmitted_ghosts",
            reconcile_abandoned_unsubmitted_ghosts,
            "abandoned_unsubmitted_ghosts",
            updated_before=started_at,
        )
        _boot_db_pass(
            "review_required_exit_mutex_release",
            reconcile_review_required_exit_mutex_releases,
            "review_required_exit_mutex_release",
        )
        _boot_db_pass(
            "cancel_ack_terminal_no_fill_facts",
            reconcile_cancel_ack_terminal_no_fill_facts,
            "cancel_ack_terminal_no_fill_facts",
        )
        _boot_db_pass(
            "cancel_ack_terminal_partial_facts",
            reconcile_cancel_ack_terminal_partial_facts,
            "cancel_ack_terminal_partial_facts",
        )
        _boot_db_pass(
            "terminal_order_facts",
            reconcile_terminal_order_facts,
            "terminal_order_facts",
            collect_continuations=True,
        )
        _boot_db_pass(
            "stale_terminal_no_fill_findings",
            reconcile_stale_terminal_no_fill_findings,
            "stale_terminal_no_fill_findings",
        )
        _boot_db_pass(
            "edli_acknowledged_venue_command_sync",
            reconcile_edli_acknowledged_venue_command_sync,
            "edli_acknowledged_venue_command_sync",
        )
        _boot_db_pass(
            "edli_rejected_venue_command_sync",
            reconcile_edli_rejected_venue_command_sync,
            "edli_rejected_venue_command_sync",
        )
        _boot_db_pass(
            "live_entry_projection_repair",
            reconcile_live_entry_projection_repairs,
            "live_entry_projection_repair",
        )
        _boot_db_pass(
            "filled_entry_projection_repair",
            reconcile_filled_entry_projection_repairs,
            "filled_entry_projection_repair",
        )
        _boot_db_pass(
            "filled_entry_execution_fact_repair",
            reconcile_filled_entry_execution_fact_repairs,
            "filled_entry_execution_fact_repair",
        )
        _boot_db_pass(
            "terminal_entry_exposure_obligations",
            reconcile_terminal_entry_exposure_obligations,
            "terminal_entry_exposure_obligations",
        )
        _boot_db_pass(
            "hard_terminal_position_projection_repair",
            reconcile_hard_terminal_position_projection_repairs,
            "hard_terminal_position_projection_repair",
        )
        _boot_db_pass(
            "confirmed_phantom_void_repair",
            repair_confirmed_phantom_voids,
            "confirmed_phantom_void_repair",
        )
        _boot_db_pass(
            "confirmed_chain_absence_projection_repair",
            repair_confirmed_chain_absence_positive_projections,
            "confirmed_chain_absence_projection_repair",
        )
        from src.execution.exchange_reconcile import reconcile_recorded_exit_fill_projections

        _boot_db_pass(
            "recorded_exit_fill_projection",
            reconcile_recorded_exit_fill_projections,
            "recorded_exit_fill_projection",
            advanced_key="projected",
            fold_stayed=False,
            observed_at=started_at,
        )
        _boot_db_pass(
            "exit_pending_projections",
            reconcile_exit_pending_projections,
            "exit_pending_projections",
        )
        _boot_db_pass(
            "matched_cancel_review_required_entries",
            reconcile_matched_cancel_review_required_entries,
            "matched_cancel_review_required_entries",
            fold_stayed=False,
        )
        _boot_db_pass(
            "terminal_positive_entry_projection_repair",
            reconcile_terminal_positive_entry_projection_repairs,
            "terminal_positive_entry_projection_repair",
        )
        _boot_db_pass(
            "exit_lifecycle_alignment_repair",
            reconcile_exit_lifecycle_alignment_repairs,
            "exit_lifecycle_alignment_repair",
        )
        _boot_db_pass(
            "complete_exit_trade_fact_commands",
            reconcile_complete_exit_trade_fact_commands,
            "complete_exit_trade_fact_commands",
        )
        _boot_db_pass(
            "filled_exit_trade_fact_tx_repair",
            reconcile_filled_exit_trade_fact_tx_repairs,
            "filled_exit_trade_fact_tx_repair",
        )

        abandoned_ghosts = summary.get("abandoned_unsubmitted_ghosts")
        abandoned_continuations = (
            list(abandoned_ghosts.get("continuations") or [])
            if isinstance(abandoned_ghosts, dict)
            else []
        )
        terminal_order_facts = summary.get("terminal_order_facts")
        terminal_continuations = (
            list(terminal_order_facts.get("continuations") or [])
            if isinstance(terminal_order_facts, dict)
            else []
        )
        if terminal_continuations or abandoned_continuations:
            summary["terminal_no_fill_continuations"] = (
                terminal_continuations + abandoned_continuations
            )
        summary["scope"] = scope
        summary["venue_snapshot_deferred"] = True
        summary["deferred_full_sweep"] = True
        return

    if _full_priority_inflight_fast_pass():
        return

    if scope == "live_tick":
        _capital_recovery_fast_pass()
        _entry_posterior_recovery_fast_pass()

    # A confirmed trade already persisted for a REVIEW_REQUIRED submit is the
    # narrowest unresolved capital truth: it resolves known exposure and releases
    # the allocator's systemic-unknown latch without venue I/O. Run it before the
    # broader authenticated-entry projection scan; that scan can consume the
    # whole live-tick DB budget on historical rows.
    _db_pass(
        "review_required_matched_submit_trade_fact",
        reconcile_review_required_matched_submit_trade_facts,
        "review_required_matched_submit_trade_fact",
    )

    # Confirmed fills are current exposure truth. They outrank absence proofs:
    # if the bounded live-tick DB budget expires, an abandoned command may keep
    # one family reserved for another minute, but a filled command must not stay
    # invisible to risk, monitoring, and capital accounting.
    _db_pass(
        "authenticated_entry_trade_fact",
        reconcile_authenticated_entry_trade_facts,
        "authenticated_entry_trade_fact",
    )

    if scope == "live_tick":
        # Recorded trade facts are already local capital truth.  Reproject
        # their exact economics before any account-wide venue snapshot so a
        # timeout/quota failure cannot leave wealth and Kelly on rounded REST
        # top-line prices.
        from src.execution.exchange_reconcile import (
            reconcile_recorded_maker_fill_economics,
        )

        _db_pass(
            "recorded_maker_fill_economics",
            reconcile_recorded_maker_fill_economics,
            "recorded_maker_fill_economics",
            advanced_key="corrected",
            fold_stayed=False,
            observed_at=started_at,
            live_tick_scope=True,
        )

    if scope == "live_tick":
        # Submit-time MATCHED facts are durable current exit truth, but the
        # recorded-fill pass correctly reserves MATCHED/MINED for already
        # closed projections. Reconcile command-bound full EXIT fills before
        # lower-priority maintenance so they cannot wait for a full sweep.
        _db_pass(
            "exit_lifecycle_alignment_repair",
            reconcile_exit_lifecycle_alignment_repairs,
            "exit_lifecycle_alignment_repair",
        )
        _db_pass(
            "recovered_partial_exit_economics",
            reconcile_recovered_partial_exit_economics,
            "recovered_partial_exit_economics",
            observed_at=started_at,
        )

    if scope == "restart_preflight":
        # Consume already-durable terminal venue truth before account/network
        # snapshot work. SCOPE is the exact command/order fact identity. DRAIN
        # is this preflight DB pass. RESET is CANCEL_ACKED/EXPIRED plus the
        # returned continuation; main redecides the family after restart.
        _db_pass(
            "terminal_order_facts",
            reconcile_terminal_order_facts,
            "terminal_order_facts",
            collect_continuations=True,
            emit_immediate_redecision=False,
        )

    if scope == "live_tick":
        # An aggregate abandoned at ExecutionCommandCreated holds a RESERVED
        # live-cap row and blocks its whole weather family. The absence proof is
        # still ahead of general maintenance, after positive exposure has been
        # projected.
        _db_pass(
            "abandoned_unsubmitted_ghosts",
            reconcile_abandoned_unsubmitted_ghosts,
            "abandoned_unsubmitted_ghosts",
            updated_before=started_at,
        )

    _db_pass(
        "review_required_exit_mutex_release",
        reconcile_review_required_exit_mutex_releases,
        "review_required_exit_mutex_release",
    )

    if scope in {"restart_preflight", "live_tick"}:
        _db_pass(
            "completed_partial_order_facts",
            reconcile_completed_partial_order_facts,
            "completed_partial_order_facts",
        )

    if scope == "live_tick":
        # Command-bound fills and terminal partials are current collateral
        # truth.  SCOPE is one OPEN obligation with its own command-bound fact;
        # DRAIN is canonical fill repair followed by the obligation reducer;
        # RESET is fact convergence and obligation RESOLVED on this cadence.
        _db_pass(
            "open_entry_obligation_execution_fact_repair",
            reconcile_open_entry_obligation_execution_fact_repairs,
            "open_entry_obligation_execution_fact_repair",
        )
        # A command with no fact still uses the stricter missing-fact proof.
        # Consume both before historical projection maintenance so a broad
        # repair query cannot strand spendable capital behind them.
        _db_pass(
            "missing_filled_entry_execution_fact_repair",
            reconcile_missing_filled_entry_execution_fact_repairs,
            "missing_filled_entry_execution_fact_repair",
        )

    if scope == "live_tick":
        _post_submit_unknown_absence_fast_pass()
    if scope == "live_tick":
        # These passes consume facts that are already durable in zeus_trades.
        # Run them before the venue snapshot so one slow CLOB point-order read
        # cannot keep zero-exposure pending entries or duplicate locks alive.
        from src.execution.exchange_reconcile import reconcile_recorded_exit_fill_projections

        _db_pass(
            "recorded_exit_fill_projection",
            reconcile_recorded_exit_fill_projections,
            "recorded_exit_fill_projection",
            advanced_key="projected",
            fold_stayed=False,
            observed_at=started_at,
        )
        _db_pass(
            "cancel_ack_terminal_no_fill_facts",
            reconcile_cancel_ack_terminal_no_fill_facts,
            "cancel_ack_terminal_no_fill_facts",
        )
        _db_pass(
            "cancel_ack_terminal_partial_facts",
            reconcile_cancel_ack_terminal_partial_facts,
            "cancel_ack_terminal_partial_facts",
        )
        _db_pass(
            "terminal_entry_exposure_obligations",
            reconcile_terminal_entry_exposure_obligations,
            "terminal_entry_exposure_obligations",
        )
        _db_pass(
            "matched_cancel_review_required_entries",
            reconcile_matched_cancel_review_required_entries,
            "matched_cancel_review_required_entries",
            fold_stayed=False,
        )
        # Capital releases consume durable facts and must outrun the expensive
        # terminal-order sweep within the live-tick DB budget.
        _db_pass(
            "terminal_order_facts",
            reconcile_terminal_order_facts,
            "terminal_order_facts",
            collect_continuations=True,
        )
        _db_pass(
            "closed_shift_bin_exit_leases",
            release_closed_shift_bin_exit_leases,
            "closed_shift_bin_exit_leases",
            observed_at=started_at,
        )
        _db_pass(
            "stale_rebalance_entry_leases",
            release_stale_rebalance_entry_leases,
            "stale_rebalance_entry_leases",
            observed_at=started_at,
        )

        if (
            summary.get("db_lock_deferred")
            or summary.get("db_budget_deferred")
            or (
                live_tick_deadline is not None
                and time.monotonic() >= live_tick_deadline
            )
        ):
            if (
                not summary.get("db_lock_deferred")
                and not summary.get("db_budget_deferred")
            ):
                summary["db_budget_deferred"] = True
                summary["db_budget_deferred_at"] = "venue_snapshot"
                summary["db_budget_deferred_count"] = 1
            summary["scope"] = scope
            summary["deferred_full_sweep"] = True
            return

    if scope == "live_tick" and summary.get("identity_bound_inflight_priority_active"):
        # Keep bounded DB-only capital drains fair even when one submit point
        # read is permanently unavailable, then defer all account-wide and
        # historical venue reads to the full sweep.
        summary["scope"] = scope
        summary["venue_snapshot_deferred"] = True
        summary["deferred_full_sweep"] = True
        return

    # -- PHASE 1: SNAPSHOT (collect priming keys on an independent RO connection)
    # ``restart_preflight`` may be called without a scheduler deadline.  It
    # still gets a hard priming bound so a historical CTE cannot pin recovery
    # indefinitely before the first APPLY lease is attempted.
    priming_deadline = scheduler_deadline
    if priming_deadline is None:
        priming_deadline = time.monotonic() + (
            _RESTART_ACCOUNT_TRUTH_DEADLINE_SECONDS
            if scope == "restart_preflight"
            else scheduled_recovery_budget_seconds()
        )
    priming_state: dict[str, str] = {}
    try:
        with _open_recovery_priming_read_connection(
            read_conn_factory,
            deadline_monotonic=priming_deadline,
            preempt_callback=_recovery_priming_monitor_preempt_requested,
            state=priming_state,
        ) as conn:
            priming = _collect_recovery_priming_keys(conn, scope=scope)
    except _LiveTickDBBudgetExhausted:
        summary["db_budget_deferred"] = True
        summary["db_budget_deferred_at"] = "priming_snapshot"
        summary["db_budget_deferred_count"] = 1
        summary["scope"] = scope
        summary["deferred_full_sweep"] = True
        return
    except sqlite3.OperationalError as exc:
        if priming_state.get("reason") == "monitor_preempted":
            summary["monitor_preempted"] = True
            summary["monitor_preempted_at"] = "priming_snapshot"
            summary["db_lock_deferred"] = True
            summary["db_lock_deferred_at"] = "priming_snapshot"
            summary["db_lock_deferred_count"] = 1
            summary["scope"] = scope
            summary["deferred_full_sweep"] = True
            return
        if priming_state.get("reason") == "deadline":
            summary["db_budget_deferred"] = True
            summary["db_budget_deferred_at"] = "priming_snapshot"
            summary["db_budget_deferred_count"] = 1
            summary["scope"] = scope
            summary["deferred_full_sweep"] = True
            return
        if (
            "interrupted" in str(exc).lower()
            and time.monotonic() >= priming_deadline
        ):
            summary["db_budget_deferred"] = True
            summary["db_budget_deferred_at"] = "priming_snapshot"
            summary["db_budget_deferred_count"] = 1
            summary["scope"] = scope
            summary["deferred_full_sweep"] = True
            return
        if (
            apply_deadline is None
            or (
                "locked" not in str(exc).lower()
                and "interrupted" not in str(exc).lower()
            )
        ):
            raise
        summary["db_lock_deferred"] = True
        summary["db_lock_deferred_at"] = "priming_snapshot"
        summary["db_lock_deferred_count"] = 1
        summary["scope"] = scope
        summary["deferred_full_sweep"] = True
        return

    # -- PHASE 2: NETWORK (no connection in scope) -----------------------------
    assert_no_open_connection("recovery.capture_venue_snapshot")
    snapshot_kwargs = _scheduled_venue_snapshot_kwargs(
        scope,
        priming,
        deadline_monotonic=scheduler_deadline,
    )
    venue_snapshot = capture_venue_read_snapshot(
        client,
        **snapshot_kwargs,
    )

    # -- PHASE 3: APPLY (each pass on its own short bounded write connection) ---
    priority_command_id = str(
        priming.get("full_priority_inflight_command_id") or ""
    )
    if scope == "full" and priority_command_id:
        # Apply the exact side-effect truth immediately after its dedicated
        # NETWORK snapshot. Running unrelated legacy/projection maintenance
        # first allowed monitor preemption to discard a completed account read
        # and strand the capital-blocking command for another cadence.
        def _apply_full_priority_inflight(conn, snap_client):
            current = conn.execute(
                """
                SELECT * FROM venue_commands
                 WHERE command_id = ?
                   AND state IN (?, ?)
                """,
                (
                    priority_command_id,
                    CommandState.UNKNOWN.value,
                    CommandState.SUBMIT_UNKNOWN_SIDE_EFFECT.value,
                ),
            ).fetchone()
            rows = [_dict_row(current)] if current is not None else []
            result = {"scanned": len(rows), "advanced": 0, "stayed": 0, "errors": 0}
            for row in rows:
                try:
                    outcome = _reconcile_row(
                        conn,
                        VenueCommand.from_row(row),
                        snap_client,
                    )
                except Exception as exc:  # noqa: BLE001 - durable continuation on error.
                    logger.error(
                        "recovery: priority inflight command %s failed: %s",
                        priority_command_id,
                        exc,
                    )
                    result["errors"] += 1
                    continue
                if outcome in {"advanced", "stayed"}:
                    result[outcome] += 1
                else:
                    result["errors"] += 1
            summary["scanned"] = result["scanned"]
            summary["advanced"] += result["advanced"]
            summary["stayed"] += result["stayed"]
            summary["errors"] += result["errors"]
            summary["inflight_quantum"] = priority_command_id
            return result

        priority_apply_deadline = time.monotonic() + (
            _capital_recovery_db_budget_seconds()
        )
        priority_writer_factory = _recovery_priority_conn_factory(
            default_trade_conn_factory,
            # An unresolved submit is current unknown capital exposure, not
            # historical maintenance. Give it the same typed priority as the
            # live capital lane while retaining the full-sweep deadline.
            scope="live_tick",
            deadline_monotonic=priority_apply_deadline,
        )
        priority_apply_conn_factory = _recovery_apply_conn_factory(
            priority_writer_factory,
            scope="full",
            deadline_monotonic=priority_apply_deadline,
            # Acquisition still yields to an existing monitor owner/waiter.
            # Once acquired, this exact command/reservation transition is a
            # short atomic capital release and must finish before yielding.
            monitor_preemptible=False,
        )
        _run_pass_with_lock_retry(
            "full_priority_inflight_apply",
            lambda: run_three_phase(
                lambda conn: None,
                lambda _snap: venue_snapshot,
                _apply_full_priority_inflight,
                conn_factory=priority_apply_conn_factory,
                snapshot_conn_factory=read_conn_factory,
                label="recovery.full_priority_inflight_apply",
            ),
        )
        summary["full_priority_inflight_only"] = True
        summary["inflight_quantum_remaining"] = bool(
            priming.get("full_priority_inflight_quantum_remaining")
        )
        summary["scope"] = scope
        summary["deferred_full_sweep"] = True
        return

    # Order mirrors the legacy inline body exactly.
    _db_pass("edli_confirmed_legacy_command_repair",
             reconcile_edli_confirmed_legacy_command_repairs,
             "edli_confirmed_legacy_command_repair")

    _db_pass("stale_intent_created_no_submit",
             reconcile_stale_intent_created_no_submit,
             "stale_intent_created_no_submit",
             updated_before=started_at)

    _db_pass("abandoned_unsubmitted_ghosts",
             reconcile_abandoned_unsubmitted_ghosts,
             "abandoned_unsubmitted_ghosts",
             updated_before=started_at)

    # In-flight per-row scan (find_unresolved_commands + _reconcile_row).
    def _scan_inflight(conn, snap_client):
        ps = {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
        if scope == "restart_preflight":
            rows = _restart_preflight_unresolved_commands(conn)
        elif scope == "full":
            rows = _full_quantum_candidates(conn)
        else:
            rows = find_unresolved_commands(conn)
        if scope == "full":
            all_rows = rows
            rows = all_rows[:1]
            if len(all_rows) > 1:
                summary["inflight_quantum_remaining"] = True
            summary["inflight_quantum"] = (
                str(rows[0].get("command_id") or "") if rows else None
            )
        ps["scanned"] = len(rows)
        for row in rows:
            try:
                cmd = VenueCommand.from_row(row)
            except Exception as exc:
                logger.error(
                    "recovery: malformed row (command_id=%r): %s; skipping",
                    row.get("command_id"), exc,
                )
                ps["errors"] += 1
                continue
            outcome = _reconcile_row(conn, cmd, snap_client)
            if outcome == "advanced":
                ps["advanced"] += 1
            elif outcome == "stayed":
                ps["stayed"] += 1
            else:
                ps["errors"] += 1
        return ps

    def _apply_inflight(conn, snap_client):
        ps = _scan_inflight(conn, snap_client)
        summary["scanned"] = ps["scanned"]
        summary["advanced"] += ps["advanced"]
        summary["stayed"] += ps["stayed"]
        summary["errors"] += ps["errors"]
        return ps

